window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0217", [{"word":"replicate","ipa_uk":"/ˈreplɪkeɪt/","ipa_us":"/ˈreplɪkeɪt/","definition_zh":"复制；重复（实验或研究）；重现（结果）；自我复制；折叠回折（书面古义）；答复（古义）；重复实验中的一次平行试验","definition_en":"to make an exact copy of something, or to repeat an experiment or process so as to obtain the same result","core_image":"一枚半透明的模子扣在原件上，压出的纹路与原件分毫不差，连凹痕的深浅都一样","scene":"实验室换了另一批人，却仍照着原来的步骤把同一项研究从头做了一遍。A second team tried to replicate the study with fresh samples.","sceneCN":"这里指把同一项研究再做一遍，看能否得到一致的结果（第 2 个义项：重复实验）；句意为另一个团队用新的样本重复了这项研究。场景图取象：模子压出的纹路与原件一模一样。","pos":[{"tag":"v.","zh":"复制；重现；重复（实验）"},{"tag":"v.","zh":"自我复制（细胞、遗传物质层面）"},{"tag":"v.","zh":"（书面）折叠回折；答复（古义）"},{"tag":"n.","zh":"重复实验中的一次平行试验（统计学用语）"}],"collocations":[{"phrase":"replicate a study","zh":"重复一项研究"},{"phrase":"replicate the results","zh":"重现结果"},{"phrase":"replicate itself","zh":"自我复制"},{"phrase":"replicate an experiment","zh":"重复实验"},{"phrase":"replicate the success","zh":"复制成功经验"},{"phrase":"replicate data","zh":"复制数据"},{"phrase":"fail to replicate","zh":"未能重现"}],"forms":[{"label":"原形","form":"replicate"},{"label":"第三人称单数","form":"replicates"},{"label":"过去式","form":"replicated"},{"label":"过去分词","form":"replicated"},{"label":"现在分词","form":"replicating"},{"label":"名词（过程）","form":"replication"},{"label":"形容词（可复制的）","form":"replicable"},{"label":"名词（复制品）","form":"replica"},{"label":"名词（复制者）","form":"replicator"}],"derivatives":[{"word":"replication","pos":"n.","zh":"复制；重复实验；自我复制（由动词加表示「行为、过程」的拉丁后缀构成，指动作本身或一次复现）"},{"word":"replica","pos":"n.","zh":"复制品；仿制品（由拉丁词干加表示「成品」的名词后缀构成，从「折回之物」转为「照原样做出的东西」）"},{"word":"replicable","pos":"adj.","zh":"可复制的；可重复的（加表示「能够被……」的形容词后缀，指结果别人也做得出来）"},{"word":"replicability","pos":"n.","zh":"可重复性（在可重复的形容词后加表示「性质」的名词后缀，科学界用来衡量结果能否被他人复现）"},{"word":"replicative","pos":"adj.","zh":"复制性的；与复制有关的（加表示「属于、倾向于」的形容词后缀，多用于描述细胞或病毒的复制活动）"},{"word":"replicator","pos":"n.","zh":"复制者；复制装置（加表示「施动者」的名词后缀，指执行复制的主体或仪器）"},{"word":"replicon","pos":"n.","zh":"复制子（分子生物学用语，指能独立复制的一段遗传物质，由复制一词加表示「单位」的后缀构成）"}],"senses":[{"no":"01","title":"Make an exact copy","titleCN":"做出分毫不差的副本","definition":"to produce an exact copy of a thing, so that the copy matches the original in every detail","definitionCN":"精确地复制某物，使副本与原件的每一处细节都相同","example":"The workshop can replicate a carved panel that broke off a century ago.","exampleCN":"这家工坊能复制一块一个世纪前断裂的雕花板。","why":"The Latin verb meant to fold back, and folding a sheet back over its source traces the same line twice.","whyCN":"这个拉丁动词本义为折回；把一张纸沿原样折回叠在源头上，等于把同一条线描了第二遍。"},{"no":"02","title":"Run the study again","titleCN":"把研究再做一遍","definition":"to repeat an experiment or study in order to see whether the same result appears","definitionCN":"把一项实验或研究再做一次，以检验能否得到相同的结果","example":"No other laboratory could replicate the finding.","exampleCN":"没有其他实验室能重现这一发现。","why":"Repeating a procedure is going over it again, which the fold image captures: the same line, drawn a second time.","whyCN":"重复一套程序就是把它再走一遍，折回的意象正好对应：同一条线，再描第二次。"},{"no":"03","title":"Copy itself","titleCN":"自我复制","definition":"to make copies of itself, as genetic material or a cell does before division","definitionCN":"自身制造副本，如遗传物质或细胞在分裂前所做的那样","example":"The virus replicates inside the host cell.","exampleCN":"病毒在宿主细胞内自我复制。","why":"Molecular biology borrowed the word because a strand that copies itself repeats its own sequence exactly.","whyCN":"分子生物学借用了这个词，因为一条链复制自身时，把自己的序列原样重复了一遍。"},{"no":"04","title":"Carry a result into a new setting","titleCN":"把结果搬到新环境里重现","definition":"to reproduce a result, pattern or success in a different place or under different conditions","definitionCN":"在不同的地点或条件下再现某一结果、模式或成功经验","example":"The school tried to replicate its reading programme in three rural districts.","exampleCN":"这所学校试着把它的阅读课程推广到三个乡村学区。","why":"If a pattern holds in a new place, the second case repeats the first like a fold laid over it.","whyCN":"如果一个模式在新地方照样成立，第二个例子就像一层折过来盖住第一个。"},{"no":"05","title":"Copy data to another system","titleCN":"把数据复制到另一套系统","definition":"to copy data continuously or on demand from one store to another so that both stay identical","definitionCN":"把数据持续或按需从一个存储位置复制到另一处，使两边保持一致","example":"The database replicates every record to a backup server.","exampleCN":"这个数据库把每条记录都复制到备份服务器上。","why":"Computing keeps the oldest sense: an exact duplicate kept somewhere else against loss.","whyCN":"计算机领域保留了最古老的含义：在别处留一份一模一样的副本，以防丢失。"},{"no":"06","title":"Fold back, as a leaf","titleCN":"（叶片等）向后折","definition":"to fold back on itself, as a leaf edge, petal or membrane does","definitionCN":"自身向后折转，如叶缘、花瓣或膜片所做的那样","example":"The petals replicate at the tip and form a small hood.","exampleCN":"花瓣在尖端向后折，形成一个小小的兜状结构。","why":"This is the literal Latin sense, still used in botanical and anatomical description.","whyCN":"这是拉丁语本义，至今仍用于植物学与解剖学的形态描述。"},{"no":"07","title":"Answer, in older usage","titleCN":"（古义）答复","definition":"to reply or answer, a sense common in older English and in diplomacy","definitionCN":"回答、答复；这是旧时英语与外交文书中的常见用法","example":"The envoy replicated that the terms were refused.","exampleCN":"使节答复说这些条件已被拒绝。","why":"The same Latin verb also meant to reply, because answering turns the question back toward the asker.","whyCN":"同一个拉丁动词也有答复之义，因为回答就是把问题朝提问者转回去。"},{"no":"08","title":"One repeated run","titleCN":"一次平行试验","definition":"one of several repeated runs or samples in an experiment, treated as a unit for analysis","definitionCN":"实验中若干次重复操作或样本之一，作为分析时的一个单位","example":"Each replicate was measured at a different temperature.","exampleCN":"每一次平行试验都在不同的温度下测量。","why":"Statistics turned the verb into a noun for a single repeat among several, so the count could be discussed.","whyCN":"统计学把这个动词变成名词，指若干重复中的一次，好把次数说清楚。"},{"no":"09","title":"Reproduce a work of art","titleCN":"把一件作品照样做出来","definition":"to reproduce a painting, object or design as a faithful copy for study, display or replacement","definitionCN":"把绘画、器物或设计照原样复制出来，用于研究、陈列或替换原件","example":"Students replicated the fresco on a smaller panel.","exampleCN":"学生们在一块较小的板上复制了那幅壁画。","why":"Museums and craftsmen use the word for stand-in copies that carry the look of the original.","whyCN":"博物馆与工匠用这个词指代用品，它承袭了原件的样子。"}],"etymology":{"intro":{"en":"Replicate goes back to Latin replicare, built from re- 'back' and plicare 'to fold'. The chain of form and meaning is clear, though the exact century in which each English sense appeared is less certain.","cn":"replicate 可追溯至拉丁语 replicare，由表示「向后」的前缀与表示「折叠」的词根构成。词形与词义的链条清楚，只是各个英语义项出现的确切年代较难确定。"},"items":[{"era":"LATIN REPLICARE","en":"Replicare meant to fold back, to turn a thing over, and from that to go over something again.","cn":"replicare 意为折回、翻转某物，由此引申为把某事再过一遍。"},{"era":"THE FOLDING ROOT","en":"The root plicare also built complicate, explicit, imply, duplicity and supple, all through the image of folding or plaiting.","cn":"词根 plicare 还构成 complicate、explicit、imply、duplicity 与 supple，全都经由折叠或编织的意象。"},{"era":"ANSWER AS TURNING BACK","en":"Because a reply turns a question back to the asker, replicare also took the sense of answering, which English kept as a rare older use.","cn":"回答是把问题朝提问者转回去，replicare 因此也有答复之义，英语保留了这一罕见的旧用法。"},{"era":"ENGLISH ENTRY","en":"The word came into English through learned Latin in the fifteenth and sixteenth centuries, first describing folded leaves and membranes.","cn":"这个词在十五、十六世纪经由学术拉丁语进入英语，最初用来描述折转的叶片与膜片。"},{"era":"REPEAT AND COPY","en":"The modern senses of repeating an experiment and of making a copy are nineteenth-century developments, pushed by laboratory practice and printing.","cn":"重复实验与制作副本这两个现代义项是十九世纪的发展，由实验室实践与印刷需求推动。"},{"era":"REPLICATION CRISIS","en":"In the twenty-first century replication became a public word, as whole fields argued over which published results could be reproduced.","cn":"二十一世纪，replication 成了公共词汇，因为多个学科都在争论哪些已发表的结果能够被重现。"}]},"similar":{"note":{"en":"The first group shares the Latin folding root or looks close; the second group names the practical acts that stand beside replicate.","cn":"第一组或共享拉丁语折叠词根，或字形相近；第二组是实践中与「复制、重复」相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"replica","ipa":"/ˈreplɪkə/","tag":"same root","definition":"A copy of an object, especially one made to look exactly like the original.","definitionCN":"器物的复制品，尤指外观与原件完全相同者。"},{"word":"replication","ipa":"/ˌreplɪˈkeɪʃn/","tag":"same root","definition":"The act or process of copying, or a single repeat of an experiment.","definitionCN":"复制的行为或过程，也指实验的一次重复。"},{"word":"duplicate","ipa":"/ˈdjuːplɪkeɪt/","tag":"same folding root","definition":"To make a second copy; built on the same folding root with the idea of two.","definitionCN":"做出第二份；同用折叠词根，只是取「二」之意。"},{"word":"complicate","ipa":"/ˈkɒmplɪkeɪt/","tag":"same folding root","definition":"To make something harder by adding parts; literally to fold everything together.","definitionCN":"因加入部分而变复杂；字面即把所有东西折在一起。"},{"word":"implicate","ipa":"/ɪmˈplɪkeɪt/","tag":"same folding root","definition":"To involve someone in a matter, literally to fold a person into it.","definitionCN":"使人牵连其中，字面即把人折进去。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reproduce","ipa":"/ˌriːprəˈdjuːs/","tag":"near meaning","definition":"To produce a copy or to bring a result back into existence, the broad everyday verb.","definitionCN":"造出副本或使结果再次出现，是最宽泛的日常说法。"},{"word":"copy","ipa":"/ˈkɒpi/","tag":"near meaning","definition":"To make something identical, the plain word that needs no method behind it.","definitionCN":"照原样做出相同之物，最朴素、不含方法意味的词。"},{"word":"repeat","ipa":"/rɪˈpiːt/","tag":"near meaning","definition":"To do or say again, without the suggestion of checking a result.","definitionCN":"再做或再说一遍，不含检验结果的意思。"},{"word":"confirm","ipa":"/kənˈfɜːm/","tag":"near meaning","definition":"To establish that something is true, the purpose behind repeating a study.","definitionCN":"确证某事为真，正是重复研究的用意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin folding root, the real word family and real fixed phrases.","cn":"正常联想使用真实的拉丁语折叠词根、真实同族词与真实固定搭配。"},"normal":[{"en":"Re- means back and plicare means fold, so replicate is literally to fold a thing back onto itself.","cn":"前缀意为向后，词根意为折叠，合起来就是把它折回自身。"},{"en":"The folding root also built complicate and imply, so the family is one image with different directions.","cn":"折叠词根还造出 complicate 与 imply，同族词是同一意象的不同走向。"},{"en":"Botany still says a petal replicates, using the literal sense of folding back.","cn":"植物学至今仍说花瓣向后折，用的就是折回的本义。"},{"en":"Fixed phrases mark the science: replicate a study, replicate the results, fail to replicate.","cn":"固定说法标出科研用途：重复一项研究、重现结果、未能重现。"},{"en":"The noun replicate counts one repeated run, and the noun replication names the whole act.","cn":"名词 replicate 指一次重复，名词 replication 指整个复制行为。"}],"abstract":[{"en":"To replicate is to insist that the same thing can happen twice, which is the wager of every experiment.","cn":"复制就是坚持同一件事能够发生第二次，这正是每次实验押下的赌注。"},{"en":"The second copy is never quite the same object, only the same shape pressed again.","cn":"第二份从来不是同一个物件，只是同一形状又被压了一次。"},{"en":"A result that cannot be folded back onto itself stays a story rather than a finding.","cn":"无法折回自身重现的结果，只能算一个说法，算不得发现。"}]},"examples":[{"en":"Her team replicated the survey in two other provinces.","cn":"她的团队在另外两个省重复了这项调查。"},{"en":"A printed page can be replicated down to the grain of the paper.","cn":"一页印刷品能复制到连纸纹都一致的程度。"},{"en":"Cells replicate their DNA before they divide.","cn":"细胞在分裂前先复制自己的遗传物质。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑞普利凯特」——把原件照原样再压一遍，压出来的就是副本：复制、重复","word":"replicate"},"root":"拉丁语 replicare「折回、翻转」← re-「向后」＋ plicare「折叠」；同根词有 complicate、explicit、imply、duplicity、supple。古义含「答复」，今义「重复实验」「复制」为十九世纪以后的扩展，各义项确切年代不确定。","sensesIntro":{"en":"Nine senses trace one fold: an exact copy, a repeated study, a cell copying itself, a result carried to a new place, data copied to a second store, a leaf folded back, an old reply, one repeated run, and a copy of a work of art.","cn":"九个义项沿着同一次折叠展开：分毫不差的副本、重复的研究、细胞的自我复制、被搬到新环境的结果、复制到另一处的数据、向后折的叶片、旧时的答复、一次平行试验，以及艺术品的照样复制。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mould pressed onto an original, leaving the same lines in a second material.","cn":"核心意象：一枚模子扣在原件上，在另一种材料里留下同样的纹路。"},"chain":["FOLD BACK","GO OVER AGAIN","ANSWER","REPEAT A TEST","MAKE A COPY","COPY ITSELF"],"branches":[{"senses":"01 · 09","en":"THE COPY: a second version made to match a thing or a work of art detail for detail.","cn":"副本：照着原物或艺术品逐处做出的第二份。"},{"senses":"02 · 08","en":"THE REPEATED RUN: the procedure is gone through again, once or several times, to see whether the result holds.","cn":"重复的运行：把程序再走一遍或几遍，看结果是否站得住。"},{"senses":"03","en":"THE SELF-COPY: a cell or a strand of genetic material makes its own duplicate.","cn":"自我复制：细胞或遗传物质链制造自己的副本。"},{"senses":"04","en":"THE CARRIED PATTERN: a result or success is reproduced in another place and still holds.","cn":"被带走的花样：结果或成功经验在另一处再现而仍然成立。"},{"senses":"05 · 06 · 07","en":"THE FOLD, THE DATA AND THE OLD REPLY: the literal folded leaf, the duplicate kept on another server, and the archaic answer.","cn":"折叶、数据与旧日答复：字面意义上向后折的叶片、存在另一台服务器上的副本，以及古老的答复之义。"}]},"affixes":{"intro":{"en":"Replicate is a Latin verb of folding; its parts are still productive in English and its derived nouns carry the laboratory sense.","cn":"replicate 是一个表示折叠的拉丁动词，其构件在英语中仍有构词力，派生名词则带上实验室里的含义。"},"latinIntro":{"en":"The Latin verb replicare is the direct source, with the prefix re- and the root plicare visible in related English words.","cn":"拉丁动词 replicare 是直接来源，前缀与词根在相关英语词中仍看得见。"},"items":[{"word":"replicate","structure":"Latin replicare, past participle replicatus","meaning":"to fold back; to repeat","meaningCN":"折回；重复","example":"The verb carries both the fold and the repeat.","exampleCN":"这个动词同时带着折叠与重复两层意思。"},{"word":"re-","structure":"Latin prefix","meaning":"back, again","meaningCN":"向后；再次","example":"It marks a movement back toward the starting point.","exampleCN":"它标出朝起点折返的动作。"},{"word":"plicare","structure":"Latin verb root","meaning":"to fold, to plait","meaningCN":"折叠；编织","example":"The root supplies the physical image behind the word.","exampleCN":"这个词根提供词语背后的具体意象。"},{"word":"replication","structure":"replicate plus -ion (act or process)","meaning":"the act of copying or repeating","meaningCN":"复制或重复的行为","example":"The suffix turns the verb into the name of a process.","exampleCN":"后缀把动词变成过程之名。"},{"word":"replica","structure":"Italian replica, from Latin replicare","meaning":"a copy of an object","meaningCN":"器物的复制品","example":"The noun names the finished copy rather than the act.","exampleCN":"这个名词指做成的副本，而非动作。"},{"word":"replicable","structure":"replicate plus -able (can be)","meaning":"able to be copied or repeated","meaningCN":"可复制、可重复的","example":"The adjective is central to debates about trustworthy science.","exampleCN":"这个形容词在关于科学可信度的争论中处于中心。"},{"word":"replicability","structure":"replicable plus -ity (quality)","meaning":"the quality of being repeatable","meaningCN":"可重复性","example":"The noun names the standard a result must meet.","exampleCN":"这个名词指结果必须达到的标准。"},{"word":"replicative","structure":"replicate plus -ive (tending to)","meaning":"relating to copying","meaningCN":"与复制有关的","example":"Biology uses it for the copying phase of a cell.","exampleCN":"生物学用它指细胞的复制阶段。"},{"word":"replicator","structure":"replicate plus -or (agent)","meaning":"a thing that copies","meaningCN":"执行复制者","example":"The suffix marks the doer or the device.","exampleCN":"后缀标出执行者或装置。"}],"latinEntries":[{"word":"replicare","structure":"re- (back, again) + plicare (fold)","meaning":"to fold back; to repeat; to reply","meaningCN":"折回；重复；答复","example":"Latin replicare means to fold back, and later to reply.","exampleCN":"拉丁语 replicare 意为折回，后来又指答复。"},{"word":"plicare","structure":"Latin verb plicare (plic-, plicatum; to fold)","meaning":"to fold, to plait","meaningCN":"折叠；编织","example":"Latin plicare means to fold, and gives complicate and explicit.","exampleCN":"拉丁语 plicare 意为折叠，并给出 complicate 与 explicit。"},{"word":"re-","structure":"Latin prefix re- (back, again)","meaning":"back, again","meaningCN":"向后；再次","example":"Latin re- appears in reducere, to lead back.","exampleCN":"拉丁语 re- 见于 reducere（引回）。"}],"derivatives":[{"word":"replication","pos":"n.","zh":"复制；重复实验；自我复制"},{"word":"replica","pos":"n.","zh":"复制品；仿制品"},{"word":"replicable","pos":"adj.","zh":"可复制、可重复的"},{"word":"replicability","pos":"n.","zh":"可重复性"},{"word":"replicative","pos":"adj.","zh":"复制性的"},{"word":"replicator","pos":"n.","zh":"复制者；复制装置"},{"word":"replicon","pos":"n.","zh":"复制子（独立复制单位）"}]}},{"word":"verification","ipa_uk":"/ˌverɪfɪˈkeɪʃn/","ipa_us":"/ˌverəfəˈkeɪʃn/","definition_zh":"核实；验证；查证；确认；证明为真；身份核验；合规审查；（哲学）证实原则","definition_en":"the act of checking or proving that something is true, accurate, or genuine","core_image":"一枚印章落在核对过的文件末尾，旁边是逐条打勾的清单","scene":"审核员把每一张发票与合同逐条对照，确认金额和日期都能对上，才在末页盖章。Before payment, the clerk carried out a careful verification of every invoice against the contract.","sceneCN":"这里指逐条核对材料是否真实、准确（第 1 个义项：核实、查证）；句意为付款前职员把每张发票与合同仔细核对了一遍。场景图取象：核对完的文件末尾落下一枚印章。","pos":[{"tag":"n.","zh":"核实；验证；查证（不可数，指过程时多用单数）"},{"tag":"n.","zh":"证明为真的证据或确认结论"},{"tag":"n.","zh":"身份、证件、账户的核验"},{"tag":"n.","zh":"（哲学）证实原则；证实主义的核心概念"}],"collocations":[{"phrase":"identity verification","zh":"身份核验"},{"phrase":"verification process","zh":"验证流程"},{"phrase":"verification of results","zh":"结果核验"},{"phrase":"independent verification","zh":"独立核实"},{"phrase":"source verification","zh":"消息来源核实"},{"phrase":"verification code","zh":"验证码"},{"phrase":"undergo verification","zh":"接受核验"}],"forms":[{"label":"原形","form":"verification"},{"label":"复数","form":"verifications"},{"label":"动词","form":"verify"},{"label":"形容词","form":"verifiable"},{"label":"名词（可核实性）","form":"verifiability"},{"label":"名词（核验者）","form":"verifier"},{"label":"形容词（已核实的）","form":"verified"}],"derivatives":[{"word":"verify","pos":"v.","zh":"核实；证实（由「真」与「做」两个拉丁词根合成，字面即「使之成真」）"},{"word":"verifiable","pos":"adj.","zh":"可核实的（加表示「能够被……」的形容词后缀，指可以被查证）"},{"word":"verifiability","pos":"n.","zh":"可核实性（在形容词后加表示「性质」的名词后缀）"},{"word":"verifier","pos":"n.","zh":"核验者；验证程序（加表示「施动者」的名词后缀）"},{"word":"verified","pos":"adj.","zh":"已核实的；经确认的（动词过去分词转为形容词，指核验已经完成）"},{"word":"verificationism","pos":"n.","zh":"证实主义（在 verification 后加表示「学说」的后缀，指以能否证实判断意义的主张）"}],"senses":[{"no":"01","title":"The act of checking","titleCN":"核对、查证的动作","definition":"the act of checking whether a statement, figure or account is true and accurate","definitionCN":"检查某一说法、数字或账目是否真实准确的行为","example":"Verification of the figures took three days.","exampleCN":"核对这些数字花了三天。","why":"The word joins 'true' and 'make', so the act is making sure a claim really is true.","whyCN":"这个词把「真」与「做」合在一起，动作就是确保某个说法确实为真。"},{"no":"02","title":"Formal confirmation","titleCN":"正式确认","definition":"official confirmation that a document, claim or record meets a required standard","definitionCN":"官方确认某份文件、声明或记录达到了规定标准","example":"The certificate requires verification by a public notary.","exampleCN":"这份证书需要由公证人正式确认。","why":"Institutions need a stamp as well as a check, and the word covers both the check and the resulting confirmation.","whyCN":"机构既要查也要盖章，这个词同时涵盖查验与由此得到的确认。"},{"no":"03","title":"Evidence that proves","titleCN":"能证明为真的凭据","definition":"a piece of evidence or a statement that establishes something as true","definitionCN":"能证明某事为真的证据或说法","example":"His notes served as verification of the claim.","exampleCN":"他的笔记成了这一说法的凭据。","why":"The noun can name the proof itself, not only the act of producing it.","whyCN":"这个名词也能指证据本身，而不只是取得证据的动作。"},{"no":"04","title":"Checking who you are","titleCN":"身份核验","definition":"the process of confirming a person's identity, account or credentials before granting access","definitionCN":"在给予权限之前确认某人身份、账户或凭证的程序","example":"Two-step verification blocked the stolen password.","exampleCN":"两步核验挡住了被盗的密码。","why":"Digital accounts made this the everyday sense: a second check that the person is who the password says.","whyCN":"数字账户使这一义项成为日常用法：再查一次，看人是否真如密码所称。"},{"no":"05","title":"Test against reality","titleCN":"用事实检验","definition":"confirmation of a scientific claim by independent observation, measurement or experiment","definitionCN":"通过独立观察、测量或实验来确认某一科学主张","example":"Independent verification is the price of a published result.","exampleCN":"独立验证是一项结果得以发表的代价。","why":"Science separates the claim from the claimant by asking another laboratory to check it.","whyCN":"科学把主张与主张者分开，办法是让另一个实验室去查。"},{"no":"06","title":"Proof that software obeys its spec","titleCN":"证明软件符合规格","definition":"the process of showing that a program or system has been built according to its stated requirements","definitionCN":"证明某个程序或系统是按其声明的需求建成的过程","example":"Verification caught the error before the release.","exampleCN":"验证在发布前抓住了这个错误。","why":"Engineering distinguishes building the thing right from building the right thing, and calls the first verification.","whyCN":"工程学把「把东西做对」与「做对的东西」分开，前者称为验证。"},{"no":"07","title":"Audit of accounts","titleCN":"账目与合规审查","definition":"a formal audit of records, accounts or compliance with rules","definitionCN":"对记录、账目或规则遵守情况的正式审查","example":"The agency ordered verification of the charity's spending.","exampleCN":"主管机构下令核查该慈善机构的开支。","why":"Public money brings a legal duty to check, and the word acquired an administrative weight.","whyCN":"公共资金带来核对的法定义务，这个词因此带上行政分量。"},{"no":"08","title":"Fact-checking before print","titleCN":"刊印前的稿件核实","definition":"the editorial process of checking names, dates and quotations before publication","definitionCN":"发表前核对人名、日期与引文的编辑程序","example":"The magazine's verification desk flagged two dates.","exampleCN":"杂志的核实台标出了两个日期问题。","why":"Publishing houses built a desk for this work, and the word named both the desk and its task.","whyCN":"出版社为此设了专岗，这个词既指这个岗位，也指它的工作。"},{"no":"09","title":"The verification principle","titleCN":"证实原则","definition":"the philosophical rule that a statement is meaningful only if it can be checked by experience","definitionCN":"一种哲学主张：一个陈述只有能被经验检验才有意义","example":"The verification principle turned out to be too strict for its own rule.","exampleCN":"证实原则对自己那条规则来说过于严格。","why":"Early twentieth-century philosophy tried to make meaning a testable property, and gave the word this narrow sense.","whyCN":"二十世纪初的哲学想把意义变成可检验的属性，于是给了这个词一个狭窄的义项。"}],"etymology":{"intro":{"en":"Verification is built from the Latin verus 'true' and facere 'to make', through Medieval Latin verificare. The chain is well documented and the only uncertain point is the exact date of its English entry.","cn":"verification 由拉丁语 verus「真」与 facere「做」构成，经由中世纪拉丁语 verificare 而来。词源链记录充分，唯一不确定的是它进入英语的确切年代。"},"items":[{"era":"LATIN VERUS","en":"Verus meant true or genuine, and it stands behind verity, veracity and the English word very.","cn":"verus 意为真实的、真正的，还构成 verity、veracity 以及英语的 very。"},{"era":"FACERE 'MAKE'","en":"The verb facere, to make or do, supplies the second half of the compound and the -fication ending.","cn":"动词 facere 意为做、造，提供复合词的后半与 -fication 这一词尾。"},{"era":"MEDIEVAL LATIN","en":"Verificare meant to make true or to prove true, a word of the schools rather than of everyday speech.","cn":"verificare 意为使之成真或证明为真，是学院用语而非日常口语。"},{"era":"ENGLISH ENTRY","en":"The noun entered English in the late Middle Ages, first in learned and legal writing; the exact date is uncertain.","cn":"这个名词在中世纪晚期进入英语，最早见于学术与法律文本；确切年代不确定。"},{"era":"SCIENCE AND LAW","en":"From the seventeenth century it spread into experiment and jurisprudence, where a claim must be checked by evidence.","cn":"十七世纪以后，它扩展到实验与法学领域，那里主张必须靠证据核查。"},{"era":"DIGITAL IDENTITY","en":"In the last decades it became a household word through codes, passwords and two-step checks.","cn":"近几十年，它靠验证码、密码与两步核验成了家常词汇。"}]},"similar":{"note":{"en":"The first group shares the true-making root or merely looks close; the second group contains the neighbouring checks that are often confused with verification.","cn":"第一组或共享「使真」词根，或只是字形相近；第二组是常与「验证」混淆的邻近概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"verify","ipa":"/ˈverɪfaɪ/","tag":"same root","definition":"The verb behind the noun: to check or prove that something is true.","definitionCN":"名词背后的动词：核查或证明某事为真。"},{"word":"veracity","ipa":"/vəˈræsəti/","tag":"same true root","definition":"Truthfulness, especially of a person or account; it shares verus but not facere.","definitionCN":"真实性、诚实，尤指人或陈述；共享「真」词根，不含「做」。"},{"word":"verity","ipa":"/ˈverəti/","tag":"same true root","definition":"An old word for truth itself, built on the same Latin adjective.","definitionCN":"指真理本身的古词，由同一个拉丁形容词构成。"},{"word":"versification","ipa":"/ˌvɜːsɪfɪˈkeɪʃn/","tag":"different root","definition":"The art of turning prose into verse; it looks close but comes from versus, a turning of the plough.","definitionCN":"把散文写成诗句的技艺；字形相近，却来自「犁沟转向」之意的 versus。"},{"word":"vilification","ipa":"/ˌvɪlɪfɪˈkeɪʃn/","tag":"different root","definition":"Abusive speech that lowers someone's name; its first element means cheap or base.","definitionCN":"贬损他人名誉的辱骂；其前一部分意为低贱。"}]},{"heading":"NEAR MEANING","entries":[{"word":"validation","ipa":"/ˌvælɪˈdeɪʃn/","tag":"near meaning","definition":"Checking that a system meets the user's real need, as opposed to its written specification.","definitionCN":"检查系统是否满足使用者的真实需要，与书面规格相对。"},{"word":"confirmation","ipa":"/ˌkɒnfəˈmeɪʃn/","tag":"near meaning","definition":"A statement or act that makes something formally certain.","definitionCN":"使某事在形式上确定的说法或举动。"},{"word":"authentication","ipa":"/ˌɔːθentɪˈkeɪʃn/","tag":"near meaning","definition":"Proving that a person or object is genuine, especially in computing.","definitionCN":"证明人或物为真品，尤用于计算机领域。"},{"word":"certification","ipa":"/ˌsɜːtɪfɪˈkeɪʃn/","tag":"near meaning","definition":"Formal granting of a certificate after an authority has checked a standard.","definitionCN":"主管机构查过标准后正式发给证书。"},{"word":"fact-checking","ipa":"/ˈfækt tʃekɪŋ/","tag":"near meaning","definition":"The journalistic routine of confirming details before publication.","definitionCN":"发表前核对细节的新闻例行工作。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real true-making root, the real derivative family and real fixed phrases.","cn":"正常联想使用真实的「使真」词根、真实派生词族与真实固定搭配。"},"normal":[{"en":"Verus is true and facere is make, so verification is literally the making true of a claim.","cn":"前者为真，后者为做，合起来字面就是使一个说法成真。"},{"en":"The same true root gives verity and veracity, while the make root gives -fication in dozens of words.","cn":"同一个「真」词根给出 verity 与 veracity，「做」词根则在许多词里留下 -fication 词尾。"},{"en":"Fixed phrases mark the uses: identity verification, independent verification, verification code.","cn":"固定说法标出用法：身份核验、独立核实、验证码。"},{"en":"The verb is verify, the adjective verifiable, the person verifier.","cn":"动词是 verify，形容词是可核实的，执行者是核验者。"},{"en":"A verified document carries a stamp; a verification is the check that earns the stamp.","cn":"已核实的文件带着印章，核验就是挣来这枚印章的检查。"}],"abstract":[{"en":"Verification is distrust put to work in an orderly way.","cn":"核验是把不信任按规矩使出来。"},{"en":"It does not create truth; it only refuses to accept a claim until the claim can be checked.","cn":"它并不制造真理，只是在说法可被核对之前拒绝接受它。"},{"en":"A society that stops verifying slowly loses the difference between a claim and a fact.","cn":"一个不再核验的社会，会慢慢失去主张与事实之间的区别。"}]},"examples":[{"en":"Verification of the sample took longer than the test itself.","cn":"样本核验比测试本身花的时间还长。"},{"en":"The bank asks for a second verification before large transfers.","cn":"大额转账前银行要求再做一次核验。"},{"en":"Independent verification is what turns an announcement into a result.","cn":"独立验证才能把一则宣告变成一个结果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「维瑞菲克申」——把「真」做出来，逐条打勾盖章：核实、验证","word":"verification"},"root":"中世纪拉丁语 verificare「使之成真、证明为真」← 拉丁语 verus「真」＋ facere「做、造」；verus 另构成 verity、veracity 与 very，facere 构成 -fication 系列。进入英语的确切年代不确定，义项扩展至科学、法律与数字身份。","sensesIntro":{"en":"Nine senses follow the same act: a check, a formal confirmation, the proof itself, an identity check, a test against reality, proof of a specification, an audit, editorial fact-checking, and a philosophical principle.","cn":"九个义项跟着同一个动作：核对、正式确认、凭据本身、身份核验、用事实检验、对规格的证明、账目审查、刊前核实，以及一条哲学原则。"},"semanticMap":{"core":{"en":"CORE IMAGE: a checked list with ticks beside every line, and a stamp waiting at the end.","cn":"核心意象：每行都打了勾的清单，末尾等着落下一枚印章。"},"chain":["TRUE","MAKE TRUE","CHECK","CONFIRM","AUDIT","SECOND CHECK"],"branches":[{"senses":"01 · 03","en":"THE CHECK AND ITS PROOF: the act of testing a claim, and the evidence that the test produced.","cn":"检查及其凭据：检验主张的动作，以及检验得出的证据。"},{"senses":"02 · 07","en":"THE OFFICIAL SEAL: confirmation by an authority, and the audit that must come before it.","cn":"官方印章：主管者的确认，以及确认之前必须做的审查。"},{"senses":"04","en":"THE IDENTITY CHECK: the second step that proves a person is who the account says.","cn":"身份核验：证明人如其账户所称的第二步。"},{"senses":"05 · 06 · 08","en":"THE TEST OF A CLAIM: independent experiment, a program checked against its specification, and a page checked before print.","cn":"对主张的检验：独立实验、按规格检查的程序，以及付印前核对过的稿件。"},{"senses":"09","en":"THE PRINCIPLE: meaning itself is said to require a possible check.","cn":"那条原则：意义本身被要求可以被检验。"}]},"affixes":{"intro":{"en":"Verification is a compound of two productive Latin pieces, and its endings still build abstract nouns in English.","cn":"verification 由两个能产的拉丁构件合成，其词尾在英语中仍能造抽象名词。"},"latinIntro":{"en":"Latin verus and facere are the two sources; the noun ending came through Medieval Latin -ficatio.","cn":"拉丁语 verus 与 facere 是两个来源，名词词尾经由中世纪拉丁语的 -ficatio 而来。"},"items":[{"word":"verification","structure":"Medieval Latin verificatio","meaning":"a making true; a proof","meaningCN":"使之成真；证明","example":"The noun names both the act and its outcome.","exampleCN":"这个名词既指动作，也指结果。"},{"word":"verus","structure":"Latin adjective","meaning":"true, genuine","meaningCN":"真的；真正的","example":"It also stands behind verity and very.","exampleCN":"它还构成 verity 与 very。"},{"word":"facere","structure":"Latin verb","meaning":"to make, to do","meaningCN":"做；造","example":"It is the source of the -fy and -fication endings.","exampleCN":"它是 -fy 与 -fication 词尾的来源。"},{"word":"-fication","structure":"Latin -ficatio, through French","meaning":"the making of something","meaningCN":"使成为……的行为","example":"It builds classification, simplification and purification.","exampleCN":"它构成分类、简化与提纯等词。"},{"word":"-fy","structure":"Latin -ficare","meaning":"to make or cause","meaningCN":"使……；使成为","example":"It builds verify, clarify and amplify.","exampleCN":"它构成核实、澄清与放大等动词。"},{"word":"verifiable","structure":"verify plus -able","meaning":"able to be checked","meaningCN":"可核实的","example":"The adjective sets the standard for a good claim.","exampleCN":"这个形容词为好的主张立下标准。"},{"word":"verifier","structure":"verify plus -er","meaning":"one who or that which checks","meaningCN":"核验者；验证程序","example":"The ending marks the person or the tool.","exampleCN":"词尾标出人或工具。"},{"word":"verifiability","structure":"verifiable plus -ity","meaning":"the quality of being checkable","meaningCN":"可核实性","example":"The abstract noun names a property rather than an act.","exampleCN":"这个抽象名词指属性而非动作。"}],"latinEntries":[{"word":"verificare","structure":"verus (true) + facere (make)","meaning":"to make true; to prove true","meaningCN":"使之成真；证明为真","example":"Medieval Latin verificare means to make true.","exampleCN":"中世纪拉丁语 verificare 意为使之为真。"},{"word":"verus","structure":"Latin adjective verus (true)","meaning":"true, genuine","meaningCN":"真的；真正的","example":"Latin verus means true, and gives veracity and verdict.","exampleCN":"拉丁语 verus 意为真的，并给出 veracity 与 verdict。"},{"word":"facere","structure":"Latin verb facere (fac-, factum; to make)","meaning":"to make, to do","meaningCN":"做；造","example":"Latin facere means to make or do.","exampleCN":"拉丁语 facere 意为做、造。"}],"derivatives":[{"word":"verify","pos":"v.","zh":"核实；证实"},{"word":"verifiable","pos":"adj.","zh":"可核实的"},{"word":"verifiability","pos":"n.","zh":"可核实性"},{"word":"verifier","pos":"n.","zh":"核验者；验证程序"},{"word":"verified","pos":"adj.","zh":"已核实的"},{"word":"verificationism","pos":"n.","zh":"证实主义"}]}},{"word":"verify","ipa_uk":"/ˈverɪfaɪ/","ipa_us":"/ˈverɪfaɪ/","definition_zh":"核实；查证；证实；确认（身份、证件、数据）；以誓言证明（法律文书）；验算","definition_en":"to check or prove that something is true, accurate, or authentic","core_image":"一张单据被逐行对着原件比过，每个数字后面都落下一个小勾","scene":"门岗把访客的证件放进扫描仪，屏幕核对通过后亮起一个绿勾。The guard used a scanner to verify the visitor's pass before letting him in.","sceneCN":"这里指核对证件是否真实有效（第 4 个义项：核验身份与凭证）；句意为门岗用扫描仪核验访客的通行证后才放他进去。场景图取象：单据上每个数字后面落下一个小勾。","pos":[{"tag":"v.","zh":"核实；查证；证实"},{"tag":"v.","zh":"确认身份、凭证或账户"},{"tag":"v.","zh":"验算；检验数据是否正确"},{"tag":"v.","zh":"（法律）以誓言或附誓书证明"}],"collocations":[{"phrase":"verify a claim","zh":"核实一项说法"},{"phrase":"verify the identity of","zh":"核验……的身份"},{"phrase":"verify the data","zh":"校验数据"},{"phrase":"verify a signature","zh":"验证签名"},{"phrase":"verify by experiment","zh":"用实验验证"},{"phrase":"independently verify","zh":"独立核实"},{"phrase":"verify that the figures add up","zh":"验算数字是否对得上"}],"forms":[{"label":"原形","form":"verify"},{"label":"第三人称单数","form":"verifies"},{"label":"过去式","form":"verified"},{"label":"过去分词","form":"verified"},{"label":"现在分词","form":"verifying"},{"label":"名词","form":"verification"},{"label":"形容词","form":"verifiable"},{"label":"名词（执行者）","form":"verifier"}],"derivatives":[{"word":"verification","pos":"n.","zh":"核实；验证（由动词加表示「行为、过程」的拉丁后缀构成，指核对这一动作及其结论）"},{"word":"verifiable","pos":"adj.","zh":"可核实的（加表示「能够被……」的形容词后缀，指说法或数据经得起查）"},{"word":"verifier","pos":"n.","zh":"核验者；验证程序（加表示「施动者」的名词后缀）"},{"word":"unverified","pos":"adj.","zh":"未经核实的（加表示否定的前缀，指尚未查证）"},{"word":"verified","pos":"adj.","zh":"已核实的；带认证标记的（过去分词转形容词，指核验已完成）"}],"senses":[{"no":"01","title":"Check a statement","titleCN":"核查一项说法","definition":"to check whether a statement or piece of information is true","definitionCN":"检查某一说法或信息是否真实","example":"Reporters must verify a claim before printing it.","exampleCN":"记者在刊出之前必须核实一项说法。","why":"The word is built as 'make true', and checking is the step that makes a claim stand.","whyCN":"这个词由「使之成真」构成，核查就是让说法立得住的那一步。"},{"no":"02","title":"Confirm with evidence","titleCN":"用证据加以确认","definition":"to establish that something is true by producing evidence or a second source","definitionCN":"通过拿出证据或第二个来源来确认某事为真","example":"Two witnesses verified his account of the night.","exampleCN":"两名证人证实了他对那一夜的叙述。","why":"Confirmation turns a single voice into a checked fact, which is what the verb promises.","whyCN":"确认把一个声音变成经核查的事实，这正是这个动词所许诺的。"},{"no":"03","title":"Check the arithmetic","titleCN":"验算、核对数字","definition":"to test a calculation, measurement or transcription for accuracy","definitionCN":"检验计算、测量或抄录是否准确","example":"Please verify that the totals on page two are correct.","exampleCN":"请核对第二页的合计是否正确。","why":"Numbers fail silently, so a second pass is needed to make the figure true again.","whyCN":"数字出错时不会出声，所以要再走一遍，让那个数重新为真。"},{"no":"04","title":"Check who someone is","titleCN":"核验身份与凭证","definition":"to confirm a person's identity, documents or account credentials before allowing access","definitionCN":"在允许进入之前确认某人的身份、证件或账户凭证","example":"The app asks you to verify your email address.","exampleCN":"这个应用要求你核验电子邮箱地址。","why":"Access control needs a check that the holder is the rightful holder, and the verb supplies it.","whyCN":"权限控制需要查明持件人就是合法持件人，这个动词正是干这件事。"},{"no":"05","title":"Check authenticity","titleCN":"查验真伪","definition":"to establish that a document, signature or object is genuine and not forged","definitionCN":"确认文件、签名或器物是真品而非伪造","example":"An expert verified the signature on the letter.","exampleCN":"一位专家查验了信上的签名。","why":"Genuine is the oldest sense of the true root, so checking a signature is the word's home ground.","whyCN":"「真品」是「真」这个词根最古老的含义，查验签名正是它的本行。"},{"no":"06","title":"Test a hypothesis","titleCN":"检验假说","definition":"to test a scientific hypothesis or prediction by observation or experiment","definitionCN":"通过观察或实验检验科学假说或预测","example":"The team verified the prediction with a field survey.","exampleCN":"团队用一次野外调查检验了这一预测。","why":"A prediction earns trust only when the world has been asked and has answered as forecast.","whyCN":"预测只有问过世界、而世界果然如其所言，才赢得信任。"},{"no":"07","title":"Check data integrity","titleCN":"校验数据完整性","definition":"to check that data or a file has not been altered or corrupted","definitionCN":"检查数据或文件是否被改动或损坏","example":"The tool verifies every download against a checksum.","exampleCN":"这个工具用校验和检查每个下载文件。","why":"Computing needs a cheap proof that a copy is still the same copy, and reuses the word for it.","whyCN":"计算机领域需要便宜的证明，确认副本还是原来那份，就借用了这个词。"},{"no":"08","title":"Swear to a pleading","titleCN":"以誓言证明文书","definition":"to support a legal document by oath or affidavit, declaring its contents true","definitionCN":"以誓言或附誓书支持一份法律文书，声明其内容属实","example":"The plaintiff verified the complaint before the court.","exampleCN":"原告在法庭上以誓言证明这份诉状属实。","why":"Legal procedure has long required a personal declaration that a written claim is true.","whyCN":"法律程序早已要求当事人亲自声明书面主张为真。"},{"no":"09","title":"Verify a suspicion","titleCN":"证实疑虑或猜测","definition":"to find out whether a suspicion, rumour or doubt is justified","definitionCN":"查明某一怀疑、传闻或疑虑是否有根据","example":"A quick call verified her worst suspicion.","exampleCN":"一个简短的电话证实了她最坏的猜测。","why":"The everyday sense narrows the word to a private doubt that a fact suddenly settles.","whyCN":"日常义项把这个词缩小到一桩私人的疑虑，被一个事实突然定了性。"}],"etymology":{"intro":{"en":"Verify comes from Medieval Latin verificare, 'to make true', built on verus 'true' and facere 'to make'. The formation is clear; only the exact date of the English borrowing is uncertain.","cn":"verify 来自中世纪拉丁语 verificare「使之成真」，由 verus「真」与 facere「做」构成。构词清楚，只有进入英语的确切年代不确定。"},"items":[{"era":"LATIN VERUS","en":"Verus meant true or genuine and is the same adjective behind verity, veracity and very.","cn":"verus 意为真实的、真正的，也是 verity、veracity 与 very 背后的同一个形容词。"},{"era":"FACERE","en":"Facere, to make or do, turns the adjective into a verb of producing a result: to make a thing true.","cn":"facere 意为做、造，把形容词变成表示造出结果的动词：使某物为真。"},{"era":"OLD FRENCH VERIFIER","en":"Old French carried the learned Latin verb into wider use, and English took it from there in the fourteenth century.","cn":"古法语把这个学术拉丁动词带入更广的使用，英语在十四世纪从那里借入。"},{"era":"LEGAL AND RELIGIOUS USE","en":"Early English use was legal and religious: verifying a statement meant swearing to it or proving it in court.","cn":"早期英语用法属法律与宗教：核实一项陈述意味着宣誓或当庭证明。"},{"era":"SCIENCE","en":"From the seventeenth century the verb moved into experiment, where a prediction is checked against what happens.","cn":"十七世纪以后，这个动词进入实验领域，预测要拿实际发生的事来对照。"},{"era":"COMPUTING","en":"In the digital age it acquired the narrow sense of checking identity or file integrity, which now dominates daily use.","cn":"数字时代它获得核对身份或文件完整性的狭窄含义，如今这层用法在日常中占主导。"}]},"similar":{"note":{"en":"The first group shares the true root or looks similar; the second group holds words that are often substituted for verify but carry a different duty.","cn":"第一组或共享「真」词根，或字形相近；第二组是常被拿来替代 verify、但职责不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"verification","ipa":"/ˌverɪfɪˈkeɪʃn/","tag":"same root","definition":"The noun for the act or result of checking.","definitionCN":"表示核对行为或结果的同根名词。"},{"word":"verifiable","ipa":"/ˈverɪfaɪəbl/","tag":"same root","definition":"Able to be checked, said of a claim or figure.","definitionCN":"可被核实的，用于说法或数字。"},{"word":"veracity","ipa":"/vəˈræsəti/","tag":"same true root","definition":"Habitual truthfulness, a quality of persons rather than a test.","definitionCN":"一贯诚实，指人的品质而非检验。"},{"word":"versify","ipa":"/ˈvɜːsɪfaɪ/","tag":"different root","definition":"To turn prose into verse; the ending matches but the root means a turning furrow.","definitionCN":"把散文写成诗；词尾相同，词根却指犁沟转向。"},{"word":"vilify","ipa":"/ˈvɪlɪfaɪ/","tag":"different root","definition":"To speak abusively about someone; its root means base or cheap.","definitionCN":"辱骂贬损某人；其词根意为低贱。"}]},{"heading":"NEAR MEANING","entries":[{"word":"confirm","ipa":"/kənˈfɜːm/","tag":"near meaning","definition":"To make a fact formally certain, often by a second statement rather than a test.","definitionCN":"使事实在形式上确定，常靠第二个说法而非检验。"},{"word":"validate","ipa":"/ˈvælɪdeɪt/","tag":"near meaning","definition":"To prove valid or acceptable, especially that a system meets its user's need.","definitionCN":"证明有效或可接受，尤指系统满足使用者需要。"},{"word":"authenticate","ipa":"/ɔːˈθentɪkeɪt/","tag":"near meaning","definition":"To prove that a person or object is genuine, a narrower job than checking a claim.","definitionCN":"证明人或物为真品，比核查说法窄。"},{"word":"check","ipa":"/tʃek/","tag":"near meaning","definition":"The plain everyday verb for a quick look, without the formal promise of proof.","definitionCN":"最朴素的日常说法，快速看一眼，不含正式证明的承诺。"},{"word":"substantiate","ipa":"/səbˈstænʃieɪt/","tag":"near meaning","definition":"To support a claim with solid evidence, closer to proving than to checking.","definitionCN":"用扎实证据支撑主张，比核对更接近证明。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real true-making root, the real family and real fixed phrases.","cn":"正常联想使用真实的「使真」词根、真实同族词与真实固定搭配。"},"normal":[{"en":"Verus is true and facere is make, so verify is to make a claim true by checking it.","cn":"前者为真，后者为做，verify 就是通过核查把说法做成真的。"},{"en":"Old French verifier carried the word to English, and the legal oath is its oldest surviving use.","cn":"古法语的 verifier 把词带到英语，法庭宣誓是它存活至今最古老的用法。"},{"en":"The family is verify, verification, verifiable, verifier and unverified.","cn":"同族词有 verify、verification、verifiable、verifier 与 unverified。"},{"en":"Fixed phrases mark the uses: verify a claim, verify identity, verify a signature, independently verify.","cn":"固定说法标出用法：核实说法、核验身份、验证签名、独立核实。"},{"en":"The noun form takes -cation, the adjective takes -able, and the doer takes -er.","cn":"名词用 -cation 词尾，形容词用 -able，施动者用 -er。"}],"abstract":[{"en":"To verify is to let the fact have the last word instead of the claimant.","cn":"核实就是让事实而非主张者说了算。"},{"en":"A claim that cannot be verified is only a preference wearing the clothes of a fact.","cn":"无法核实的说法，只是穿着事实外衣的偏好。"},{"en":"Every check is a small refusal to be persuaded by confidence alone.","cn":"每一次核查，都是对单凭自信就被说服的小小拒绝。"}]},"examples":[{"en":"Please verify the spelling of every name on the list.","cn":"请核对名单上每个名字的拼写。"},{"en":"The lab could not verify the result a second time.","cn":"实验室第二次没能验证这个结果。"},{"en":"Banks now verify a caller's voice before any transfer.","cn":"银行如今在转账前先核验来电者的声音。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「维瑞法依」——把「真」做出来，逐条打勾：核实、验证","word":"verify"},"root":"中世纪拉丁语 verificare「使之成真」← verus「真」＋ facere「做」；经古法语 verifier 于十四世纪进入英语。同根词有 verity、veracity、very；-fication 词尾见于 classification、simplification 等。进入英语的确切年代不确定。","sensesIntro":{"en":"Nine senses follow the check: a statement tested, a fact confirmed, arithmetic re-added, an identity proved, a signature judged genuine, a hypothesis tried, a file checked for damage, a pleading sworn, and a suspicion settled.","cn":"九个义项沿着核查展开：检验说法、确认事实、验算数字、证明身份、判定签名真伪、检验假说、检查文件是否损坏、以誓言证明诉状，以及让疑虑落定。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sheet compared line by line with its original, each item ticked.","cn":"核心意象：一张单据逐行对着原件比过，每一项都打了勾。"},"chain":["TRUE","MAKE TRUE","CHECK","CONFIRM","CERTIFY","SECOND CHECK"],"branches":[{"senses":"01 · 02","en":"THE CLAIM UNDER TEST: a statement is checked, then confirmed by evidence or a second voice.","cn":"受检的主张：说法先被核对，再由证据或第二个声音确认。"},{"senses":"03 · 07","en":"THE FIGURE AND THE FILE: totals re-added by hand, downloads compared against a checksum.","cn":"数字与文件：合计重新加过，下载文件与校验和对照。"},{"senses":"04 · 05","en":"THE GENUINE HOLDER: an identity or a signature proved real before access is granted.","cn":"真正的持有人：在给予权限前证明身份或签名属实。"},{"senses":"06 · 09","en":"THE SETTLED DOUBT: a prediction tested in the field, or a private suspicion ended by one fact.","cn":"落定的疑虑：预测在野外受检，或私人的怀疑被一个事实了结。"},{"senses":"08","en":"THE OATH: a written claim declared true by the person who makes it.","cn":"誓言：书面主张由提出者亲自声明属实。"}]},"affixes":{"intro":{"en":"Verify is a Latin compound whose two halves are both common building blocks in English.","cn":"verify 是一个拉丁复合词，前后两半在英语里都是常见的构词材料。"},"latinIntro":{"en":"The direct source is Medieval Latin verificare, from verus and facere.","cn":"直接来源是中世纪拉丁语 verificare，出自 verus 与 facere。"},"items":[{"word":"verify","structure":"Medieval Latin verificare","meaning":"to make true; to prove","meaningCN":"使之成真；证明","example":"The verb names the act of checking a claim.","exampleCN":"这个动词指核查主张的动作。"},{"word":"verus","structure":"Latin adjective","meaning":"true, genuine","meaningCN":"真的；真正的","example":"It also gives verity and very.","exampleCN":"它还给出 verity 与 very。"},{"word":"facere","structure":"Latin verb","meaning":"to make, to do","meaningCN":"做；造","example":"It supplies the -fy ending.","exampleCN":"它提供 -fy 词尾。"},{"word":"-fy","structure":"Latin -ficare","meaning":"to make, to cause to be","meaningCN":"使……；使成为","example":"It builds verify, clarify and amplify.","exampleCN":"它构成核实、澄清与放大。"},{"word":"verification","structure":"verify plus -cation","meaning":"the act of checking","meaningCN":"核对的行为","example":"The noun names the process or its result.","exampleCN":"这个名词指过程或结果。"},{"word":"verifiable","structure":"verify plus -able","meaning":"able to be checked","meaningCN":"可核实的","example":"The adjective marks what can stand a test.","exampleCN":"这个形容词标出经得起检验的东西。"},{"word":"verifier","structure":"verify plus -er","meaning":"one who checks","meaningCN":"核验者","example":"The ending marks the person or program.","exampleCN":"词尾标出人或程序。"},{"word":"un-","structure":"English negative prefix","meaning":"not","meaningCN":"不；未","example":"It builds unverified, meaning not yet checked.","exampleCN":"它构成 unverified，意为尚未核实。"}],"latinEntries":[{"word":"verificare","structure":"verus (true) + facere (make)","meaning":"to make true; to prove true","meaningCN":"使之成真；证明为真","example":"The Latin verb is the direct source of English verify.","exampleCN":"这个拉丁动词是英语 verify 的直接来源。"},{"word":"verus","structure":"Latin adjective verus (true)","meaning":"true, genuine","meaningCN":"真的；真正的","example":"The adjective supplies the truth at the centre of the verb.","exampleCN":"这个形容词提供动词核心的「真」。"},{"word":"facere","structure":"Latin verb facere (fac-, factum; to make)","meaning":"to make, to do","meaningCN":"做；造","example":"The verb supplies the making half of the compound.","exampleCN":"这个动词提供复合词中「使成」那一半。"}],"derivatives":[{"word":"verification","pos":"n.","zh":"核实；验证"},{"word":"verifiable","pos":"adj.","zh":"可核实的"},{"word":"verifier","pos":"n.","zh":"核验者；验证程序"},{"word":"unverified","pos":"adj.","zh":"未经核实的"},{"word":"verified","pos":"adj.","zh":"已核实的"}]}},{"word":"falsification","ipa_uk":"/ˌfɔːlsɪfɪˈkeɪʃn/","ipa_us":"/ˌfɑːlsəfəˈkeɪʃn/","definition_zh":"证伪；证明为假；伪造；篡改（记录、数据、账目）；（哲学）可证伪性方法中的反证环节","definition_en":"the act of showing that a statement or theory is false, or of making a document or record false","core_image":"一支笔把文件上原本的数字划掉，改写成另一个数字，墨迹还压在纸面上","scene":"档案馆里有人把原始记录的年份悄悄改早，后来的研究者用同位素检测发现了这处改动。The historian exposed a falsification of the archive record that had stood for sixty years.","sceneCN":"这里指对记录、数据的篡改（第 3 个义项：伪造、篡改）；句意为这位历史学家揭穿了一处冒充了六十年的档案篡改。场景图取象：文件上的数字被划掉改写。","pos":[{"tag":"n.","zh":"证伪；证明为假（不可数）"},{"tag":"n.","zh":"伪造；篡改（文件、数据、账目）"},{"tag":"n.","zh":"（哲学）证伪；反证的一次具体操作"}],"collocations":[{"phrase":"falsification of data","zh":"数据篡改"},{"phrase":"falsification of records","zh":"伪造记录"},{"phrase":"falsification of a theory","zh":"对一个理论的证伪"},{"phrase":"deliberate falsification","zh":"故意伪造"},{"phrase":"the principle of falsification","zh":"证伪原则"},{"phrase":"falsification test","zh":"证伪检验"},{"phrase":"accused of falsification","zh":"被控伪造"}],"forms":[{"label":"原形","form":"falsification"},{"label":"复数","form":"falsifications"},{"label":"动词","form":"falsify"},{"label":"形容词","form":"falsifiable"},{"label":"名词（伪造者）","form":"falsifier"},{"label":"形容词（虚假的）","form":"false"},{"label":"名词（谬误）","form":"fallacy"}],"derivatives":[{"word":"falsify","pos":"v.","zh":"证伪；伪造（由「假」与「做」两个拉丁词根合成，字面即「使之为假」）"},{"word":"falsifiable","pos":"adj.","zh":"可证伪的（加表示「能够被……」的形容词后缀，指一种说法能被事实推翻）"},{"word":"falsifier","pos":"n.","zh":"证伪者；伪造者（加表示「施动者」的名词后缀，兼指做实验推翻理论与造假两种人）"},{"word":"falsity","pos":"n.","zh":"虚假；不实（由「假」的形容词加表示「性质」的名词后缀构成）"},{"word":"falsehood","pos":"n.","zh":"谎言；虚假陈述（英语本族语复合词，指不实之事）"},{"word":"falsificationism","pos":"n.","zh":"证伪主义（在证伪后加表示「学说」的后缀，指以能否被推翻来判断科学性的主张）"}],"senses":[{"no":"01","title":"Showing a claim is false","titleCN":"证明某一说法为假","definition":"the act of proving that a statement, belief or theory is false","definitionCN":"证明一个说法、信念或理论为假的行为","example":"The falsification of the rumour took only one document.","exampleCN":"推翻那个传闻只用了一份文件。","why":"The word is built as 'making false', and the oldest sense is exactly that: bringing a claim down.","whyCN":"这个词由「使之为假」构成，最古老的义项正就是这个：把一种说法打翻。"},{"no":"02","title":"The test that could fail","titleCN":"可能失败的那次检验","definition":"in the philosophy of science, a test so framed that a negative result would count against the theory","definitionCN":"在科学哲学中，设计得使否定结果足以打击该理论的一次检验","example":"Popper made falsification the mark of a scientific claim.","exampleCN":"波普尔把证伪立为科学主张的标志。","why":"A theory that cannot lose is not being tested; the power to be shown false is what makes a test real.","whyCN":"不会输的理论并没有受检；能被证明为假的力量，才让检验成其为检验。"},{"no":"03","title":"Doctoring a record","titleCN":"篡改记录","definition":"the deliberate alteration of a document, data set or account so that it misrepresents the facts","definitionCN":"故意改动文件、数据集或账目，使其歪曲事实","example":"The audit found falsification of three quarterly reports.","exampleCN":"审计发现三份季度报告被篡改。","why":"The same verb that means proving false also means making false, and paperwork is where the second sense lives.","whyCN":"既表示「证明为假」又表示「使之为假」的同一个动词，第二层意思就落在纸面上。"},{"no":"04","title":"A refuting instance","titleCN":"一条反证","definition":"a single observation or case that contradicts a general statement and thereby disproves it","definitionCN":"与一般性陈述相抵触、从而推翻它的一条观察或事例","example":"One falsification is enough to sink a universal claim.","exampleCN":"一条反证就足以推翻一个全称主张。","why":"Universal claims promise everything without exception, so one exception makes the promise false.","whyCN":"全称主张承诺无一例外，因此一个例外就让这承诺为假。"},{"no":"05","title":"Forgery of a signature","titleCN":"签名与文书的伪造","definition":"the forging of a signature, document or certificate so that it appears genuine","definitionCN":"伪造签名、文件或证书，使其看起来像真品","example":"Falsification of a passport is a criminal offence.","exampleCN":"伪造护照是刑事犯罪。","why":"Forgery makes a false thing pass as true, which is the 'making false' branch in its legal form.","whyCN":"伪造让假东西冒充真东西，这是「使之为假」一脉在法律上的形态。"},{"no":"06","title":"Research misconduct","titleCN":"科研中的数据造假","definition":"the fabrication or manipulation of research data, images or results","definitionCN":"编造或操纵研究数据、图像或结果","example":"The journal retracted the paper after evidence of falsification.","exampleCN":"有造假证据后，期刊撤下了那篇论文。","why":"Modern universities separate honest error from falsification, because only the second is misconduct.","whyCN":"现代大学把诚实的错误与造假分开，因为只有后者才算不端。"},{"no":"07","title":"False accounting","titleCN":"账目作假","definition":"the falsification of financial accounts, invoices or tax records","definitionCN":"对财务账目、发票或税务记录的作假","example":"He was charged with falsification of company accounts.","exampleCN":"他被控对公司账目作假。","why":"Law names the offence after the act, and accounts are the documents most often made false.","whyCN":"法律以动作命名罪名，而账目是最常被做假的文件。"},{"no":"08","title":"The state of being disproved","titleCN":"被推翻的状态","definition":"the condition of a statement that has been shown to be false","definitionCN":"某一说法已被证明为假的状态","example":"The falsification of that model came from its own predictions.","exampleCN":"那个模型是被它自己的预测推翻的。","why":"The noun can name the outcome as well as the act, so a theory can be said to suffer falsification.","whyCN":"这个名词也能指结果而非动作，所以说一个理论遭到证伪。"},{"no":"09","title":"A counterfeit copy","titleCN":"冒充真品的仿件","definition":"a copy or imitation made to be taken for the genuine article","definitionCN":"被做出来冒充真品的复制件或仿制品","example":"The museum rejected the painting as a falsification.","exampleCN":"博物馆认定这幅画是赝品而拒收。","why":"A false copy is a thing made false in the literal sense, and the word carries that older weight.","whyCN":"假画就是字面意义上被做假的东西，这个词还带着那层旧有的分量。"}],"etymology":{"intro":{"en":"Falsification joins Latin falsus 'false' with facere 'to make'. Both elements are well attested; the only uncertain point is how early the 'forgery' sense appears in English.","cn":"falsification 把拉丁语 falsus「假」与 facere「做」合在一起。两个构件都有充分记录，唯一不确定的是「伪造」这一义项在英语中出现得有多早。"},"items":[{"era":"LATIN FALSUS","en":"Falsus meant false or deceptive and came from fallere, to deceive, which also stands behind fail, fault and fallacy.","cn":"falsus 意为虚假的、骗人的，出自 fallere「欺骗」，fail、fault 与 fallacy 也源于此。"},{"era":"FALLERE","en":"Fallere first described a trick or a slip, and its family spreads across failure, default and fallible.","cn":"fallere 最初描述欺骗或失足，其词族延伸到 failure、default 与 fallible。"},{"era":"FACERE","en":"The second element, to make, turns the adjective into a verb of producing a state: to make false.","cn":"第二个构件意为做、造，把形容词变成制造某种状态的动词：使之为假。"},{"era":"LATE LATIN","en":"Late Latin falsificare meant to make false or to counterfeit, a word used of coins and documents as well as arguments.","cn":"晚期拉丁语 falsificare 意为使假或伪造，既用于钱币与文件，也用于论证。"},{"era":"ENGLISH ENTRY","en":"English took the noun in the sixteenth century; the exact date of its first use in the forgery sense is uncertain.","cn":"英语在十六世纪借入这个名词；它首次用于「伪造」义的确切年代不确定。"},{"era":"POPPER","en":"In the 1930s Karl Popper made falsification the test of scientific status, and the word became a term of method.","cn":"二十世纪三十年代，波普尔把证伪立为科学资格的检验，这个词于是成了方法论术语。"}]},"similar":{"note":{"en":"The first group shares the false-making root or only looks close; the second group holds the neighbouring acts that are often confused with it.","cn":"第一组或共享「使假」词根，或只是字形相近；第二组是常与之混淆的邻近行为。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"falsify","ipa":"/ˈfɔːlsɪfaɪ/","tag":"same root","definition":"The verb: to prove false or to make a record false.","definitionCN":"动词：证明为假，或把记录做假。"},{"word":"falsifiable","ipa":"/ˌfɔːlsɪˈfaɪəbl/","tag":"same root","definition":"Able to be shown false, the quality Popper demanded of a theory.","definitionCN":"能被证明为假的，正是波普尔对理论的要求。"},{"word":"false","ipa":"/fɔːls/","tag":"same root","definition":"The plain adjective of untruth, from the same Latin source.","definitionCN":"最朴素的「假」的形容词，来自同一拉丁语来源。"},{"word":"fallacy","ipa":"/ˈfæləsi/","tag":"same deceiving root","definition":"A mistaken argument that looks convincing; it shares fallere but not facere.","definitionCN":"看似有理实则错误的论证；共享「欺骗」词根，不含「做」。"},{"word":"facilitation","ipa":"/ˌfæsɪlɪˈteɪʃn/","tag":"different root","definition":"Making a process easier; the ending matches but the root means easy.","definitionCN":"使过程更容易；词尾相同，词根却意为容易。"}]},{"heading":"NEAR MEANING","entries":[{"word":"refutation","ipa":"/ˌrefjuˈteɪʃn/","tag":"near meaning","definition":"The act of proving an argument or claim wrong by evidence.","definitionCN":"用证据证明某一论证或主张有误。"},{"word":"disproof","ipa":"/dɪsˈpruːf/","tag":"near meaning","definition":"Evidence that a claim is false, the plain noun for a negative result.","definitionCN":"证明主张为假的证据，最朴素的否定结果之名。"},{"word":"forgery","ipa":"/ˈfɔːdʒəri/","tag":"near meaning","definition":"A false document, signature or object made to pass as genuine.","definitionCN":"为冒充真品而造的假文件、假签名或假器物。"},{"word":"fabrication","ipa":"/ˌfæbrɪˈkeɪʃn/","tag":"near meaning","definition":"Inventing data or a story; falsification alters what exists, fabrication creates what does not.","definitionCN":"编造数据或故事；造假改动已有之物，编造则凭空造出。"},{"word":"debunking","ipa":"/diːˈbʌŋkɪŋ/","tag":"near meaning","definition":"Publicly exposing a false claim, usually in journalism rather than in method.","definitionCN":"公开揭穿虚假说法，多见于新闻而非方法论。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real false-making root, the real family and real fixed phrases.","cn":"正常联想使用真实的「使假」词根、真实同族词与真实固定搭配。"},"normal":[{"en":"Falsus is false and facere is make, so falsification is literally the making false of something.","cn":"前者为假，后者为做，字面就是把某物做成假的。"},{"en":"Fallere, to deceive, also gives fail, fault and fallacy, so the whole family smells of a slip.","cn":"表示欺骗的 fallere 还给出 fail、fault 与 fallacy，整个词族都带着失足的气味。"},{"en":"Fixed phrases mark the uses: falsification of data, falsification of records, falsification test.","cn":"固定说法标出用法：数据篡改、伪造记录、证伪检验。"},{"en":"In science the word is honourable: a theory earns trust by surviving attempts at falsification.","cn":"在科学里这个词是体面的：理论靠挺过证伪的尝试而赢得信任。"},{"en":"In paperwork the same word is a crime: falsification of accounts and of passports.","cn":"在文书里同一个词是罪名：账目作假与伪造护照。"}],"abstract":[{"en":"Falsification is the only honest way a theory can be wrong in public.","cn":"证伪是一个理论能在公开场合出错的唯一体面方式。"},{"en":"A claim that nothing could ever contradict is not strong; it is simply out of reach.","cn":"任何东西都无法反驳的说法并不强大，只是够不着。"},{"en":"Making a record false is a small war on memory, since the paper was supposed to remember for us.","cn":"把记录做假，是对记忆发动的一场小战争，因为纸本来该替我们记住。"}]},"examples":[{"en":"The falsification of the original minutes changed the whole case.","cn":"原始会议记录被篡改，整个案子都变了。"},{"en":"Popper treated falsification as the dividing line of science.","cn":"波普尔把证伪当作科学的分界线。"},{"en":"A single falsification ended the belief in that remedy.","cn":"一条反证终结了人们对那种疗法的相信。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「佛西菲克申」——把「假」做出来，划掉原字改写：证伪、伪造","word":"falsification"},"root":"晚期拉丁语 falsificare「使假、伪造」← 拉丁语 falsus「假」＋ facere「做」，falsus 出自 fallere「欺骗」，同族有 fail、fault、fallacy、false。十六世纪进入英语；证伪作为科学方法术语由波普尔在二十世纪三十年代确立。","sensesIntro":{"en":"Nine senses run from proving a claim false, through a test that could fail, to doctored records, a single counterexample, a forged signature, research misconduct, false accounts, the state of being disproved, and a counterfeit copy.","cn":"九个义项从「证明说法为假」出发，经过可能失败的一次检验，到篡改记录、一条反证、伪造签名、科研造假、账目作假、被推翻的状态，最后是冒充真品的仿件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a number on a page crossed out and rewritten, with the old ink still under the new.","cn":"核心意象：纸上的数字被划掉改写，旧的墨迹还压在新字下面。"},"chain":["FALSE","MAKE FALSE","PROVE FALSE","ONE COUNTEREXAMPLE","A THEORY FALLS","A RECORD IS DOCTORED"],"branches":[{"senses":"01 · 08","en":"THE CLAIM BROUGHT DOWN: the act of proving a statement false, and the state it is left in.","cn":"被打翻的主张：证明说法为假的动作，以及它被留下时的状态。"},{"senses":"02 · 04","en":"THE TEST AND THE INSTANCE: a planned attempt that could fail, and the single case that does the failing.","cn":"检验与实例：一次可能失败的设计，以及真正造成失败的那一个事例。"},{"senses":"03 · 07","en":"THE DOCTORED PAPER: records and accounts altered so that they misstate the facts.","cn":"被改动的纸面：记录与账目被改动，从而歪曲事实。"},{"senses":"05 · 09","en":"THE FALSE THING: a forged signature or a copy passed off as the genuine article.","cn":"假东西：伪造的签名，或被当作真品递出的仿件。"},{"senses":"06","en":"THE MISCONDUCT: research data invented or manipulated, which the word separates from honest error.","cn":"不端行为：研究数据被编造或操纵，这个词把它与诚实的错误分开。"}]},"affixes":{"intro":{"en":"Falsification is built from the Latin words for false and make, and the same endings recur across English.","cn":"falsification 由拉丁语「假」与「做」两个词构成，同样的词尾在英语中反复出现。"},"latinIntro":{"en":"Latin falsus and facere are the sources, with the noun ending through Late Latin -ficatio.","cn":"拉丁语 falsus 与 facere 是来源，名词词尾经由晚期拉丁语的 -ficatio 而来。"},"items":[{"word":"falsification","structure":"Late Latin falsificatio","meaning":"a making false; a counterfeit","meaningCN":"使之为假；伪造","example":"The noun names both the act and the false result.","exampleCN":"这个名词既指动作，也指假的结果。"},{"word":"falsus","structure":"Latin adjective","meaning":"false, deceptive","meaningCN":"假的；骗人的","example":"It is the past participle of the verb to deceive.","exampleCN":"它是表示欺骗的动词的过去分词。"},{"word":"facere","structure":"Latin verb","meaning":"to make, to do","meaningCN":"做；造","example":"It supplies the -fication ending.","exampleCN":"它提供 -fication 词尾。"},{"word":"-fication","structure":"Latin -ficatio","meaning":"the making of something","meaningCN":"使成……的行为","example":"It builds amplification, classification and falsification.","exampleCN":"它构成放大、分类与证伪等词。"},{"word":"-fy","structure":"Latin -ficare","meaning":"to make or cause","meaningCN":"使……；使成为","example":"It builds falsify, verify and simplify.","exampleCN":"它构成证伪、核实与简化。"},{"word":"false","structure":"Latin falsus through Old French","meaning":"untrue","meaningCN":"不真实的","example":"The adjective keeps the oldest layer of meaning.","exampleCN":"这个形容词保留最古老的一层意思。"},{"word":"falsifiable","structure":"falsify plus -able","meaning":"able to be shown false","meaningCN":"可证伪的","example":"The adjective is the key term of Popper's method.","exampleCN":"这个形容词是波普尔方法的关键词。"},{"word":"falsifier","structure":"falsify plus -er","meaning":"one who falsifies","meaningCN":"证伪者；伪造者","example":"The ending marks the person, honest or not.","exampleCN":"词尾标出人，无论诚实与否。"},{"word":"falsity","structure":"false plus -ity","meaning":"the quality of being false","meaningCN":"虚假","example":"The noun names the property rather than the act.","exampleCN":"这个名词指性质而非动作。"}],"latinEntries":[{"word":"falsificare","structure":"falsus (false) + facere (make)","meaning":"to make false; to counterfeit","meaningCN":"使假；伪造","example":"Medieval Latin falsificare means to make false or to counterfeit.","exampleCN":"中世纪拉丁语 falsificare 意为使假、伪造。"},{"word":"falsus","structure":"Latin adjective falsus (false), participle of fallere","meaning":"false, deceptive","meaningCN":"假的；骗人的","example":"Latin falsus means false, from fallere, to deceive.","exampleCN":"拉丁语 falsus 意为假的，出自 fallere（欺骗）。"},{"word":"facere","structure":"Latin verb facere (fac-, factum; to make)","meaning":"to make, to do","meaningCN":"做；造","example":"Latin facere supplies the making of the compound.","exampleCN":"拉丁语 facere 提供该复合词中「造」的部分。"}],"derivatives":[{"word":"falsify","pos":"v.","zh":"证伪；伪造"},{"word":"falsifiable","pos":"adj.","zh":"可证伪的"},{"word":"falsifier","pos":"n.","zh":"证伪者；伪造者"},{"word":"falsity","pos":"n.","zh":"虚假"},{"word":"falsehood","pos":"n.","zh":"谎言；虚假"},{"word":"falsificationism","pos":"n.","zh":"证伪主义"}]}},{"word":"falsifiable","ipa_uk":"/ˌfɔːlsɪˈfaɪəbl/","ipa_us":"/ˌfɑːlsəˈfaɪəbl/","definition_zh":"可证伪的；能被证明为假的；可被反证推翻的；（科学哲学）具备可检验性的","definition_en":"capable of being proved false, especially by an observation or test that contradicts the claim","core_image":"一张写着预言的纸被一只手指按住，旁边摆着一台能显示否定结果的仪器","scene":"会议上有人提出一条断言，随后又补充说明哪种观测结果会让他当场认错。A claim becomes falsifiable once its author names the observation that would prove it wrong.","sceneCN":"这里指一种说法有被事实推翻的可能（第 1 个义项：可被证明为假）；句意为当提出者说出了哪种观测能证明自己错时，这个说法才成为可证伪的。场景图取象：预言旁摆着一台能给出否定结果的仪器。","pos":[{"tag":"adj.","zh":"可证伪的；能被证明为假的"},{"tag":"adj.","zh":"（科学哲学）具备可检验性的，即存在可能的反例"},{"tag":"adj.","zh":"（一般用法）可被质疑、可被推翻的"}],"collocations":[{"phrase":"a falsifiable hypothesis","zh":"可证伪的假说"},{"phrase":"falsifiable prediction","zh":"可证伪的预测"},{"phrase":"falsifiable claim","zh":"可被推翻的说法"},{"phrase":"falsifiable in principle","zh":"原则上可证伪"},{"phrase":"not falsifiable","zh":"不可证伪"},{"phrase":"barely falsifiable","zh":"几乎无法证伪"},{"phrase":"falsifiable by observation","zh":"可由观测证伪"}],"forms":[{"label":"原形","form":"falsifiable"},{"label":"名词（性质）","form":"falsifiability"},{"label":"动词","form":"falsify"},{"label":"名词（行为）","form":"falsification"},{"label":"反义形容词","form":"unfalsifiable"},{"label":"副词","form":"falsifiably"}],"derivatives":[{"word":"falsify","pos":"v.","zh":"证伪；伪造（由「假」与「做」合成，字面即「使之为假」）"},{"word":"falsifiability","pos":"n.","zh":"可证伪性（在可证伪的形容词后加表示「性质」的名词后缀，是科学哲学的核心标准）"},{"word":"falsification","pos":"n.","zh":"证伪；伪造（加表示「行为、过程」的拉丁后缀）"},{"word":"unfalsifiable","pos":"adj.","zh":"不可证伪的（加表示否定的前缀，指任何观测都无法推翻）"},{"word":"falsifier","pos":"n.","zh":"证伪者（加表示「施动者」的名词后缀）"}],"senses":[{"no":"01","title":"Open to being proved wrong","titleCN":"有可能被证明为错","definition":"capable of being shown false by evidence that contradicts the claim","definitionCN":"能够被与主张相抵触的证据证明为假","example":"A good forecast is falsifiable by the weather itself.","exampleCN":"一个像样的预报能被天气本身证明为错。","why":"The suffix means 'can be', so the adjective simply says the claim is able to be made false.","whyCN":"这个词尾意为「能够被」，因此这个形容词只是说该主张有可能被做成假的。"},{"no":"02","title":"The mark of a science","titleCN":"科学资格的标记","definition":"in Popper's method, framed so that some observable event would count against the theory","definitionCN":"在波普尔的方法中，其表述方式使某种可观测事件足以对该理论不利","example":"Astrology is not falsifiable in the way astronomy is.","exampleCN":"占星术不像天文学那样可证伪。","why":"The criterion is not truth but risk: a theory must be able to lose before it can win.","whyCN":"标准不在真假而在风险：理论得先能输，才有资格赢。"},{"no":"03","title":"Testable by observation","titleCN":"可由观测检验","definition":"stated in terms specific enough that observation could confirm or deny it","definitionCN":"表述足够具体，使观测能够确认或否定它","example":"The prediction was falsifiable because it named a date and a place.","exampleCN":"这个预测可证伪，因为它点明了日期和地点。","why":"Specificity is what gives a test something to bite on; vagueness protects a claim from being refuted.","whyCN":"具体性给了检验可咬住的东西；含糊则让主张免于被驳倒。"},{"no":"04","title":"Exposed to challenge","titleCN":"经得起公开质疑","definition":"in everyday use, open to challenge or contradiction by others","definitionCN":"在日常用法中，可被他人质疑或反驳","example":"Her proposal was falsifiable, so the committee could argue with it.","exampleCN":"她的提案可被反驳，委员会因此能就它争论。","why":"Outside the laboratory, the word means a claim that accepts opposition rather than silencing it.","whyCN":"在实验室之外，这个词指一种肯接受反对、而不封杀反对的说法。"},{"no":"05","title":"Can be invalidated by a counterexample","titleCN":"可被反例判为无效","definition":"in logic, able to be proved invalid by a single counterexample","definitionCN":"在逻辑中，能被单独一个反例证明为无效","example":"The rule was falsifiable by one awkward case.","exampleCN":"这条规则被一个棘手的例子就能推翻。","why":"A general rule claims all cases without exception, so one exception is enough to break it.","whyCN":"通则宣称毫无例外地覆盖全部情形，一个例外就足以把它打破。"},{"no":"06","title":"A testable statistical prediction","titleCN":"可检验的统计预测","definition":"expressed as a quantitative prediction that data could contradict","definitionCN":"表述为数量化预测，使数据有可能与之相抵触","example":"The model's projection was falsifiable by next year's figures.","exampleCN":"该模型的预测能被明年的数字证伪。","why":"Numbers give a prediction edges sharp enough for data to cut against.","whyCN":"数字把预测磨出锋刃，数据才割得进去。"},{"no":"07","title":"Not the same as false","titleCN":"可证伪不等于假","definition":"standing in contrast with 'false': a falsifiable claim may in fact be true","definitionCN":"与「假」相对照：可证伪的说法事实上也可能是真的","example":"The statement is falsifiable but happens to be true.","exampleCN":"这个陈述可证伪，却恰好为真。","why":"Being able to lose and having lost are different states, a distinction students often blur.","whyCN":"「能输」与「已经输了」是两种状态，学生常把这一区别抹平。"},{"no":"08","title":"Designed to be refutable","titleCN":"存心设计成可被驳倒","definition":"of an experiment or study, set up so that a negative outcome is possible and informative","definitionCN":"指实验或研究的设计使否定结果既有可能出现，又能说明问题","example":"The team built a falsifiable test instead of a demonstration.","exampleCN":"团队建的是一个可证伪的检验，而不是一场演示。","why":"An experiment that cannot fail teaches nothing, which is why the adjective attaches to design.","whyCN":"不会失败的实验什么也教不了，所以这个形容词常挂在设计上。"}],"etymology":{"intro":{"en":"Falsifiable is falsify plus the Latin suffix -abilis, 'able to be'. The word itself is old; its special sense as a test of science comes from Popper in the 1930s.","cn":"falsifiable 是 falsify 加拉丁语词尾 -abilis「能够被……」构成。词本身并不新，它作为科学检验标准的特殊含义来自二十世纪三十年代的波普尔。"},"items":[{"era":"FALSUS AND FACERE","en":"The base verb falsify joins falsus 'false' with facere 'to make', so it means to make false or to show false.","cn":"基础动词 falsify 把 falsus「假」与 facere「做」合起来，意为使假或证明为假。"},{"era":"-ABILIS","en":"Latin -abilis forms adjectives of capability, the same ending that gives readable and breakable in English.","cn":"拉丁语 -abilis 构成表示能力的形容词，英语里的 readable 与 breakable 用的正是同一词尾。"},{"era":"EARLY ENGLISH USE","en":"The adjective appears in English well before modern science, simply meaning able to be shown false.","cn":"这个形容词远在现代科学之前就出现在英语里，意思只是「能被证明为假」。"},{"era":"POPPER, 1930s","en":"Karl Popper made falsifiability the dividing line between scientific and non-scientific claims in his logic of research.","cn":"波普尔在他的研究逻辑中，把可证伪性立为科学主张与非科学主张的分界线。"},{"era":"ENGLISH TRANSLATION","en":"The English edition of 1959 carried the term into ordinary scientific speech, where it has stayed.","cn":"一九五九年的英译本把这个术语带入日常的科学语言，此后一直沿用。"},{"era":"OPEN SCIENCE","en":"Recent debates about replication gave new life to the adjective, now applied to data and methods as well as theories.","cn":"近年关于可重复性的争论给这个形容词注入新生命，如今它也被用于数据与方法，而不只是理论。"}]},"similar":{"note":{"en":"The first group shares the false-making root or looks close; the second group holds words that describe testability, which is often mistaken for falsifiability.","cn":"第一组或共享「使假」词根，或字形相近；第二组描述可检验性，常被误当作可证伪性。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"falsify","ipa":"/ˈfɔːlsɪfaɪ/","tag":"same root","definition":"The verb: to prove false or to make a record false.","definitionCN":"动词：证明为假，或把记录做假。"},{"word":"falsification","ipa":"/ˌfɔːlsɪfɪˈkeɪʃn/","tag":"same root","definition":"The act of proving false, or the doctoring of records.","definitionCN":"证明为假的行为，或对记录的篡改。"},{"word":"falsifiability","ipa":"/ˌfɔːlsɪfaɪəˈbɪləti/","tag":"same root","definition":"The noun for the property the adjective names.","definitionCN":"指这个形容词所述性质的名词。"},{"word":"fallible","ipa":"/ˈfæləbl/","tag":"same deceiving root","definition":"Able to be mistaken, said of people rather than claims.","definitionCN":"会犯错的，用于人而非主张。"},{"word":"feasible","ipa":"/ˈfiːzəbl/","tag":"different root","definition":"Practicable; it shares the -ible shape but comes from a root meaning to do or make readily.","definitionCN":"可行的；词尾形状相同，词根却意为易于做成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"testable","ipa":"/ˈtestəbl/","tag":"near meaning","definition":"Able to be checked by experiment, which is necessary but not sufficient for falsifiability.","definitionCN":"能用实验检查，这是可证伪的必要条件，却并不充分。"},{"word":"refutable","ipa":"/rɪˈfjuːtəbl/","tag":"near meaning","definition":"Able to be proved wrong by argument, the word used of statements rather than theories.","definitionCN":"能被论证驳倒，多用于陈述而非理论。"},{"word":"disprovable","ipa":"/dɪsˈpruːvəbl/","tag":"near meaning","definition":"Able to be shown false by evidence, the plain English equivalent.","definitionCN":"能被证据证明为假，是最朴素的英语对应词。"},{"word":"unfalsifiable","ipa":"/ˌʌnfɔːlsɪˈfaɪəbl/","tag":"near meaning","definition":"Beyond any possible test, and therefore outside science by Popper's rule.","definitionCN":"超出任何可能的检验，按波普尔的规则因此落在科学之外。"},{"word":"verifiable","ipa":"/ˈverɪfaɪəbl/","tag":"near meaning","definition":"Able to be shown true; the optimistic twin of the adjective.","definitionCN":"能被证明为真；是这个形容词乐观的另一半。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real suffix, the real family and real fixed phrases.","cn":"正常联想使用真实词尾、真实同族词与真实固定搭配。"},"normal":[{"en":"The ending -able means can be, so falsifiable is can be made false.","cn":"词尾意为「能够被」，可证伪就是能够被做成假的。"},{"en":"Falsify is false plus make, and the same ending builds readable and breakable.","cn":"基础动词是「假」加「做」，同一词尾还造出可读的与易碎的。"},{"en":"Fixed phrases mark the uses: falsifiable hypothesis, falsifiable prediction, not falsifiable.","cn":"固定说法标出用法：可证伪的假说、可证伪的预测、不可证伪。"},{"en":"The opposite is unfalsifiable, which is a criticism rather than a compliment in science.","cn":"反义词是不可证伪，在科学里这是批评而非称赞。"},{"en":"Do not confuse it with false: a falsifiable claim can still be true.","cn":"别把它当作「假」：可证伪的说法仍可能是真的。"}],"abstract":[{"en":"Falsifiable means a claim has left itself a door through which it could be thrown out.","cn":"可证伪意味着一个说法给自己留了一扇门，好让人能把它扔出去。"},{"en":"The adjective measures courage in an idea, not correctness.","cn":"这个形容词衡量的是一个想法的勇气，而不是它的正确。"},{"en":"A claim that can lose is already taking part in the world it describes.","cn":"一个能输的说法，已经参与到它所描述的世界里了。"}]},"examples":[{"en":"A falsifiable claim states what would count against it.","cn":"可证伪的主张会说明什么结果对它不利。"},{"en":"The hypothesis was falsifiable but never actually falsified.","cn":"这个假说可证伪，却从未真的被证伪。"},{"en":"Models that are not falsifiable tend to survive for the wrong reason.","cn":"不可证伪的模型往往因为错误的理由而存活。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「佛西法伊额波」——能被做成假的，就是能被推翻的：可证伪的","word":"falsifiable"},"root":"falsify ＋ 拉丁语形容词词尾 -abilis「能够被……」；falsify 出自晚期拉丁语 falsificare，由 falsus「假」＋ facere「做」构成。作为科学哲学的关键标准，源自波普尔一九三〇年代的著作，一九五九年英译本使其通行。","sensesIntro":{"en":"Eight senses all circle one property: a claim that could be shown wrong, whether by a named observation, a counterexample, a statistical result, or an experiment built to fail.","cn":"八个义项都围绕一种性质：一个可能被证明为错的说法，无论靠点明的观测、一个反例、一组统计结果，还是一场存心设计得可能失败的实验。"},"semanticMap":{"core":{"en":"CORE IMAGE: a prediction with a trapdoor built in, through which a contrary fact could drop it.","cn":"核心意象：一条为自己装好翻板的预言，相反的事实可以从那里把它放下去。"},"chain":["FALSE","MAKE FALSE","CAN BE MADE FALSE","A NAMED TEST","A POSSIBLE COUNTEREXAMPLE","SCIENCE'S DIVIDING LINE"],"branches":[{"senses":"01 · 07","en":"THE OPEN CLAIM: able to be shown false, yet not itself false.","cn":"留了门的主张：能被证明为假，却不是假。"},{"senses":"02 · 08","en":"THE RISKY TEST: a study or theory framed so that losing is possible and informative.","cn":"有风险的检验：研究或理论的设计使失败既可能出现，又能说明问题。"},{"senses":"03 · 06","en":"THE SPECIFIC PREDICTION: a date, place or figure sharp enough for data to contradict.","cn":"具体的预测：日期、地点或数字足够明确，数据才反驳得动。"},{"senses":"04","en":"THE PUBLIC CHALLENGE: in ordinary speech, a proposal that accepts argument.","cn":"公开的质疑：在日常言语里，指肯接受争论的提案。"},{"senses":"05","en":"THE ONE EXCEPTION: logic lets a single awkward case invalidate a general rule.","cn":"那一个例外：逻辑允许一个棘手的例子使通则失效。"}]},"affixes":{"intro":{"en":"Falsifiable is a Latin verb plus a Latin capability suffix, a pattern shared by hundreds of English adjectives.","cn":"falsifiable 是一个拉丁动词加一个表示能力的拉丁词尾，这一模式在英语形容词里很常见。"},"latinIntro":{"en":"The pieces are falsus, facere and -abilis, all with clear histories.","cn":"构件为 falsus、facere 与 -abilis，来源都清楚。"},"items":[{"word":"falsifiable","structure":"falsify plus -able","meaning":"able to be made or shown false","meaningCN":"可被证明为假的","example":"The adjective is the standard term in method.","exampleCN":"这个形容词是方法论中的标准术语。"},{"word":"falsify","structure":"Late Latin falsificare","meaning":"to make false; to prove false","meaningCN":"使假；证明为假","example":"The verb keeps both directions of the word.","exampleCN":"这个动词保留了这个词的两个方向。"},{"word":"falsus","structure":"Latin adjective","meaning":"false, deceptive","meaningCN":"假的；骗人的","example":"It also gives false and falsity.","exampleCN":"它还给出 false 与 falsity。"},{"word":"facere","structure":"Latin verb","meaning":"to make, to do","meaningCN":"做；造","example":"It supplies the -fy ending.","exampleCN":"它提供 -fy 词尾。"},{"word":"-able","structure":"Latin -abilis through French","meaning":"can be, fit to be","meaningCN":"能被……的","example":"It builds readable, breakable and falsifiable.","exampleCN":"它构成可读的、易碎的与可证伪的。"},{"word":"-ability","structure":"Latin -abilitas","meaning":"the quality of being able","meaningCN":"可……的性质","example":"It turns the adjective into a noun of property.","exampleCN":"它把这个形容词变成性质名词。"},{"word":"un-","structure":"English negative prefix","meaning":"not","meaningCN":"不；非","example":"It builds unfalsifiable, the word used against bad science.","exampleCN":"它构成不可证伪，即用来批评坏科学之词。"},{"word":"-ation","structure":"Latin -atio through French","meaning":"act or process","meaningCN":"行为；过程","example":"It builds falsification from falsify.","exampleCN":"它把 falsify 变成证伪这一名词。"}],"latinEntries":[{"word":"falsificare","structure":"falsus (false) + facere (make)","meaning":"to make false; to counterfeit","meaningCN":"使假；伪造","example":"The Latin verb is the base of the English adjective.","exampleCN":"这个拉丁动词是英语形容词的词基。"},{"word":"falsus","structure":"Latin adjective falsus (false), participle of fallere","meaning":"false, deceptive","meaningCN":"假的；骗人的","example":"Latin falsus means false, and gives English false.","exampleCN":"拉丁语 falsus 意为假的，并给出英语 false。"},{"word":"-abilis","structure":"Latin adjectival suffix -abilis (able to be)","meaning":"able to be","meaningCN":"能够被……的","example":"Latin -abilis builds adjectives such as demonstrabilis.","exampleCN":"拉丁语 -abilis 构成 demonstrabilis（可证明的）这类形容词。"}],"derivatives":[{"word":"falsify","pos":"v.","zh":"证伪；伪造"},{"word":"falsifiability","pos":"n.","zh":"可证伪性"},{"word":"falsification","pos":"n.","zh":"证伪；伪造"},{"word":"unfalsifiable","pos":"adj.","zh":"不可证伪的"},{"word":"falsifier","pos":"n.","zh":"证伪者"}]}},{"word":"uncertainty","ipa_uk":"/ʌnˈsɜːtnti/","ipa_us":"/ʌnˈsɜːrtnti/","definition_zh":"不确定；不确定性；疑虑；未知之事；测量的不确定度；风险与不可预测性","definition_en":"the state of not being sure or not being known, and the range within which a measurement or forecast may vary","core_image":"一根指针停在两个刻度之间，微微抖动，既不落在这边也不落在那边","scene":"预报员看着云图，风向在半天之内改了三次，他只能说周末可能下雨也可能不下。The uncertainty in the forecast kept the organizers from booking the outdoor stage.","sceneCN":"这里指预报结果无法确定的状态（第 3 个义项：不可预测、结果未定）；句意为预报中的不确定性让主办方无法预订露天舞台。场景图取象：指针停在两个刻度之间微微抖动。","pos":[{"tag":"n.","zh":"不确定；疑虑（不可数，指心理状态）"},{"tag":"n.","zh":"不确定之事；变数（可数，常用复数）"},{"tag":"n.","zh":"不确定度（测量学，指结果可能波动的范围）"},{"tag":"n.","zh":"（经济与管理）不可预测性、风险"}],"collocations":[{"phrase":"a degree of uncertainty","zh":"一定程度的不确定"},{"phrase":"scientific uncertainty","zh":"科学上的不确定性"},{"phrase":"measurement uncertainty","zh":"测量不确定度"},{"phrase":"economic uncertainty","zh":"经济不确定性"},{"phrase":"live with uncertainty","zh":"与不确定性共处"},{"phrase":"reduce uncertainty","zh":"减少不确定性"},{"phrase":"the uncertainty principle","zh":"不确定性原理"},{"phrase":"face uncertainty","zh":"面对不确定"}],"forms":[{"label":"原形","form":"uncertainty"},{"label":"复数","form":"uncertainties"},{"label":"形容词","form":"uncertain"},{"label":"副词","form":"uncertainly"},{"label":"反义名词","form":"certainty"},{"label":"反义形容词","form":"certain"}],"derivatives":[{"word":"uncertain","pos":"adj.","zh":"不确定的；不肯定的（加表示否定的前缀，指不处于已被判定的状态）"},{"word":"certainty","pos":"n.","zh":"确定性；必然之事（去掉否定前缀后由「已被判定」的形容词加名词词尾构成）"},{"word":"certain","pos":"adj.","zh":"确定的；某个的（由拉丁语「已判定」义而来，经由表示「筛定」的动词）"},{"word":"uncertainly","pos":"adv.","zh":"没有把握地；迟疑地（在形容词后加副词词尾）"},{"word":"certitude","pos":"n.","zh":"确信；笃定（与 certain 同源的名词，多指主观上的确定感）"}],"senses":[{"no":"01","title":"Not knowing for sure","titleCN":"拿不准的状态","definition":"the state of not knowing whether something is true or what will happen","definitionCN":"不知道某事是否为真、或将会如何的状态","example":"Her uncertainty about the answer was obvious.","exampleCN":"她对答案没有把握，这一点很明显。","why":"The word negates a Latin adjective meaning settled, so it names the condition of not being settled.","whyCN":"这个词否定了一个意为「已判定」的拉丁形容词，因此指未被定下来的状态。"},{"no":"02","title":"Something not yet decided","titleCN":"尚未定下来的事","definition":"a matter whose outcome is not yet fixed, often counted in the plural","definitionCN":"结果尚未确定的事情，常用复数计数","example":"The plan has too many uncertainties to price.","exampleCN":"这个计划变数太多，无法定价。","why":"Uncertainty can be a thing as well as a mood, and business counts the things rather than the mood.","whyCN":"不确定性既能是心情，也能是事情，商界数的是事情而非心情。"},{"no":"03","title":"What cannot be predicted","titleCN":"无法预测的部分","definition":"the part of a situation that cannot be forecast, as in weather or markets","definitionCN":"局面中无法预报的部分，如天气或市场中的情形","example":"The uncertainty in the forecast kept the organizers from booking the outdoor stage.","exampleCN":"预报中的不确定性让主办方无法预订露天舞台。","why":"Forecasting separates what is known from what remains open, and the open part takes this name.","whyCN":"预报把已知与仍未定的部分分开，仍未定的那部分就用这个名字。"},{"no":"04","title":"The spread of a measurement","titleCN":"测量的不确定度","definition":"the range within which the true value of a measurement is expected to lie","definitionCN":"测量的真值预期落在其中的范围","example":"The result was reported with an uncertainty of two per cent.","exampleCN":"结果报告时附有百分之二的不确定度。","why":"Metrology refuses to give a bare number; every figure comes with the width of its doubt.","whyCN":"计量学不肯给出光秃秃的数字，每个数都带着它那份怀疑的宽度。"},{"no":"05","title":"The quantum limit","titleCN":"量子层面的限度","definition":"the limit on how precisely certain paired properties of a particle can be known at once","definitionCN":"粒子的某些成对属性无法同时被测得足够精确的限度","example":"The uncertainty principle is about knowledge, not about laboratory clumsiness.","exampleCN":"不确定性原理讲的是知识限度，而不是实验室笨手笨脚。","why":"Physics found a doubt built into nature itself, and borrowed the everyday word for it.","whyCN":"物理学发现怀疑被造进了自然本身，于是借用了日常的词来称它。"},{"no":"06","title":"Economic unpredictability","titleCN":"经济上的不可预测","definition":"unpredictability in prices, demand or policy that makes planning difficult","definitionCN":"价格、需求或政策上的不可预测，使规划变得困难","example":"Uncertainty over tariffs froze new investment.","exampleCN":"关税上的不确定让新投资停滞。","why":"Firms do not react to bad news so much as to not knowing, which is why the word dominates economics.","whyCN":"企业反应的与其说是坏消息，不如说是「不知道」，所以这个词在经济领域举足轻重。"},{"no":"07","title":"Hesitation in a person","titleCN":"人的迟疑","definition":"a feeling of doubt that makes a person hesitate or speak cautiously","definitionCN":"使人迟疑或说话谨慎的怀疑感","example":"He answered with a slight uncertainty in his voice.","exampleCN":"他回答时声音里带着一点迟疑。","why":"The inner sense is the oldest: an unsettled judgement shows in the voice before it shows in the data.","whyCN":"内心的义项最古老：未定的判断先露在声音里，然后才露在数据里。"},{"no":"08","title":"Risk that cannot be counted","titleCN":"无法计数的风险","definition":"a situation whose probabilities are unknown, distinguished from risk in which odds can be assigned","definitionCN":"概率未知的处境，与可以给出赔率的「风险」相区别","example":"Decision theory separates uncertainty from measurable risk.","exampleCN":"决策理论把不确定性与可计量的风险分开。","why":"If the odds are known it is risk; if they are not, it is uncertainty, and the distinction matters to insurers.","whyCN":"赔率已知的是风险，未知的是不确定性，这一区分对保险业至关重要。"},{"no":"09","title":"The open future","titleCN":"尚未闭合的未来","definition":"the general condition of the future being undecided, a theme in philosophy and literature","definitionCN":"未来尚未定局的一般状况，是哲学与文学的常见主题","example":"The novel turns uncertainty into a kind of freedom.","exampleCN":"这部小说把不确定变成了一种自由。","why":"If the future were closed, choice would be pointless; the word can name that openness rather than a lack.","whyCN":"若未来已经闭合，选择便无意义；这个词也能指那种敞开，而不只是一种缺失。"}],"etymology":{"intro":{"en":"Uncertainty is the negative of certainty, from Latin certus 'settled', itself from cernere 'to sift, to decide'. The root history is generally accepted; only the exact date of the English noun is uncertain.","cn":"uncertainty 是 certainty 的否定形式，certainty 出自拉丁语 certus「已定的」，而 certus 又出自 cernere「筛、判定」。词根历史一般认为可靠，只有这个英语名词的确切年代不确定。"},"items":[{"era":"CERNERE","en":"Cernere meant to sift or to separate, and from sifting came the sense of deciding a matter.","cn":"cernere 意为筛、分开，从筛选中引出判定一件事的意思。"},{"era":"CERTUS","en":"Certus meant settled or decided, said of a thing no longer in doubt.","cn":"certus 意为已定、已决，用于不再有疑问之事。"},{"era":"INCERTUS","en":"Latin added the negative prefix to make incertus, not settled, the direct ancestor of uncertain.","cn":"拉丁语加上否定前缀构成 incertus「未定的」，正是 uncertain 的直接祖先。"},{"era":"OLD FRENCH","en":"Old French uncertain and the noun forme carried the word into English in the Middle Ages.","cn":"古法语的形式把这个词与名词形态在中世纪带入英语。"},{"era":"MEASUREMENT","en":"In the nineteenth and twentieth centuries the word was given a numeric sense, the band around a measured value.","cn":"十九与二十世纪，这个词获得数量含义，指测量值周围的那一条带。"},{"era":"PHYSICS AND FINANCE","en":"Quantum theory and modern finance both made uncertainty a technical quantity, one in nature and one in markets.","cn":"量子理论与现代金融都把不确定性做成了技术量，一个在自然里，一个在市场里。"}]},"similar":{"note":{"en":"The first group shares the settled root or looks similar; the second group names neighbouring states that are often folded into uncertainty.","cn":"第一组或共享「已定」词根，或字形相近；第二组是常被并入「不确定性」的邻近状态。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"uncertain","ipa":"/ʌnˈsɜːtn/","tag":"same root","definition":"The adjective: not sure, not settled.","definitionCN":"形容词：不确定的、未定的。"},{"word":"certainty","ipa":"/ˈsɜːtnti/","tag":"same root","definition":"The positive noun: the state of being settled.","definitionCN":"肯定形式的名词：已被确定的状态。"},{"word":"certitude","ipa":"/ˈsɜːtɪtjuːd/","tag":"same root","definition":"A feeling of complete sureness, usually subjective.","definitionCN":"完全的确定感，通常指主观上的。"},{"word":"ascertain","ipa":"/əˈsɜːteɪn/","tag":"same sifting root","definition":"To find out for certain; it shares cernere but not the negative prefix.","definitionCN":"查明、确定；共享「筛定」词根，不含否定前缀。"},{"word":"uncanny","ipa":"/ʌnˈkæni/","tag":"different root","definition":"Strange in a way that unsettles; it looks like the same negative but comes from ken, knowledge.","definitionCN":"怪得令人不安；看似同一否定前缀，其实出自表示「知晓」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"doubt","ipa":"/daʊt/","tag":"near meaning","definition":"A feeling of not being convinced, the personal side of uncertainty.","definitionCN":"未被说服的感觉，是不确定性在个人身上的那一面。"},{"word":"ambiguity","ipa":"/ˌæmbɪˈɡjuːəti/","tag":"near meaning","definition":"Having more than one possible meaning, a property of statements rather than of the future.","definitionCN":"存在不止一种可能含义，是陈述的属性而非未来的属性。"},{"word":"risk","ipa":"/rɪsk/","tag":"near meaning","definition":"Exposure to a loss whose probability can be estimated.","definitionCN":"暴露于损失之中，而其概率可以估算。"},{"word":"variability","ipa":"/ˌværiəˈbɪləti/","tag":"near meaning","definition":"The tendency of a quantity to change, which produces uncertainty in measurement.","definitionCN":"数量容易变动的倾向，正是它造成测量上的不确定。"},{"word":"volatility","ipa":"/ˌvɒləˈtɪləti/","tag":"near meaning","definition":"The rate at which prices swing, a market measure of uncertainty.","definitionCN":"价格摆动的幅度，是市场对不确定性的度量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real sifting root, the real family and real fixed phrases.","cn":"正常联想使用真实的「筛定」词根、真实同族词与真实固定搭配。"},"normal":[{"en":"Certain comes from a Latin verb meaning to sift, so certainty is what survives the sieve and uncertainty is what does not.","cn":"certain 出自意为「筛」的拉丁动词，确定性是筛后留下之物，不确定性是没留下的。"},{"en":"The family pairs neatly: certain and certainty against uncertain and uncertainty.","cn":"同族词成对出现：确定的、确定性，对不确定的、不确定性。"},{"en":"Fixed phrases mark the uses: measurement uncertainty, economic uncertainty, the uncertainty principle.","cn":"固定说法标出用法：测量不确定度、经济不确定性、不确定性原理。"},{"en":"In decision theory risk has countable odds, uncertainty does not.","cn":"在决策理论里，风险有可数的赔率，不确定性没有。"},{"en":"The plural uncertainties names concrete open questions, not a mood.","cn":"复数形式指一件件还没定的事，而不是一种心情。"}],"abstract":[{"en":"Uncertainty is the space in which a decision is still a decision.","cn":"不确定性是那块空间，决定在其中还算得上决定。"},{"en":"A number without an uncertainty is a claim pretending to be a fact.","cn":"没有不确定度的数字，是假装成事实的主张。"},{"en":"Uncertainty is not the enemy of knowledge; it is the shape knowledge takes at its edges.","cn":"不确定性不是知识的敌人，而是知识在边缘处呈现的形状。"}]},"examples":[{"en":"Uncertainty about the funding delayed the whole project.","cn":"资金上的不确定拖住了整个项目。"},{"en":"Every measurement carries an uncertainty that must be stated.","cn":"每次测量都带有必须说明的不确定度。"},{"en":"She learned to work despite the uncertainty of the outcome.","cn":"她学会了在结果未定之时照样做事。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「安色滕提」——心里那根针迟迟不落定：不确定","word":"uncertainty"},"root":"certainty 的否定形式；certain 出自拉丁语 certus「已定」← cernere「筛、判定」，加否定前缀构成 incertus「未定」，经古法语进入英语。二十世纪起在测量学、量子物理与金融中获得技术含义。名词进入英语的确切年代不确定。","sensesIntro":{"en":"Nine senses move from a private doubt to a public quantity: not knowing, an open question, an unpredictable part, the spread of a measurement, the quantum limit, economic unpredictability, personal hesitation, uncountable risk, and the openness of the future.","cn":"九个义项从私人的疑虑走到公共的量：拿不准、尚未定的事、无法预测的部分、测量的不确定度、量子限度、经济上的不可预测、个人的迟疑、无法计数的风险，以及未来的敞开。"},"semanticMap":{"core":{"en":"CORE IMAGE: a needle resting between two marks and trembling, belonging to neither.","cn":"核心意象：指针停在两个刻度之间微微抖动，哪一边都不属于。"},"chain":["SIFT","DECIDE","SETTLED","NOT SETTLED","UNKNOWN FUTURE","MEASURED RANGE"],"branches":[{"senses":"01 · 07","en":"THE UNSETTLED MIND: a judgement not yet made, showing as hesitation in a voice.","cn":"未定的心：尚未作出的判断，先从声音里的迟疑露出来。"},{"senses":"02","en":"THE OPEN QUESTION: a matter whose outcome is still unfixed and can be counted.","cn":"未决的问题：结果尚未确定、还可以数出来的一件事。"},{"senses":"03 · 06","en":"THE UNFORECASTABLE: weather that may or may not hold, tariffs that may or may not change.","cn":"无法预报之物：可能下也可能不下的雨，可能改也可能不改的关税。"},{"senses":"04 · 05","en":"THE WIDTH OF A NUMBER: the band around a measured value, and the quantum limit on knowing two things at once.","cn":"数字的宽度：测量值周围那一条带，以及同时知道两件事的量子限度。"},{"senses":"08 · 09","en":"THE OPEN FUTURE: risk without countable odds, and the freedom of a future not yet closed.","cn":"敞开的未来：没有可数赔率的风险，以及尚未闭合的未来的自由。"}]},"affixes":{"intro":{"en":"Uncertainty negates a Latin adjective of settledness and turns it into an abstract noun.","cn":"uncertainty 否定一个表示「已定」的拉丁形容词，并把它变成抽象名词。"},"latinIntro":{"en":"The base is certus from cernere, with the negative prefix and the noun ending added in turn.","cn":"基础是出自 cernere 的 certus，先后加上否定前缀与名词词尾。"},"items":[{"word":"uncertainty","structure":"un- plus certainty","meaning":"the state of not being settled","meaningCN":"未被确定的状态","example":"The noun covers both a mood and a measured range.","exampleCN":"这个名词既指心情，也指测量出的范围。"},{"word":"un-","structure":"Latin and English negative prefix","meaning":"not","meaningCN":"不；未","example":"It turns certain into uncertain.","exampleCN":"它把确定的变成不确定的。"},{"word":"certus","structure":"Latin adjective","meaning":"settled, sure","meaningCN":"已定的；可靠的","example":"It comes from the verb for sifting.","exampleCN":"它出自表示筛的动词。"},{"word":"cernere","structure":"Latin verb","meaning":"to sift, to separate, to decide","meaningCN":"筛；分开；判定","example":"The image is a sieve that leaves only what is sure.","exampleCN":"意象是一只筛子，只留下确定的东西。"},{"word":"-ty","structure":"Latin -tas through French","meaning":"state or quality","meaningCN":"状态；性质","example":"It builds certainty and uncertainty.","exampleCN":"它构成确定性与不确定性。"},{"word":"certain","structure":"Latin certus through Old French","meaning":"sure, fixed","meaningCN":"确定的；固定的","example":"The adjective also means a particular one.","exampleCN":"这个形容词也有「某一个」的意思。"},{"word":"certainty","structure":"certain plus -ty","meaning":"the state of being sure","meaningCN":"确定的状态","example":"The pair makes a clean positive and negative.","exampleCN":"这一对构成干净的正与负。"},{"word":"ascertain","structure":"Latin ad- plus certus","meaning":"to find out for certain","meaningCN":"查明；确定","example":"It shares the root without the negative.","exampleCN":"它共享词根，却没有否定。"},{"word":"certitude","structure":"Latin certitudo","meaning":"subjective sureness","meaningCN":"主观的确信","example":"The noun names the feeling rather than the fact.","exampleCN":"这个名词指感觉而非事实。"}],"latinEntries":[{"word":"incertus","structure":"in- (not) + certus (settled)","meaning":"not settled, doubtful","meaningCN":"未定的；可疑的","example":"Latin incertus means not settled, doubtful.","exampleCN":"拉丁语 incertus 意为未定的、可疑的。"},{"word":"certus","structure":"Latin adjective certus (settled, sure), from cernere","meaning":"settled, sure","meaningCN":"已定的；可靠的","example":"Latin certus means settled or sure.","exampleCN":"拉丁语 certus 意为已定的、可靠的。"},{"word":"cernere","structure":"Latin verb cernere (cern-, cretum; to sift, decide)","meaning":"to sift; to decide","meaningCN":"筛；判定","example":"Latin cernere means to sift, and so to decide.","exampleCN":"拉丁语 cernere 意为筛，因而也指判定。"}],"derivatives":[{"word":"uncertain","pos":"adj.","zh":"不确定的"},{"word":"certainty","pos":"n.","zh":"确定性"},{"word":"certain","pos":"adj.","zh":"确定的；某个"},{"word":"uncertainly","pos":"adv.","zh":"没有把握地"},{"word":"certitude","pos":"n.","zh":"确信；笃定"}]}},{"word":"uncertain","ipa_uk":"/ʌnˈsɜːtn/","ipa_us":"/ʌnˈsɜːrtn/","definition_zh":"不确定的；不肯定的；没有把握的；变化无常的；结果难料的；含糊的","definition_en":"not sure or not known, and therefore not to be relied on or predicted with confidence","core_image":"一个人站在岔路口，两块路牌都半旧，字迹模糊得看不清","scene":"他拿着两张写有不同日期的通知，站在办公室门口，迟迟不敢推门。He was uncertain which date the meeting would finally take place.","sceneCN":"这里指对具体信息没有把握（第 1 个义项：不确定、不肯定）；句意为他不确定会议最终会在哪一天举行。场景图取象：人站在岔路口，两块路牌的字迹都模糊。","pos":[{"tag":"adj.","zh":"不确定的；不肯定的"},{"tag":"adj.","zh":"没有把握的；迟疑的（用于人）"},{"tag":"adj.","zh":"变化无常的；靠不住的（用于事物、天气、前景）"},{"tag":"adj.","zh":"（古义）某些；某个（已较少使用）"}],"collocations":[{"phrase":"be uncertain about","zh":"对……没有把握"},{"phrase":"uncertain outcome","zh":"难料的结果"},{"phrase":"uncertain future","zh":"不确定的前景"},{"phrase":"uncertain weather","zh":"变化无常的天气"},{"phrase":"remain uncertain","zh":"仍不确定"},{"phrase":"an uncertain smile","zh":"一个迟疑的微笑"},{"phrase":"in no uncertain terms","zh":"毫不含糊地；明确地"}],"forms":[{"label":"原形","form":"uncertain"},{"label":"名词","form":"uncertainty"},{"label":"副词","form":"uncertainly"},{"label":"比较级","form":"more uncertain"},{"label":"最高级","form":"most uncertain"},{"label":"反义形容词","form":"certain"}],"derivatives":[{"word":"uncertainty","pos":"n.","zh":"不确定；不确定性（加表示「性质、状态」的名词词尾，指未定状态或测量范围）"},{"word":"uncertainly","pos":"adv.","zh":"没有把握地；迟疑地（加副词词尾，描述动作的方式）"},{"word":"certain","pos":"adj.","zh":"确定的；某个（去掉否定前缀后的正面形式，出自拉丁语「已定」）"},{"word":"certainty","pos":"n.","zh":"确定性（正面形式的名词，与 uncertain 构成一对）"},{"word":"ascertain","pos":"v.","zh":"查明；确定（同源动词，意为把事情查清，语义上正与「不确定」相反）"}],"senses":[{"no":"01","title":"Not known for sure","titleCN":"不确定、不知道","definition":"not known with confidence, so that no firm answer can be given","definitionCN":"无法有把握地知道，因此给不出确定的答案","example":"It is uncertain whether the bridge will open this year.","exampleCN":"这座桥今年能否通车还不确定。","why":"The negative of a settled adjective simply says the matter is not settled.","whyCN":"对一个「已定」形容词的否定，只是说这件事尚未定下来。"},{"no":"02","title":"Doubtful in one's mind","titleCN":"心里没有把握","definition":"of a person, not sure about something and therefore hesitant","definitionCN":"指人对某事没有把握，因而迟疑","example":"He was uncertain how to answer the question.","exampleCN":"他不知道该怎么回答这个问题。","why":"Unsettled judgement inside a person shows outwardly as hesitation.","whyCN":"人心里未定的判断，露在外面就是迟疑。"},{"no":"03","title":"Unreliable, changeable","titleCN":"靠不住、变化无常","definition":"of weather, conditions or behaviour, likely to change and not to be depended on","definitionCN":"指天气、条件或行为容易变化，不能依赖","example":"The spring weather here is uncertain at best.","exampleCN":"这里的春天天气往好里说也是变化无常。","why":"A thing that cannot be counted on is, in the old sense, not fixed, and the word transfers from mind to world.","whyCN":"不能指望的东西按旧义就是没定下来，这个词于是从心里转到世上。"},{"no":"04","title":"An outcome still open","titleCN":"结果尚未见分晓","definition":"of an outcome or result, not yet decided and therefore impossible to plan around","definitionCN":"指结果尚未见分晓，因此无法据此安排","example":"The election remained uncertain until the last district reported.","exampleCN":"直到最后一个选区报出结果，选举仍未见分晓。","why":"The future sense is the one that matters most in politics and business, where plans need a settled result.","whyCN":"未来的义项在政治与商业里最要紧，因为规划需要一个定下来的结果。"},{"no":"05","title":"Not clearly stated","titleCN":"表述含糊","definition":"of a statement or meaning, not clear enough to settle a question","definitionCN":"指陈述或含义不够清楚，无法解决问题","example":"The letter was uncertain about the sum to be paid.","exampleCN":"这封信对要付的金额说得含糊。","why":"Ambiguity in words produces uncertainty in readers, so the adjective moved from the reader to the text.","whyCN":"文字的含糊造成读者的不确定，这个形容词于是从读者挪到了文本上。"},{"no":"06","title":"Hesitant in manner","titleCN":"举止迟疑","definition":"showing hesitation in voice, step or manner","definitionCN":"在声音、脚步或举止上显出迟疑","example":"She gave an uncertain wave from the doorway.","exampleCN":"她在门口迟疑地挥了挥手。","why":"The body leaks a doubt the mind has not yet put into words.","whyCN":"身体会把心里还没说出口的疑惑漏出来。"},{"no":"07","title":"Not established by evidence","titleCN":"证据不足、尚未确证","definition":"of a finding, not yet established by adequate evidence","definitionCN":"指某项发现尚未得到充分证据的支持","example":"The link between the two events is still uncertain.","exampleCN":"这两件事之间的关联仍未确证。","why":"Research uses the adjective to mark a claim that has not yet earned the status of a fact.","whyCN":"研究界用这个形容词标出尚未取得事实身份的主张。"},{"no":"08","title":"In no uncertain terms","titleCN":"在「毫不含糊」这一固定说法里","definition":"in the fixed phrase 'in no uncertain terms', meaning plainly and forcefully","definitionCN":"在固定说法「毫不含糊地」之中，意为直白而有力","example":"The director told them in no uncertain terms that the plan was dead.","exampleCN":"主管毫不含糊地告诉他们，这个计划已经作废。","why":"Two negatives in one phrase make a superlative of clarity, a favourite of English idiom.","whyCN":"一个短语里的两重否定把清楚推到极点，是英语习语偏爱的构造。"}],"etymology":{"intro":{"en":"Uncertain is Latin incertus, 'not settled', built from the negative prefix and certus, which comes from cernere 'to sift'. The root line is accepted; the exact date of the English borrowing is uncertain.","cn":"uncertain 来自拉丁语 incertus「未定的」，由否定前缀加 certus 构成，而 certus 出自 cernere「筛」。词根线索一般认为可靠，进入英语的确切年代不确定。"},"items":[{"era":"CERNERE","en":"Cernere meant to sift, to separate and, by extension, to decide a disputed matter.","cn":"cernere 意为筛、分开，引申为裁定有争议的事。"},{"era":"CERTUS","en":"Certus described what has been decided and no longer admits doubt.","cn":"certus 描述已经判定、不再容有疑问的东西。"},{"era":"INCERTUS","en":"The negative prefix produced incertus, unsettled, the immediate Latin source of the English word.","cn":"否定前缀造出 incertus「未定的」，是英语这个词的直接拉丁语来源。"},{"era":"OLD FRENCH","en":"Old French passed the adjective to English in the thirteenth and fourteenth centuries, first in religious and legal prose.","cn":"古法语在十三、十四世纪把这个形容词传给英语，最早见于宗教与法律文本。"},{"era":"EVERYDAY WIDENING","en":"By the modern period it covered weather, outcomes and manners, not only matters of judgement.","cn":"到近代，它覆盖天气、结果与举止，不再只指判断上的事。"},{"era":"IDIOM","en":"The phrase 'in no uncertain terms' fixed the word in a double negative that means extreme clarity.","cn":"「毫不含糊地」这一说法把这个词固定在一个双重否定里，意为极其清楚。"}]},"similar":{"note":{"en":"The first group shares the settled root or looks close; the second group holds the words that overlap with uncertain in ordinary use.","cn":"第一组或共享「已定」词根，或字形相近；第二组是日常使用中与「不确定」重叠的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"uncertainty","ipa":"/ʌnˈsɜːtnti/","tag":"same root","definition":"The noun: the state and the measured range.","definitionCN":"名词：未定状态与测量范围。"},{"word":"certain","ipa":"/ˈsɜːtn/","tag":"same root","definition":"The positive adjective: sure, or a particular one.","definitionCN":"肯定形式的形容词：确定的，或指某一个。"},{"word":"uncertainly","ipa":"/ʌnˈsɜːtnli/","tag":"same root","definition":"The adverb for acting without confidence.","definitionCN":"副词：没有把握地行动。"},{"word":"ascertain","ipa":"/əˈsɜːteɪn/","tag":"same sifting root","definition":"To establish something for certain, the direct opposite action.","definitionCN":"确定某事，正是相反的动作。"},{"word":"uncanny","ipa":"/ʌnˈkæni/","tag":"different root","definition":"Unsettlingly strange; the negative prefix is the same but the root means knowledge.","definitionCN":"怪得令人不安；否定前缀相同，词根却意为知晓。"}]},{"heading":"NEAR MEANING","entries":[{"word":"doubtful","ipa":"/ˈdaʊtfl/","tag":"near meaning","definition":"Unlikely or open to doubt, often said of a prospect.","definitionCN":"不太可能或可存疑，多用于前景。"},{"word":"unsure","ipa":"/ˌʌnˈʃʊə/","tag":"near meaning","definition":"Not confident in oneself, the personal and informal twin.","definitionCN":"对自己没有信心，更口语、更指个人的说法。"},{"word":"unclear","ipa":"/ˌʌnˈklɑː/","tag":"near meaning","definition":"Not explained well enough to be understood, said of statements.","definitionCN":"说明得不够清楚，多用于陈述。"},{"word":"ambivalent","ipa":"/ˌæmbɪˈveɪlənt/","tag":"near meaning","definition":"Holding two feelings at once, which is different from lacking knowledge.","definitionCN":"同时抱有两种感受，与缺乏信息不同。"},{"word":"unpredictable","ipa":"/ˌʌnprɪˈdɪktəbl/","tag":"near meaning","definition":"Impossible to forecast, the strong form of what uncertain says about the future.","definitionCN":"无法预报，是「不确定」在未来的强式说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real sifting root, the real family and real fixed phrases.","cn":"正常联想使用真实的「筛定」词根、真实同族词与真实固定搭配。"},"normal":[{"en":"Certain is what the sieve keeps, so uncertain is what ran through it.","cn":"确定的，是筛子留下的；不确定的，是从筛眼里跑掉的。"},{"en":"The pair uncertain and certainty is one of the cleanest positive and negative pairs in English.","cn":"uncertain 与 certainty 是英语里最干净的一对正否词之一。"},{"en":"Fixed phrases mark the uses: uncertain outcome, uncertain future, remain uncertain, in no uncertain terms.","cn":"固定说法标出用法：难料的结果、不确定的前景、仍不确定、毫不含糊地。"},{"en":"The adverb uncertainly describes the hesitant wave and the hesitating step.","cn":"副词形式描述迟疑的挥手与迟疑的脚步。"},{"en":"The idiom in no uncertain terms doubles the negative to mean absolute clarity.","cn":"固定说法「毫不含糊地」用双重否定表达绝对的清楚。"}],"abstract":[{"en":"To be uncertain is to hold a question open instead of closing it too early.","cn":"不确定就是把问题留着，而不是过早把它关上。"},{"en":"An uncertain person is not a weak one; the weak one is the one who cannot say so.","cn":"不确定的人并不软弱；软弱的是那个说不出这句话的人。"},{"en":"An uncertain answer leaves room for the next question.","cn":"一个不确定的回答，为下一个问题留下了余地。"}]},"examples":[{"en":"The committee was uncertain about the cost of the repairs.","cn":"委员会对修缮费用没有把握。"},{"en":"An uncertain market kept buyers away all autumn.","cn":"市场前景不明，整个秋天买家都不肯进场。"},{"en":"She said in no uncertain terms that the deadline would stand.","cn":"她毫不含糊地说，截止日期不会更改。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「安色滕」——站在岔路口两块牌子都看不清：不确定的","word":"uncertain"},"root":"拉丁语 incertus「未定的」← 否定前缀＋ certus「已定的」← cernere「筛、判定」；经古法语于十三、十四世纪进入英语。与 certainty、certain、ascertain 同源；「毫不含糊地」为固定习语。确切借入年代不确定。","sensesIntro":{"en":"Eight senses spread from the mind to the world: not knowing, personal doubt, changeable conditions, an open outcome, unclear wording, hesitant manner, unproven evidence, and the fixed phrase of absolute clarity.","cn":"八个义项从心里铺到世上：不知道、心里的迟疑、变化无常的状况、尚未见分晓的结果、含糊的措辞、迟疑的举止、证据不足，以及表示绝对清楚的固定说法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a traveller at a fork where both signs have weathered past legibility.","cn":"核心意象：旅人站在岔路口，两块路牌都被风雨磨得看不清字。"},"chain":["SIFT","DECIDE","SETTLED","NOT SETTLED","NOT RELIABLE","NOT YET KNOWN"],"branches":[{"senses":"01 · 07","en":"THE UNKNOWABLE FACT: a question without an answer, or a finding without enough evidence.","cn":"不可知的事实：没有答案的问题，或证据不足的发现。"},{"senses":"02 · 06","en":"THE HESITANT PERSON: a mind not made up yet, and a body that shows it.","cn":"迟疑的人：心里还没定，身体先露了出来。"},{"senses":"03","en":"THE UNRELIABLE THING: weather and conditions that cannot be counted on.","cn":"靠不住的事物：不能指望的天气与状况。"},{"senses":"04","en":"THE OPEN OUTCOME: an election or plan whose result has not yet appeared.","cn":"未定的结果：选举或计划的结果尚未出现。"},{"senses":"05 · 08","en":"THE UNCLEAR WORD: ambiguous wording, and the idiom that doubles the negative to mean perfect clarity.","cn":"含糊的措辞：语义不明的文字，以及用双重否定表示绝对清楚的那个习语。"}]},"affixes":{"intro":{"en":"Uncertain is a negative prefix on a Latin adjective of settledness, the same base as certainty and ascertain.","cn":"uncertain 是在表示「已定」的拉丁形容词前加否定前缀，与 certainty、ascertain 同一基础。"},"latinIntro":{"en":"Latin incertus is the direct source; certus and cernere lie behind it.","cn":"拉丁语 incertus 是直接来源，其背后是 certus 与 cernere。"},"items":[{"word":"uncertain","structure":"Latin incertus, through Old French","meaning":"not settled, not sure","meaningCN":"未定的；没有把握的","example":"The adjective covers both knowledge and reliability.","exampleCN":"这个形容词既管知识，也管可靠性。"},{"word":"un-","structure":"Latin and English negative prefix","meaning":"not","meaningCN":"不；未","example":"It negates the settled adjective.","exampleCN":"它否定那个表示已定的形容词。"},{"word":"certus","structure":"Latin adjective","meaning":"settled, sure","meaningCN":"已定的；可靠的","example":"It is the source of certain and certainty.","exampleCN":"它是 certain 与 certainty 的来源。"},{"word":"cernere","structure":"Latin verb","meaning":"to sift; to decide","meaningCN":"筛；判定","example":"The sieve image explains why certainty feels like what is left.","exampleCN":"筛子的意象解释了为什么确定性像是筛剩之物。"},{"word":"-tain","structure":"Latin -tus through French","meaning":"held, established","meaningCN":"持有；确立","example":"It appears in ascertain, to hold something as certain.","exampleCN":"它出现在 ascertain 中，意为把某事确认下来。"},{"word":"certainty","structure":"certain plus -ty","meaning":"the state of being sure","meaningCN":"已定的状态","example":"The noun is the positive partner of uncertainty.","exampleCN":"这个名词是不确定性的肯定搭档。"},{"word":"uncertainly","structure":"uncertain plus -ly","meaning":"in a hesitant way","meaningCN":"迟疑地","example":"The adverb marks the manner of a doubtful action.","exampleCN":"这个副词标出存疑动作的方式。"},{"word":"ascertain","structure":"Latin ad- plus certus","meaning":"to make certain by inquiry","meaningCN":"经查问而确定","example":"The verb is the remedy for uncertainty.","exampleCN":"这个动词正是不确定的解药。"}],"latinEntries":[{"word":"incertus","structure":"in- (not) + certus (settled)","meaning":"not settled, doubtful","meaningCN":"未定的；可疑的","example":"English uncertain renders this Latin adjective directly.","exampleCN":"英语 uncertain 直接对应这个拉丁形容词。"},{"word":"certus","structure":"Latin adjective certus (settled, sure), from cernere","meaning":"settled, sure","meaningCN":"已定的；可靠的","example":"The adjective supplies the certainty the prefix denies.","exampleCN":"这个形容词提供被前缀否定的那份「确定」。"},{"word":"cernere","structure":"Latin verb cernere (cern-, cretum; to sift, decide)","meaning":"to sift; to decide","meaningCN":"筛；判定","example":"The verb gives the deciding behind certus.","exampleCN":"这个动词给出 certus 背后的「判定」。"}],"derivatives":[{"word":"uncertainty","pos":"n.","zh":"不确定；不确定性"},{"word":"uncertainly","pos":"adv.","zh":"没有把握地；迟疑地"},{"word":"certain","pos":"adj.","zh":"确定的；某个"},{"word":"certainty","pos":"n.","zh":"确定性"},{"word":"ascertain","pos":"v.","zh":"查明；确定"}]}},{"word":"limitation","ipa_uk":"/ˌlɪmɪˈteɪʃn/","ipa_us":"/ˌlɪməˈteɪʃn/","definition_zh":"限制；限度；局限；不足之处；（法律）诉讼时效；责任限额；权利或地产的限定","definition_en":"a rule or condition that limits something, and a weakness or shortcoming that a method or person cannot pass","core_image":"一条画在路面上的白线，把可以走的范围圈在里面，圈外一步也不许越","scene":"论文末尾专门用一节说明样本太小、只覆盖一所学校，提醒读者结论不能推得太远。Every study states its limitations so that readers know how far the findings can travel.","sceneCN":"这里指研究自身的不足之处（第 4 个义项：局限、不足）；句意为每项研究都要说明自己的局限，读者才知道结论能走多远。场景图取象：路面上一条白线把可行范围圈住。","pos":[{"tag":"n.","zh":"限制；限度（可数或不可数）"},{"tag":"n.","zh":"局限；不足之处（多用复数）"},{"tag":"n.","zh":"（法律）诉讼时效；法定期间"},{"tag":"n.","zh":"（法律）责任限额；权利限定"}],"collocations":[{"phrase":"limitations of the study","zh":"研究的局限"},{"phrase":"a serious limitation","zh":"严重的局限"},{"phrase":"time limitation","zh":"时间限制"},{"phrase":"limitation of liability","zh":"责任限额"},{"phrase":"statute of limitations","zh":"诉讼时效法规"},{"phrase":"impose limitations on","zh":"对……施加限制"},{"phrase":"recognize the limitations","zh":"承认局限"},{"phrase":"within the limitations","zh":"在限度之内"}],"forms":[{"label":"原形","form":"limitation"},{"label":"复数","form":"limitations"},{"label":"动词","form":"limit"},{"label":"形容词","form":"limited"},{"label":"形容词（无限的）","form":"limitless"},{"label":"名词（界限）","form":"limit"}],"derivatives":[{"word":"limit","pos":"n./v.","zh":"界限；限制（由拉丁语「边界」一词直接借入，兼指界线与设界之举）"},{"word":"limited","pos":"adj.","zh":"有限的；受限制的（动词过去分词转形容词，指数量或范围受约束）"},{"word":"limitless","pos":"adj.","zh":"无限的；无边的（加表示「没有」的形容词后缀）"},{"word":"delimitation","pos":"n.","zh":"划定界限；划界（加表示「去除、划分」的前缀，指把边界明确画出）"},{"word":"limiting","pos":"adj.","zh":"限制性的（现在分词转形容词，指起约束作用）"},{"word":"unlimited","pos":"adj.","zh":"无限的；不受限制的（加否定前缀，指没有设上限）"}],"senses":[{"no":"01","title":"The act of limiting","titleCN":"施加限制这一动作","definition":"the act of keeping something within bounds, or the state of being kept within them","definitionCN":"把某物保持在范围之内的动作，或受此约束的状态","example":"The limitation of outdoor gatherings began in October.","exampleCN":"户外聚集的限制从十月开始。","why":"The noun comes from a Latin verb meaning to bound, so the act of drawing the line is the oldest sense.","whyCN":"这个名词出自意为「划界」的拉丁动词，画线这个动作是最古老的义项。"},{"no":"02","title":"A rule that restricts","titleCN":"一条限制性规定","definition":"a rule, condition or cap that restricts what may be done, used or claimed","definitionCN":"限制可以做什么、用多少或主张什么的规则、条件或上限","example":"The contract places a limitation on how many copies may be made.","exampleCN":"合同对可以制作多少份副本设了限制。","why":"Once a line is drawn, people need it written down, and the written line is this sense.","whyCN":"线一旦画出，人们就需要把它写下来，写下来的线就是这一义项。"},{"no":"03","title":"A cap on money or time","titleCN":"金额或时间的上限","definition":"a fixed upper amount of money, time or resources allowed for a purpose","definitionCN":"为某项用途所允许的金钱、时间或资源的固定上限","example":"There is a strict limitation on the daily water supply.","exampleCN":"每日供水量有严格上限。","why":"Budgets and clocks are the most concrete boundaries, so the word settles there first.","whyCN":"预算与时钟是最具体的边界，这个词先在这里落脚。"},{"no":"04","title":"A weakness of a method","titleCN":"方法或研究的局限","definition":"a shortcoming in a study, method or tool that limits what its results can support","definitionCN":"研究、方法或工具中的不足，限制了其结果能支撑的结论","example":"Every study states its limitations so that readers know how far the findings can travel.","exampleCN":"每项研究都要说明自己的局限，读者才知道结论能走多远。","why":"Science uses the plural to admit what a design cannot see, and that candour is part of the method.","whyCN":"科学用复数形式承认设计看不到的东西，这种坦白本身就是方法的一部分。"},{"no":"05","title":"The statute of limitations","titleCN":"诉讼时效","definition":"the legal time limit within which a claim must be brought before it is barred","definitionCN":"必须在期限之内提起诉讼、逾期即丧失胜诉权的法定时限","example":"The claim was dismissed because the limitation had expired.","exampleCN":"由于时效已过，这项请求被驳回。","why":"Law puts a clock on every right, and the time limit is named after the limiting itself.","whyCN":"法律给每项权利都装上时钟，这个时限就以「限制」这个动作为名。"},{"no":"06","title":"A cap on liability","titleCN":"责任限额","definition":"a contractual maximum on the amount one party must pay for loss or damage","definitionCN":"合同规定的、一方对损失或损害必须支付的最高金额","example":"The insurer accepted a limitation of liability of two million.","exampleCN":"保险人接受了二百万的责任限额。","why":"Risk is made bearable by naming the worst number in advance, and the clause is named after that cap.","whyCN":"事先把最坏的数字写出来，风险才可承受，这条款便以那个上限命名。"},{"no":"07","title":"A limit on an estate or right","titleCN":"对权利或地产的限定","definition":"a legal restriction on how long an estate or right may last or how it may pass","definitionCN":"对某项地产或权利存续时间或转让方式的法定限定","example":"The deed carried a limitation on the sale of the land.","exampleCN":"这份契据对土地的出售作了限定。","why":"Property law inherited the Roman boundary word and uses it for estates cut down to a fixed term.","whyCN":"财产法继承了罗马的边界词，用它指被限定为固定期限的产权。"},{"no":"08","title":"A caveat in an argument","titleCN":"论证中的保留条件","definition":"a qualification attached to a claim so that it is not taken too broadly","definitionCN":"附加在主张之上的限定条件，使其不被过度推广","example":"He added a limitation: the rule holds only for small firms.","exampleCN":"他加了一个限定：这条规则只适用于小公司。","why":"A wise claim fences its own reach, and the fence is called a limitation.","whyCN":"审慎的主张会替自己围出边界，这道围栏就叫限定。"},{"no":"09","title":"A boundary in space","titleCN":"空间上的边界","definition":"an outer boundary or edge, the oldest physical sense of the root","definitionCN":"外部的边界或边缘，是这个词根最古老的具体含义","example":"The limitation of the old city wall still shows on the map.","exampleCN":"旧城墙的边界在地图上仍看得出来。","why":"The Latin word meant a frontier between fields, and every later sense is a descendant of that ditch.","whyCN":"这个拉丁词本指田地之间的地界，后来所有义项都是那条沟的后代。"}],"etymology":{"intro":{"en":"Limitation comes from Latin limitare 'to bound', from limes, 'boundary, frontier'. The line of descent is clear; the exact date of the English noun is uncertain.","cn":"limitation 来自拉丁语 limitare「划界」，出自 limes「边界、前线」。词源线索清楚，这个英语名词出现的确切年代不确定。"},"items":[{"era":"LATIN LIMES","en":"Limes meant a boundary line, a frontier between fields or between provinces of the empire.","cn":"limes 意为边界线，是田地之间或帝国行省之间的分界线。"},{"era":"LIMITARE","en":"The verb limitare meant to mark a boundary and, by extension, to keep something within it.","cn":"动词 limitare 意为标出边界，引申为把某物留在边界之内。"},{"era":"LATIN LIMITATIO","en":"Limitio and limitatio named the marking of a bound, a word of surveyors and lawyers.","cn":"limitio 与 limitatio 指划定边界，是测量员与法律人的用语。"},{"era":"ENGLISH ENTRY","en":"The noun entered English in the fifteenth century through legal and scholarly French; the exact date is uncertain.","cn":"这个名词在十五世纪经由法律与学术法语进入英语；确切年代不确定。"},{"era":"SCIENCE AND INSURANCE","en":"Modern English split the word two ways: the limitations of a study, and the limitation of liability in a contract.","cn":"现代英语把这个词分成两支：研究的局限，以及合同中的责任限额。"},{"era":"LAW OF TIME","en":"The statute of limitations gave the word a clock, naming the period beyond which a right cannot be pursued.","cn":"诉讼时效法规给这个词装上了时钟，指超过之后权利便无法追索的期间。"}]},"similar":{"note":{"en":"The first group shares the boundary root or looks close; the second group holds the words that often stand in for limitation in argument and in law.","cn":"第一组或共享「边界」词根，或字形相近；第二组是论证与法律中常替代「限制、局限」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"limit","ipa":"/ˈlɪmɪt/","tag":"same root","definition":"The plain noun and verb for a boundary or a cap.","definitionCN":"最朴素的边界或上限名词，也可作动词。"},{"word":"limited","ipa":"/ˈlɪmɪtɪd/","tag":"same root","definition":"Restricted in amount or scope, the adjective.","definitionCN":"在数量或范围上受限制的形容词。"},{"word":"delimitation","ipa":"/ˌdiːlɪmɪˈteɪʃn/","tag":"same root","definition":"The drawing of a boundary, especially between states or fields.","definitionCN":"划定边界，尤指国界或领域之间。"},{"word":"eliminate","ipa":"/ˈelɪmɪneɪt/","tag":"different root","definition":"To remove something; it looks like the same family but comes from limen, a threshold.","definitionCN":"清除某物；看似同族，其实出自意为「门槛」的 limen。"},{"word":"liminal","ipa":"/ˈlɪmɪnl/","tag":"different root","definition":"Occupying a threshold or in-between state, from limen rather than limes.","definitionCN":"处于门槛或过渡状态，出自 limen 而非 limes。"}]},{"heading":"NEAR MEANING","entries":[{"word":"restriction","ipa":"/rɪˈstrɪkʃn/","tag":"near meaning","definition":"A rule that prevents something, often imposed by authority.","definitionCN":"阻止某事的规则，通常由权威施加。"},{"word":"constraint","ipa":"/kənˈstreɪnt/","tag":"near meaning","definition":"A factor that forces a choice, close to limitation in research writing.","definitionCN":"迫使作出选择的因素，在研究写作中接近「局限」。"},{"word":"shortcoming","ipa":"/ˈʃɔːtkʌmɪŋ/","tag":"near meaning","definition":"A failure to reach a standard, the plain word for a weakness.","definitionCN":"未能达到标准，是最朴素的「缺点」说法。"},{"word":"drawback","ipa":"/ˈdrɔːbæk/","tag":"near meaning","definition":"A disadvantage that makes something less attractive.","definitionCN":"使某物吸引力下降的不利之处。"},{"word":"caveat","ipa":"/ˈkeɪviət/","tag":"near meaning","definition":"A warning or condition attached to a claim or permission.","definitionCN":"附在主张或许可之上的警告或条件。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real frontier word, the real family and real fixed phrases.","cn":"正常联想使用真实的「边界」词、真实同族词与真实固定搭配。"},"normal":[{"en":"Limes meant the frontier of the empire, so a limitation is a line drawn at the edge of what is allowed.","cn":"limes 指帝国的前线，限制就是画在允许范围边缘的一条线。"},{"en":"The family runs limit, limited, limitless and delimitation.","cn":"同族词有 limit、limited、limitless 与 delimitation。"},{"en":"Fixed phrases mark the uses: limitations of the study, time limitation, limitation of liability.","cn":"固定说法标出用法：研究的局限、时间限制、责任限额。"},{"en":"In law the plural has a life of its own: the statute of limitations.","cn":"在法律里复数形式自成一体：诉讼时效。"},{"en":"Eliminate and liminal are false friends; they come from limen, a threshold.","cn":"eliminate 与 liminal 是假朋友，它们出自意为门槛的 limen。"}],"abstract":[{"en":"A limitation honestly stated is a gift to the reader, not a weakness of the writer.","cn":"老实说出的局限是给读者的礼物，而不是作者的无能。"},{"en":"Every boundary that keeps something in also keeps something out.","cn":"每道把东西圈进来的边界，也把另一些东西关在外面。"},{"en":"The line that protects also instructs; it tells you where the work begins.","cn":"起保护作用的线同时在指路，它告诉你工作从哪里开始。"}]},"examples":[{"en":"The report lists three limitations of its own method.","cn":"报告列出自身方法的三处局限。"},{"en":"A limitation on imports raised the price of steel.","cn":"进口限制抬高了钢材价格。"},{"en":"The suit was filed within the limitation period.","cn":"诉讼是在时效期间内提起的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「利米泰申」——地上画一条白线，线外不许走：限制、局限","word":"limitation"},"root":"拉丁语 limitare「划界」← limes「边界、前线」；经法律与学术法语于十五世纪进入英语。同族有 limit、limited、delimitation；eliminate 与 liminal 出自 limen「门槛」，属形近不同源。名词进入英语的确切年代不确定。","sensesIntro":{"en":"Nine senses all descend from one boundary: the act of bounding, a restricting rule, a cap on money or time, a weakness of method, the statute of limitations, a liability cap, a limit on an estate, a caveat in argument, and a boundary in space.","cn":"九个义项都出自同一条边界：划界之举、限制性规定、金额或时间的上限、方法的局限、诉讼时效、责任限额、对地产或权利的限定、论证中的保留，以及空间上的边界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a white line painted across a road, with everything beyond it out of bounds.","cn":"核心意象：路面上画着一条白线，线外一切都不得越过。"},"chain":["BOUNDARY","DRAW THE LINE","KEEP WITHIN","A RULE","A WEAKNESS","A TIME LIMIT"],"branches":[{"senses":"01 · 09","en":"THE LINE ITSELF: a frontier drawn in space, and the act of drawing it.","cn":"线本身：在空间里画出的边界，以及画线的动作。"},{"senses":"02 · 03","en":"THE WRITTEN CAP: a rule or a fixed amount of money, time or water that may not be exceeded.","cn":"写下来的上限：不可超过的规则，或金钱、时间、用水的定额。"},{"senses":"04 · 08","en":"THE HONEST WEAKNESS: what a method cannot see, and the caveat that keeps a claim from spreading too far.","cn":"诚实的弱点：方法看不到的东西，以及防止主张过度扩张的保留。"},{"senses":"05 · 07","en":"THE LEGAL CLOCK AND DEED: a period after which a right is barred, and a term fixed on an estate.","cn":"法律的时钟与契据：过期即失权的期间，以及为地产设定的期限。"},{"senses":"06","en":"THE LIABILITY CAP: the worst number named in advance so that risk can be borne.","cn":"责任限额：事先写出的最坏数字，好让风险可以承担。"}]},"affixes":{"intro":{"en":"Limitation is a Latin boundary word turned into an abstract noun, with a family that runs through law and science.","cn":"limitation 是把一个拉丁边界词变成抽象名词，其词族贯穿法律与科学。"},"latinIntro":{"en":"Limes and limitare are the sources; the noun ending came through Latin limitatio.","cn":"limes 与 limitare 是来源，名词词尾经由拉丁语 limitatio 而来。"},"items":[{"word":"limitation","structure":"Latin limitatio","meaning":"a marking of bounds; a restriction","meaningCN":"划定边界；限制","example":"The noun covers a rule, a weakness and a legal period.","exampleCN":"这个名词兼指规定、弱点与法定期间。"},{"word":"limes","structure":"Latin noun","meaning":"boundary, frontier","meaningCN":"边界；前线","example":"It named the edge of a field or of an empire.","exampleCN":"它指田地或帝国的边缘。"},{"word":"limitare","structure":"Latin verb","meaning":"to bound, to mark a limit","meaningCN":"划界；设限","example":"The verb supplies the action behind the noun.","exampleCN":"这个动词提供名词背后的动作。"},{"word":"-ation","structure":"Latin -atio through French","meaning":"act or process","meaningCN":"行为；过程","example":"It builds limitation, demarcation and estimation.","exampleCN":"它构成限制、划界与估计等词。"},{"word":"limit","structure":"Latin limes through French","meaning":"a boundary; to bound","meaningCN":"界限；限制","example":"The short form is both noun and verb.","exampleCN":"短形既可作名词也可作动词。"},{"word":"limited","structure":"limit plus -ed","meaning":"restricted","meaningCN":"受限制的","example":"The participle became the everyday adjective.","exampleCN":"过去分词成了日常形容词。"},{"word":"-less","structure":"English suffix","meaning":"without","meaningCN":"没有……的","example":"It builds limitless, the opposite of limited.","exampleCN":"它构成 limitless，即 limited 的反面。"},{"word":"de-","structure":"Latin prefix","meaning":"off, away; marking out","meaningCN":"去除；划出","example":"It builds delimitation, the drawing of a border.","exampleCN":"它构成 delimitation，即划定边界。"},{"word":"-ing","structure":"English suffix","meaning":"having the quality of","meaningCN":"具有……性质的","example":"It builds limiting, as in a limiting factor.","exampleCN":"它构成 limiting，如限制因素。"}],"latinEntries":[{"word":"limes","structure":"Latin noun limes (limit-, boundary)","meaning":"boundary, frontier","meaningCN":"边界；前线","example":"Latin limes means boundary or frontier.","exampleCN":"拉丁语 limes 意为边界、前线。"},{"word":"limitare","structure":"limes (boundary) + -are (verb ending)","meaning":"to bound; to limit","meaningCN":"划界；限制","example":"Medieval Latin limitare means to mark a boundary.","exampleCN":"中世纪拉丁语 limitare 意为划定边界。"},{"word":"limitatio","structure":"limitare + -tio (noun of action)","meaning":"a marking of bounds","meaningCN":"划定边界","example":"Latin limitatio means a marking of bounds.","exampleCN":"拉丁语 limitatio 意为划定界限。"}],"derivatives":[{"word":"limit","pos":"n./v.","zh":"界限；限制"},{"word":"limited","pos":"adj.","zh":"有限的"},{"word":"limitless","pos":"adj.","zh":"无限的"},{"word":"delimitation","pos":"n.","zh":"划界；界定"},{"word":"limiting","pos":"adj.","zh":"限制性的"}]}},{"word":"procedural","ipa_uk":"/prəˈsiːdʒərəl/","ipa_us":"/prəˈsiːdʒərəl/","definition_zh":"程序的；程序性的；手续上的；（法律）程序法的；按步骤操作的","definition_en":"relating to the steps or rules by which something is done, rather than to its substance or result","core_image":"一张按序号排好的流程图贴在墙上，每一步都用箭头连到下一步","scene":"法官没有讨论谁更有理，而是先问警方取证时是否按规定的步骤通知了当事人。The court raised a procedural question about whether the search had followed the required steps.","sceneCN":"这里指与程序、步骤有关的（第 2 个义项：法律程序上的）；句意为法院提出了一个程序问题，即这次搜查是否按规定的步骤进行。场景图取象：墙上贴着按序号排好的流程图。","pos":[{"tag":"adj.","zh":"程序的；程序性的"},{"tag":"adj.","zh":"（法律）程序法的；与程序有关的"},{"tag":"adj.","zh":"（计算机）过程式的；按步骤展开的"}],"collocations":[{"phrase":"procedural rules","zh":"程序规则"},{"phrase":"procedural fairness","zh":"程序公正"},{"phrase":"procedural justice","zh":"程序正义"},{"phrase":"procedural law","zh":"程序法"},{"phrase":"procedural error","zh":"程序性错误"},{"phrase":"procedural safeguards","zh":"程序性保障"},{"phrase":"procedural programming","zh":"过程式编程"},{"phrase":"procedural motion","zh":"程序性动议"}],"forms":[{"label":"原形","form":"procedural"},{"label":"名词","form":"procedure"},{"label":"副词","form":"procedurally"},{"label":"比较级","form":"more procedural"},{"label":"最高级","form":"most procedural"},{"label":"相关名词（程序规则）","form":"proceduralism"}],"derivatives":[{"word":"procedure","pos":"n.","zh":"程序；步骤；手续（由表示「向前走」的拉丁动词加名词词尾构成，指一步步走的路径）"},{"word":"procedurally","pos":"adv.","zh":"在程序上；按程序地（加副词词尾，指从程序角度看）"},{"word":"proceed","pos":"v.","zh":"继续进行；行进（同源动词，字面即「向前走」，是 procedure 的动作基础）"},{"word":"proceedings","pos":"n.","zh":"诉讼程序；会议记录（现在分词转名词，指正在进行的一系列步骤）"},{"word":"process","pos":"n./v.","zh":"过程；处理（同出「向前走」的拉丁词根，但走的是另一条名词化路径）"},{"word":"proceduralism","pos":"n.","zh":"程序主义（在形容词后加表示「学说、倾向」的后缀，指重视程序的立场）"}],"senses":[{"no":"01","title":"Belonging to the steps","titleCN":"属于步骤本身的","definition":"relating to the way in which something is done, rather than to what is done","definitionCN":"关涉做事的方式与步骤，而非所做之事的内容","example":"The change was procedural, not a matter of policy.","exampleCN":"这一改动是程序上的，不涉及政策本身。","why":"The base noun procedure names a path walked step by step, so the adjective marks the path rather than the destination.","whyCN":"基础名词指一步步走过的路径，因此这个形容词标的是路径而非终点。"},{"no":"02","title":"Of the rules of court","titleCN":"法庭规则上的","definition":"concerning the rules that govern how a legal case is conducted","definitionCN":"关于主导案件如何审理的规则的","example":"The appeal was lost on procedural grounds.","exampleCN":"上诉因程序上的理由而失败。","why":"Law separates substance from procedure, and the adjective names the second half of that split.","whyCN":"法律把实体与程序分开，这个形容词指这一划分的后一半。"},{"no":"03","title":"Fair in the way it is done","titleCN":"程序上的公正","definition":"describing fairness in the process itself, such as being heard before a decision","definitionCN":"指过程本身的公正，例如在决定之前有陈述的机会","example":"Procedural fairness required the board to hear both sides.","exampleCN":"程序公正要求委员会听取双方意见。","why":"A good result reached by a bad path is still suspect, so fairness attaches to the steps.","whyCN":"用坏路径得到的好结果仍然可疑，所以公正落在步骤上。"},{"no":"04","title":"Safeguards against error","titleCN":"防止出错的程序保障","definition":"of rules designed to catch mistakes, such as a second reading or a signature","definitionCN":"指为发现错误而设的规则，如二次审读或签名确认","example":"The agency added procedural checks before approving loans.","exampleCN":"该机构在批准贷款前增加了程序性核查。","why":"Bureaucracy is often defended as a set of small procedural brakes on haste.","whyCN":"官僚程序常被辩护为一组对仓促行事的小小刹车。"},{"no":"05","title":"Step-by-step in computing","titleCN":"计算机里的过程式","definition":"of a programming style built from named sequences of instructions, as opposed to object-oriented style","definitionCN":"指由命名的指令序列构成的编程风格，与面向对象风格相对","example":"The course starts with procedural programming in a simple language.","exampleCN":"这门课从简单语言的过程式编程讲起。","why":"Software borrowed the word for code that reads like a list of steps to be walked through.","whyCN":"软件领域借这个词指读起来像一串待走步骤的代码。"},{"no":"06","title":"Of a parliamentary motion","titleCN":"议会程序性的","definition":"concerning the conduct of a meeting, such as a motion on speaking time","definitionCN":"关于会议如何进行的，如关于发言时间的动议","example":"The chair ruled the objection procedural and set it aside.","exampleCN":"主席裁定这一异议属程序问题，暂不处理。","why":"Assemblies run on rules of order, and a procedural motion keeps the argument about the rules.","whyCN":"议会依议事规则运转，程序性动议把争论留在规则层面。"},{"no":"07","title":"Characteristic of a procedure","titleCN":"带步骤特征的","definition":"having the character of a routine, done in a fixed order without much judgement","definitionCN":"带有例行程序的特征，按固定次序执行而少有判断","example":"The interview felt procedural, with the same questions for everyone.","exampleCN":"这场面谈显得很程序化，每个人都问同样的问题。","why":"When a human act becomes a fixed sequence, the adjective moves from describing rules to describing behaviour.","whyCN":"当人的行为变成固定序列，这个形容词就从描述规则转为描述举止。"},{"no":"08","title":"Of medical procedures","titleCN":"医疗操作上的","definition":"relating to a medical or surgical procedure rather than to diagnosis alone","definitionCN":"关涉医疗或外科操作本身，而非仅指诊断","example":"The clinic offers procedural sedation for minor surgery.","exampleCN":"这家诊所的小手术提供操作中的镇静。","why":"Medicine names by procedure what is done with hands, and the adjective separates it from talk and tests.","whyCN":"医学以操作命名动手做的事，这个形容词把它与谈话和检查分开。"}],"etymology":{"intro":{"en":"Procedural is procedure plus -al. Procedure comes from Latin procedere 'to go forward', from pro- 'forward' and cedere 'to go'. The line is clear; the exact date of the adjective in English is uncertain.","cn":"procedural 是 procedure 加 -al。procedure 出自拉丁语 procedere「向前走」，由 pro-「向前」与 cedere「走」构成。线索清楚，这个形容词进入英语的确切年代不确定。"},"items":[{"era":"CEDERE","en":"Cedere meant to go, to yield or to give way, and it stands behind proceed, process and succeed.","cn":"cedere 意为走、让步或退让，proceed、process 与 succeed 都由它而来。"},{"era":"PROCEDERE","en":"Procedere combined the forward prefix with that verb to mean to go forward, to advance, to come out.","cn":"procedere 把表示向前的前缀与这个动词结合，意为前行、推进、走出。"},{"era":"FRENCH PROCEDURE","en":"Old French procedure named the manner of conducting a case, a word of courts before it was a word of offices.","cn":"古法语的 procedure 指审理案件的方式，先是法庭用语，后成公务用语。"},{"era":"ENGLISH PROCEDURE","en":"English borrowed the noun in the sixteenth century, first in law and then in general administration.","cn":"英语在十六世纪借入这个名词，先用于法律，随后用于一般行政。"},{"era":"PROCEDURAL","en":"The adjective followed, and modern law fixed the contrast between procedural and substantive rules.","cn":"形容词随后出现，现代法律确立了程序规则与实体规则的对立。"},{"era":"COMPUTING","en":"In the later twentieth century the adjective was applied to programming built from named steps.","cn":"二十世纪后期，这个形容词被用来指由命名步骤构成的编程方式。"}]},"similar":{"note":{"en":"The first group shares the going-forward root or looks close; the second group holds words that describe rules and steps but are not the same contrast.","cn":"第一组或共享「向前走」词根，或字形相近；第二组描述规则与步骤，却不是同一个对立面。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"procedure","ipa":"/prəˈsiːdʒə/","tag":"same root","definition":"The noun: a set of steps for doing something.","definitionCN":"名词：做事的一套步骤。"},{"word":"proceed","ipa":"/prəˈsiːd/","tag":"same root","definition":"To go on or move forward, the verb inside the noun.","definitionCN":"继续或向前走，是名词里的动词。"},{"word":"proceeding","ipa":"/prəˈsiːdɪŋ/","tag":"same root","definition":"A course of action, often in the plural for legal or formal business.","definitionCN":"一系列行动，复数多指法律或正式事务。"},{"word":"process","ipa":"/ˈprəʊses/","tag":"same going root","definition":"A series of changes; it shares cedere through a different Latin noun.","definitionCN":"一系列变化；经另一个拉丁名词共享同一词根。"},{"word":"prodigal","ipa":"/ˈprɒdɪɡl/","tag":"different root","definition":"Wastefully generous; it looks like the same prefix but comes from a verb meaning to squander.","definitionCN":"挥霍的；前缀看似相同，词根却意为耗费。"}]},{"heading":"NEAR MEANING","entries":[{"word":"formal","ipa":"/ˈfɔːml/","tag":"near meaning","definition":"Following established rules, which often overlaps with procedural but concerns form.","definitionCN":"遵循既定规则，常与程序重叠，但着眼在形式。"},{"word":"administrative","ipa":"/ˌædmɪˈnɪstrətɪv/","tag":"near meaning","definition":"Concerning the running of an organisation rather than its policy.","definitionCN":"关涉机构运转而非政策。"},{"word":"ritual","ipa":"/ˈrɪtʃuəl/","tag":"near meaning","definition":"A fixed sequence of actions with symbolic weight, closer to ceremony than to rule.","definitionCN":"带象征分量的固定动作序列，更近仪式而非规则。"},{"word":"systematic","ipa":"/sɪˈstæmətɪk/","tag":"near meaning","definition":"Done by an ordered plan, emphasising method rather than rules.","definitionCN":"按有序计划进行，强调方法而非规则。"},{"word":"substantive","ipa":"/səbˈstæntɪv/","tag":"near meaning","definition":"Concerning the actual rights and duties at issue, the opposite half of the legal split.","definitionCN":"关涉争议中的实际权利与义务，是法律划分的另一半。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real going-forward root, the real family and real fixed phrases.","cn":"正常联想使用真实的「向前走」词根、真实同族词与真实固定搭配。"},"normal":[{"en":"Cedere means to go, and procedere means to go forward, so a procedure is a path walked step by step.","cn":"词根意为走，加向前的前缀即前行，程序就是一步步走过的路径。"},{"en":"The family runs proceed, procedure, proceeding, procedural and process.","cn":"同族词有 proceed、procedure、proceeding、procedural 与 process。"},{"en":"Fixed phrases mark the uses: procedural rules, procedural fairness, procedural law, procedural error.","cn":"固定说法标出用法：程序规则、程序公正、程序法、程序性错误。"},{"en":"Law divides the world into procedural and substantive, and the adjective owns one half.","cn":"法律把世界分成程序与实体，这个形容词占一半。"},{"en":"Procedure is the noun, procedural the adjective, procedurally the adverb.","cn":"名词是 procedure，形容词是 procedural，副词是 procedurally。"}],"abstract":[{"en":"Procedure is fairness made repeatable, so that the same case gets the same path.","cn":"程序是把公正做成可重复的，好让同样的案子走同样的路。"},{"en":"When procedure becomes an end in itself, the path eats the destination.","cn":"当程序本身成了目的，路径就把终点吃掉了。"},{"en":"A procedure is a promise that the next person will get the same treatment.","cn":"程序是一个承诺：下一个人也会受到同样的对待。"}]},"examples":[{"en":"The delay was procedural and did not affect the merits.","cn":"这次延误属程序问题，不影响案件实体。"},{"en":"Procedural fairness matters even when the answer is obvious.","cn":"即使答案显而易见，程序公正仍然要紧。"},{"en":"The older software was written in a procedural style.","cn":"那套旧软件是过程式风格写成的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「普若西哲柔」——照着流程图上编号一步步走：程序的","word":"procedural"},"root":"procedure ＋ 形容词词尾 -al；procedure 出自拉丁语 procedere「向前走」← pro-「向前」＋ cedere「走」，同源有 proceed、process、proceeding。十六世纪进入英语，先在法律后及行政；二十世纪后期用于编程风格。形容词确切年代不确定。","sensesIntro":{"en":"Eight senses follow the path: the steps themselves, court rules, fairness of process, safeguards, step-by-step code, meeting order, routine behaviour, and medical procedures.","cn":"八个义项沿着这条路径展开：步骤本身、法庭规则、过程公正、防错保障、按步执行的代码、议事秩序、例行举止，以及医疗操作。"},"semanticMap":{"core":{"en":"CORE IMAGE: a numbered flow chart on a wall, each box linked to the next by an arrow.","cn":"核心意象：墙上贴着编号的流程图，每个方框都用箭头连到下一个。"},"chain":["GO FORWARD","A PATH OF STEPS","WRITTEN RULES","FAIR PROCESS","ROUTINE ORDER","STEP-BY-STEP CODE"],"branches":[{"senses":"01 · 07","en":"THE MANNER OF DOING: the steps rather than the substance, and behaviour that has become a fixed sequence.","cn":"做事的方式：步骤而非实体，以及变成固定序列的举止。"},{"senses":"02 · 06","en":"THE RULES OF THE ROOM: court rules and the motions that keep a meeting arguing about its own order.","cn":"场内规则：法庭规则，以及让会议只争论自身秩序的动议。"},{"senses":"03 · 04","en":"THE GUARDED PATH: hearing both sides, and the checks that catch a mistake before it travels.","cn":"有护栏的路径：听取双方，以及错误传开之前抓住它的核查。"},{"senses":"05","en":"THE CODE THAT READS LIKE STEPS: named sequences of instructions walked through in order.","cn":"读起来像步骤的代码：按次序走过的命名指令序列。"},{"senses":"08","en":"THE PROCEDURE IN MEDICINE: what is done with hands, as distinct from diagnosis and talk.","cn":"医学里的操作：动手所做之事，与诊断和谈话相区别。"}]},"affixes":{"intro":{"en":"Procedural rests on the Latin verb for going forward and adds an English adjective ending.","cn":"procedural 依托表示「向前走」的拉丁动词，再加上英语形容词词尾。"},"latinIntro":{"en":"Latin procedere and the noun procedura are the sources behind the English pair procedure and procedural.","cn":"拉丁语 procedere 与名词 procedura 是英语 procedure 与 procedural 这对词的来源。"},"items":[{"word":"procedural","structure":"procedure plus -al","meaning":"relating to steps or rules","meaningCN":"与步骤或规则有关的","example":"The adjective marks manner rather than substance.","exampleCN":"这个形容词标的是方式而非实体。"},{"word":"procedure","structure":"French procedure, from Latin procedere","meaning":"a set of steps","meaningCN":"一套步骤","example":"The noun names the path as a whole.","exampleCN":"这个名词指整条路径。"},{"word":"pro-","structure":"Latin prefix","meaning":"forward","meaningCN":"向前","example":"It gives the direction of the walking.","exampleCN":"它给出行走的方向。"},{"word":"cedere","structure":"Latin verb","meaning":"to go, to yield","meaningCN":"走；让步","example":"It also stands behind process and succeed.","exampleCN":"process 与 succeed 也由它而来。"},{"word":"-al","structure":"Latin -alis through French","meaning":"relating to","meaningCN":"与……有关的","example":"It builds procedural, formal and substantial.","exampleCN":"它构成程序的、形式的与实质的等词。"},{"word":"-ure","structure":"Latin -ura through French","meaning":"result or manner of an act","meaningCN":"动作的结果或方式","example":"It builds procedure and departure.","exampleCN":"它构成程序与离开等词。"},{"word":"-ly","structure":"English suffix","meaning":"in the manner of","meaningCN":"以……方式","example":"It builds procedurally, as in procedurally flawed.","exampleCN":"它构成 procedurally，如程序上有瑕疵。"},{"word":"proceedings","structure":"proceed plus -ings","meaning":"a course of formal business","meaningCN":"一系列正式事务","example":"The plural names the whole run of steps.","exampleCN":"复数形式指整套步骤的进行。"}],"latinEntries":[{"word":"procedere","structure":"pro- (forward) + cedere (go)","meaning":"to go forward; to come out","meaningCN":"向前走；出现","example":"Latin procedere means to go forward.","exampleCN":"拉丁语 procedere 意为向前走。"},{"word":"pro-","structure":"Latin prefix pro- (forward, for)","meaning":"forward","meaningCN":"向前","example":"Latin pro- appears in producere, to lead forward.","exampleCN":"拉丁语 pro- 见于 producere（向前引出）。"},{"word":"cedere","structure":"Latin verb cedere (ced-, cessum; to go, yield)","meaning":"to go; to yield","meaningCN":"走；让步","example":"Latin cedere means to go or yield, and gives cede and process.","exampleCN":"拉丁语 cedere 意为走、让步，并给出 cede 与 process。"}],"derivatives":[{"word":"procedure","pos":"n.","zh":"程序；步骤"},{"word":"procedurally","pos":"adv.","zh":"在程序上"},{"word":"proceed","pos":"v.","zh":"继续进行"},{"word":"proceedings","pos":"n.","zh":"诉讼程序；会议记录"},{"word":"process","pos":"n./v.","zh":"过程；处理"},{"word":"proceduralism","pos":"n.","zh":"程序主义"}]}},{"word":"comparative","ipa_uk":"/kəmˈpærətɪv/","ipa_us":"/kəmˈpærətɪv/","definition_zh":"比较的；对比的；相对的；（语法）比较级的；比较研究的；比较文学的；（名词）比较级形式","definition_en":"based on comparing two or more things, or measured in relation to something else rather than absolutely","core_image":"两只手把两片叶子并排举到同一束光下，一片宽一片窄，差别立刻显出来","scene":"同一套政策在两个邻国各自实行了十年，研究者在两地分别测算效果，再放到一起看。The paper offers a comparative study of school funding in two neighbouring countries.","sceneCN":"这里指以比较为基础的研究（第 5 个义项：比较性的、比较研究的）；句意为这篇论文对两个邻国的学校经费作了比较研究。场景图取象：两片叶子被并排举到同一束光下。","pos":[{"tag":"adj.","zh":"比较的；对比的"},{"tag":"adj.","zh":"相对的；相比较而言的"},{"tag":"adj.","zh":"（语法）比较级的"},{"tag":"n.","zh":"（语法）比较级形式"}],"collocations":[{"phrase":"comparative study","zh":"比较研究"},{"phrase":"comparative analysis","zh":"比较分析"},{"phrase":"comparative advantage","zh":"比较优势"},{"phrase":"comparative literature","zh":"比较文学"},{"phrase":"comparative anatomy","zh":"比较解剖学"},{"phrase":"comparative degree","zh":"比较级"},{"phrase":"comparative politics","zh":"比较政治学"},{"phrase":"in comparative terms","zh":"相比较而言"}],"forms":[{"label":"原形","form":"comparative"},{"label":"名词（比较）","form":"comparison"},{"label":"动词","form":"compare"},{"label":"副词","form":"comparatively"},{"label":"形容词（可比的）","form":"comparable"},{"label":"名词（比较级）","form":"comparative"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较；对照（由表示「一起」的前缀加表示「使齐备」的动词构成，字面即把两样东西摆到一起量）"},{"word":"comparison","pos":"n.","zh":"比较；对比（动词的名词形式，指把两物并置衡量的过程或结论）"},{"word":"comparable","pos":"adj.","zh":"可比的；相似的（加表示「能够被……」的形容词后缀，指两物值得放在一起量）"},{"word":"comparatively","pos":"adv.","zh":"相对地；比较而言（加副词词尾，指把基准放在别处来看）"},{"word":"comparator","pos":"n.","zh":"比较器；比较基准（加表示「施动者、工具」的名词后缀，指用于比对的装置或标准）"},{"word":"incomparable","pos":"adj.","zh":"无可比拟的（加表示否定的前缀，指找不到可比之物）"}],"senses":[{"no":"01","title":"Based on comparison","titleCN":"以比较为基础的","definition":"founded on the comparison of two or more things rather than on a single case","definitionCN":"建立在两件或更多事物的比较之上，而非只凭单一案例","example":"The report is comparative, setting four cities side by side.","exampleCN":"这份报告是比较性的，把四座城市并排放着看。","why":"The Latin verb meant to pair things together, so the adjective marks work that puts pairs side by side.","whyCN":"这个拉丁动词意为把东西配成对，因此这个形容词标出把成对之物并排的工作。"},{"no":"02","title":"Relative rather than absolute","titleCN":"相对而非绝对的","definition":"measured against another standard, so that the judgement depends on what it is compared with","definitionCN":"以另一标准来衡量，判断随参照物而变","example":"The region is wealthy in comparative terms.","exampleCN":"相比较而言，这个地区算富裕。","why":"Nothing is cheap or safe on its own; the adjective insists on the second thing in the sentence.","whyCN":"没有什么东西单凭自身就算便宜或安全，这个形容词坚持要句子里出现第二个东西。"},{"no":"03","title":"The grammar of -er","titleCN":"语法上的比较级","definition":"of the form of an adjective or adverb that compares two things, as in taller or more careful","definitionCN":"指形容词或副词比较两物的形式，如「更高」或「更小心」","example":"'Faster' is the comparative form of 'fast'.","exampleCN":"「更快」是「快」的比较级形式。","why":"Grammar names the degree after the act of comparing, since two things are always implied.","whyCN":"语法按比较这一动作来命名这个级别，因为它总隐含两样东西。"},{"no":"04","title":"The comparative form itself","titleCN":"比较级形式（名词）","definition":"the word or form that expresses the comparative degree","definitionCN":"表达比较级的词或词形","example":"Write the comparative of each adjective in the list.","exampleCN":"写出名单里每个形容词的比较级。","why":"Once grammar had the degree, it needed a noun for the form, and reused the adjective as one.","whyCN":"语法一旦有了这个级别，就需要一个指形式的名称，于是把这个形容词直接当名词用。"},{"no":"05","title":"A cross-case study","titleCN":"跨案例的比较研究","definition":"of research that studies several cases, countries or periods in order to explain differences","definitionCN":"指研究多个案例、国家或时期以解释差异的研究","example":"The paper offers a comparative study of school funding in two neighbouring countries.","exampleCN":"这篇论文对两个邻国的学校经费作了比较研究。","why":"A single case can describe; only a second case can show what is peculiar and what is common.","whyCN":"单一案例只能描述，第二个案例才能显出何者独特、何者共通。"},{"no":"06","title":"Comparative advantage","titleCN":"比较优势","definition":"in economics, the ability to produce a good at a lower opportunity cost than another producer","definitionCN":"在经济学中，指以比另一生产者更低的机会成本生产某种商品的能力","example":"The island's comparative advantage lies in fruit, not steel.","exampleCN":"这座岛的比较优势在水果，不在钢铁。","why":"Trade theory compares opportunity costs rather than absolute skill, and the adjective carries that idea.","whyCN":"贸易理论比较的是机会成本而非绝对本领，这个形容词承载的就是这一思路。"},{"no":"07","title":"A field of study","titleCN":"作为学科名的一部分","definition":"in names such as comparative literature or comparative anatomy, the systematic study of variation across cases","definitionCN":"在比较文学、比较解剖学等名称中，指跨案例系统研究差异的学科","example":"She teaches comparative literature at the university.","exampleCN":"她在大学教比较文学。","why":"Disciplines take the adjective when their method is to set traditions or species beside each other.","whyCN":"学科若以把传统或物种并置为方法，就会用这个形容词。"},{"no":"08","title":"Comparative negligence","titleCN":"比较过失（法律）","definition":"in law, the rule that damages are reduced in proportion to the injured party's own share of fault","definitionCN":"在法律中，指按受害方自身过错的比例减少赔偿额的规则","example":"The jury applied comparative negligence and cut the award by a third.","exampleCN":"陪审团适用比较过失，把赔偿额削减了三分之一。","why":"Law weighs fault as a proportion, and the adjective names that weighing.","whyCN":"法律把过失按比例称量，这个形容词就给这次称量命名。"}],"etymology":{"intro":{"en":"Comparative comes from Latin comparativus, from comparare 'to pair together', built on com- 'together' and parare 'to make ready'. The chain is clear; the first English use is dated to the late sixteenth century.","cn":"comparative 出自拉丁语 comparativus，来自 comparare「配成对」，由 com-「一起」与 parare「使齐备」构成。词源链清楚，英语最早用例可定在十六世纪后期。"},"items":[{"era":"PARARE","en":"Parare meant to make ready or to prepare, and it also stands behind prepare, repair and apparatus.","cn":"parare 意为使齐备、准备，prepare、repair 与 apparatus 也源于它。"},{"era":"COMPARARE","en":"The prefix com- added the idea of together, so comparare meant to put two things level and measure them against each other.","cn":"前缀 com- 加入「一起」之意，comparare 因此指把两物摆平并互相比量。"},{"era":"LATIN COMPARATIVUS","en":"Grammarians used comparativus for the degree of two, a technical label from the schools.","cn":"语法学家用 comparativus 指「二者之比」的级别，是学院里的技术标签。"},{"era":"ENGLISH ENTRY","en":"English took the adjective in the late sixteenth century, first in grammar and then in natural history.","cn":"英语在十六世纪后期借入这个形容词，先用于语法，后用于博物学。"},{"era":"THE COMPARATIVE METHOD","en":"The nineteenth century made comparison a method, in anatomy, law and religion, and the adjective became a label for whole disciplines.","cn":"十九世纪把比较变成方法，用于解剖学、法学与宗教学，这个形容词成了整门学科的标签。"},{"era":"ECONOMICS","en":"Comparative advantage, named in the early nineteenth century, gave the word a permanent place in trade theory.","cn":"十九世纪初提出的比较优势，让这个词在贸易理论中取得长久位置。"}]},"similar":{"note":{"en":"The first group shares the pairing root or looks close; the second group holds the words that sit near comparative without being interchangeable.","cn":"第一组或共享「配对」词根，或字形相近；第二组是与「比较的」相近却不能互换的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"compare","ipa":"/kəmˈpeə/","tag":"same root","definition":"The verb: to set things side by side and note differences.","definitionCN":"动词：把东西并排摆着看差别。"},{"word":"comparison","ipa":"/kəmˈpærɪsn/","tag":"same root","definition":"The noun for the act or the resulting judgement.","definitionCN":"指比较动作或其结论的名词。"},{"word":"comparable","ipa":"/ˈkɒmpərəbl/","tag":"same root","definition":"Worthy of being compared, a different claim from being comparative.","definitionCN":"值得相比，与「比较性的」是不同的主张。"},{"word":"comparator","ipa":"/kəmˈpærətə/","tag":"same root","definition":"A device or standard used for comparison.","definitionCN":"用于比对的装置或标准。"},{"word":"imperative","ipa":"/ɪmˈperətɪv/","tag":"different root","definition":"Commanding; it looks similar but comes from a verb meaning to command.","definitionCN":"命令的；字形相近，却出自意为命令的动词。"},{"word":"cooperative","ipa":"/kəʊˈɒpərətɪv/","tag":"different root","definition":"Working together; the shape misleads, since its root is work rather than ready.","definitionCN":"合作共事的；形状易误导，其词根意为工作而非齐备。"}]},{"heading":"NEAR MEANING","entries":[{"word":"relative","ipa":"/ˈrelətɪv/","tag":"near meaning","definition":"Judged against something else; close to the second sense of comparative.","definitionCN":"以他物为参照判断；接近 comparative 的第二义。"},{"word":"contrastive","ipa":"/kənˈtræstɪv/","tag":"near meaning","definition":"Designed to bring out differences, especially in linguistics.","definitionCN":"旨在显出差异，尤用于语言学。"},{"word":"cross-cultural","ipa":"/ˌkrɒs ˈkʌltʃərəl/","tag":"near meaning","definition":"Comparing societies, a common partner of comparative in research writing.","definitionCN":"比较不同社会，是研究写作中 comparative 的常见搭档。"},{"word":"benchmark","ipa":"/ˈbentʃmɑːk/","tag":"near meaning","definition":"A standard point of reference against which others are measured.","definitionCN":"用来衡量他者的参照标准。"},{"word":"analogical","ipa":"/ˌænəˈlɒdʒɪkl/","tag":"near meaning","definition":"Reasoning from similarity rather than from measured comparison.","definitionCN":"由相似推出，而非由测量比较推出。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real pairing root, the real family and real fixed phrases.","cn":"正常联想使用真实的「配对」词根、真实同族词与真实固定搭配。"},"normal":[{"en":"Parare means to make ready, and com- means together, so comparare is to get two things ready side by side.","cn":"词根意为使齐备，前缀意为一起，合起来就是把两样东西摆到一处备好。"},{"en":"The family runs compare, comparison, comparable, comparative, comparatively and incomparable.","cn":"同族词有 compare、comparison、comparable、comparative、comparatively 与 incomparable。"},{"en":"Fixed phrases mark the uses: comparative study, comparative advantage, comparative literature, comparative degree.","cn":"固定说法标出用法：比较研究、比较优势、比较文学、比较级。"},{"en":"In grammar the comparative is the -er form, the superlative the -est form.","cn":"语法里比较级是加 -er 的形式，最高级是加 -est 的形式。"},{"en":"Com-parable is about whether two things can be compared; com-parative is about work that does compare them.","cn":"comparable 说的是两物能否相比，comparative 说的是确实做了比较的工作。"}],"abstract":[{"en":"A comparative view is a cure for the illusion that one's own case is the natural one.","cn":"比较的眼光能治一种错觉：以为自己这种情形是理所当然的。"},{"en":"Comparison doubles the information without doubling the effort.","cn":"比较让信息翻倍，却不必让工夫翻倍。"},{"en":"The second case is not an extra; it is the instrument.","cn":"第二个案例不是多余的，它就是仪器本身。"}]},"examples":[{"en":"The two systems look similar until you take a comparative view.","cn":"两个体系看着相似，直到你采用比较的眼光。"},{"en":"Comparative studies of the two regions began last year.","cn":"对这两个地区的比较研究去年开始。"},{"en":"Use the comparative when exactly two things are being weighed.","cn":"恰好比较两样东西时用比较级。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康帕瑞提夫」——把两片叶子并排举到光下：比较的","word":"comparative"},"root":"拉丁语 comparativus ← comparare「配成对、比量」← com-「一起」＋ parare「使齐备」；同族有 compare、comparison、comparable；parare 另出 prepare、repair、apparatus。十六世纪后期进入英语，十九世纪成为学科方法之名。","sensesIntro":{"en":"Eight senses share one act of pairing: work based on comparison, a relative judgement, the -er degree, the form that carries it, a cross-case study, comparative advantage, a discipline's name, and comparative negligence in law.","cn":"八个义项共享同一次配对：以比较为基础的工作、相对的判断、加 -er 的级别、承载该级别的形式、跨案例研究、比较优势、学科名，以及法律上的比较过失。"},"semanticMap":{"core":{"en":"CORE IMAGE: two leaves held side by side in one beam of light, one wide and one narrow.","cn":"核心意象：两片叶子在同一束光下并排举着，一片宽一片窄。"},"chain":["MAKE READY","PAIR TOGETHER","WEIGH AGAINST","RELATIVE JUDGEMENT","CROSS-CASE STUDY","A DISCIPLINE'S METHOD"],"branches":[{"senses":"01 · 05","en":"THE SIDE-BY-SIDE STUDY: work that sets cases next to each other to explain difference.","cn":"并排的研究：把案例放在一起以解释差异的工作。"},{"senses":"02","en":"THE RELATIVE MEASURE: rich or safe only when a second standard is named.","cn":"相对的衡量：只有点出第二个标准，才谈得上富裕或安全。"},{"senses":"03 · 04","en":"THE DEGREE AND ITS FORM: the grammar of two, as a label and as a noun.","cn":"级别及其形式：二者之比的语法，既作标签也作名词。"},{"senses":"06","en":"THE OPPORTUNITY COST: trade theory's comparison of what each producer gives up.","cn":"机会成本：贸易理论比较每个生产者放弃的东西。"},{"senses":"07 · 08","en":"THE INSTITUTIONAL NAME: comparative literature and comparative anatomy, and the law's weighing of fault.","cn":"学科之名与法律：比较文学与比较解剖学，以及法律对过失的称量。"}]},"affixes":{"intro":{"en":"Comparative is built from a Latin verb of pairing and a Latin adjective ending, a pattern shared by dozens of academic labels.","cn":"comparative 由表示配对的拉丁动词加拉丁形容词词尾构成，这一模式见于许多学术标签。"},"latinIntro":{"en":"Comparare from com- and parare is the source; comparativus is the Latin adjective.","cn":"来源是 com- 与 parare 合成的 comparare，拉丁形容词为 comparativus。"},"items":[{"word":"comparative","structure":"Latin comparativus","meaning":"relating to comparison","meaningCN":"与比较有关的","example":"The adjective labels both method and grammar.","exampleCN":"这个形容词既标方法，也标语法级别。"},{"word":"com-","structure":"Latin prefix","meaning":"together","meaningCN":"一起","example":"It gives the idea of two things placed together.","exampleCN":"它给出把两物放在一起的意思。"},{"word":"parare","structure":"Latin verb","meaning":"to make ready, to prepare","meaningCN":"使齐备；准备","example":"It also stands behind prepare and repair.","exampleCN":"prepare 与 repair 也由它而来。"},{"word":"comparare","structure":"com- plus parare","meaning":"to pair, to compare","meaningCN":"配对；比较","example":"The verb is the action inside the adjective.","exampleCN":"这个动词是形容词里的动作。"},{"word":"-ive","structure":"Latin -ivus through French","meaning":"tending to, serving for","meaningCN":"倾向于；用于","example":"It builds comparative, instructive and preventive.","exampleCN":"它构成比较的、教导性的与预防的等词。"},{"word":"comparison","structure":"compare plus -ison","meaning":"the act of comparing","meaningCN":"比较的行为","example":"The noun names the act rather than the method.","exampleCN":"这个名词指动作而非方法。"},{"word":"-able","structure":"Latin -abilis","meaning":"able to be","meaningCN":"能够被……的","example":"It builds comparable, meaning fit to be compared.","exampleCN":"它构成 comparable，意为值得相比。"},{"word":"-ly","structure":"English suffix","meaning":"in the manner of","meaningCN":"以……方式","example":"It builds comparatively, meaning relatively.","exampleCN":"它构成 comparatively，意为相对地。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不；非","example":"It builds incomparable, meaning beyond comparison.","exampleCN":"它构成 incomparable，意为无可比拟。"}],"latinEntries":[{"word":"comparare","structure":"com- (together) + parare (make ready)","meaning":"to pair together; to compare","meaningCN":"配对；比较","example":"Latin comparare means to pair together, to compare.","exampleCN":"拉丁语 comparare 意为配对、比较。"},{"word":"parare","structure":"Latin verb parare (par-, paratum; to make ready)","meaning":"to make ready","meaningCN":"使齐备","example":"Latin parare means to make ready, and gives prepare.","exampleCN":"拉丁语 parare 意为使齐备，并给出 prepare。"},{"word":"comparativus","structure":"comparat- (compared) + -ivus (adjective)","meaning":"relating to comparison","meaningCN":"与比较有关的","example":"Latin comparativus means relating to comparison.","exampleCN":"拉丁语 comparativus 意为与比较有关的。"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较；对照"},{"word":"comparison","pos":"n.","zh":"比较；对比"},{"word":"comparable","pos":"adj.","zh":"可比的"},{"word":"comparatively","pos":"adv.","zh":"相对地"},{"word":"comparator","pos":"n.","zh":"比较器；比较基准"},{"word":"incomparable","pos":"adj.","zh":"无可比拟的"}]}},{"word":"comparison","ipa_uk":"/kəmˈpærɪsn/","ipa_us":"/kəmˈpærɪsn/","definition_zh":"比较；对比；比拟；对照得出的结论；（语法）比较（级）；（修辞）比喻","definition_en":"the act of examining two or more things for their similarities and differences, and the judgement that results","core_image":"两只杯子放在同一张桌上，一只满一只浅，水位线被同一道目光量了两遍","scene":"编辑把今年的销售曲线和去年那条印在同一张图上，两条线的分叉一眼就看得见。A direct comparison of the two curves showed where the autumn slump began.","sceneCN":"这里指把两组数据并置对照（第 2 个义项：对照、对比）；句意为两条曲线的直接对比显出秋季下滑是从哪里开始的。场景图取象：两只杯子放在同一张桌上，水位高低一目了然。","pos":[{"tag":"n.","zh":"比较；对照（可数或不可数）"},{"tag":"n.","zh":"比拟；比喻（修辞用法）"},{"tag":"n.","zh":"（语法）比较；比较级"},{"tag":"n.","zh":"对照后得出的判断或结论"}],"collocations":[{"phrase":"in comparison with","zh":"与……相比"},{"phrase":"by comparison","zh":"相比之下"},{"phrase":"a fair comparison","zh":"公平的比较"},{"phrase":"direct comparison","zh":"直接对比"},{"phrase":"comparison shopping","zh":"货比三家"},{"phrase":"draw a comparison between","zh":"把……与……作比较"},{"phrase":"invite comparison","zh":"招致比较"},{"phrase":"for comparison","zh":"供比较之用"}],"forms":[{"label":"原形","form":"comparison"},{"label":"复数","form":"comparisons"},{"label":"动词","form":"compare"},{"label":"形容词","form":"comparative"},{"label":"形容词（可比的）","form":"comparable"},{"label":"副词","form":"comparatively"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较；对照（由表示「一起」的前缀加表示「使齐备」的动词构成，字面即把两物摆到一处量）"},{"word":"comparative","pos":"adj.","zh":"比较的；比较级的（加表示「倾向于、用于」的形容词后缀）"},{"word":"comparable","pos":"adj.","zh":"可比的（加表示「能够被」的形容词后缀，指两物值得放在一起量）"},{"word":"comparably","pos":"adv.","zh":"类似地；可相比地（加副词词尾）"},{"word":"comparator","pos":"n.","zh":"比较器（加表示「工具」的名词后缀）"},{"word":"incomparable","pos":"adj.","zh":"无可比拟的（加否定前缀，指找不到可比之物）"}],"senses":[{"no":"01","title":"The act of comparing","titleCN":"比较这个动作","definition":"the act of examining two or more things in order to note their similarities and differences","definitionCN":"检查两件或更多事物以指出其异同的行为","example":"A comparison of the two maps shows how the river moved.","exampleCN":"把两幅地图一比较，就看得出河道怎么挪了。","why":"The Latin verb meant to pair things level, and the noun names that act of holding two things up together.","whyCN":"这个拉丁动词意为把东西摆平配对，名词指把两物一起举起比看的动作。"},{"no":"02","title":"A side-by-side contrast","titleCN":"并排对照","definition":"a contrast drawn between two cases, figures or versions so that differences stand out","definitionCN":"在两件事例、数字或版本之间作出的对照，使差异显出来","example":"A direct comparison of the two curves showed where the autumn slump began.","exampleCN":"两条曲线的直接对比显出秋季下滑是从哪里开始的。","why":"The act becomes a thing when the result is put on a page, and the contrast is then a comparison.","whyCN":"结果一落到纸上，动作就成了东西，那一处对照也就成了一个比较。"},{"no":"03","title":"The phrase 'by comparison'","titleCN":"在「相比之下」这一说法里","definition":"in fixed phrases such as 'by comparison' or 'in comparison with', marking a standard of judgement","definitionCN":"在「相比之下」「与……相比」等固定说法中，标出判断的参照","example":"By comparison, the second method is cheap.","exampleCN":"相比之下，第二种方法便宜。","why":"English sentences use the noun to hang a judgement on a stated reference point.","whyCN":"英语句子用这个名词，把判断挂在说出来的参照点上。"},{"no":"04","title":"Degrees of comparison","titleCN":"语法上的比较级别","definition":"in grammar, the system of comparative and superlative forms of adjectives and adverbs","definitionCN":"语法中形容词与副词的比较级、最高级形式系统","example":"The chapter on degrees of comparison fills only two pages.","exampleCN":"讲比较级别的那一章只有两页。","why":"Grammar treats comparison as a formal system, with its own forms and exceptions.","whyCN":"语法把比较当成一套形式系统，有自己的形态与例外。"},{"no":"05","title":"Price comparison","titleCN":"货比三家","definition":"the practice of checking prices or offers before buying","definitionCN":"购买之前查看价格或报价的做法","example":"Comparison shopping saved her forty pounds.","exampleCN":"货比三家让她省了四十镑。","why":"Markets turn the act into a habit, and the noun attaches to the shopping rather than to the reasoning.","whyCN":"市场把这个动作变成习惯，名词便挂在购物上而非推理上。"},{"no":"06","title":"A judgement that follows","titleCN":"由此得出的判断","definition":"the conclusion reached after weighing two things, often stated as a verdict","definitionCN":"权衡两物之后得出的结论，常以评判的形式说出","example":"The comparison favours the smaller design.","exampleCN":"这一比较更有利于较小的设计。","why":"The noun can name the verdict as well as the process, so a comparison can favour one side.","whyCN":"这个名词也能指裁决而非过程，所以可以说一次比较偏向某一边。"},{"no":"07","title":"A figure of speech","titleCN":"修辞上的比喻","definition":"in rhetoric and literature, an explicit likening of one thing to another, as in a simile","definitionCN":"在修辞与文学中，明说一物像另一物，如明喻","example":"The poem closes with a comparison between the sea and sleep.","exampleCN":"这首诗以海与睡眠的比喻收尾。","why":"Rhetoric calls the likening a comparison because two unlike things are held up side by side.","whyCN":"修辞学把这种比拟称为比较，因为两样不同之物被并排举了起来。"},{"no":"08","title":"A statistical contrast","titleCN":"统计上的组间对比","definition":"in research, the formal contrast of groups or conditions, often against a control","definitionCN":"在研究中，对若干组别或条件的正式对照，常以对照组为基准","example":"The comparison between the treated and untreated groups was significant.","exampleCN":"治疗组与未治疗组之间的对比具有显著性。","why":"Experiments are built on a comparison, since a single group has nothing to be measured against.","whyCN":"实验建立在比较之上，因为单独一组没有可对照的东西。"}],"etymology":{"intro":{"en":"Comparison comes from Latin comparatio, from comparare 'to pair together', built on com- 'together' and parare 'to make ready'. The chain is clear; the English noun is recorded from the fourteenth century.","cn":"comparison 出自拉丁语 comparatio，来自 comparare「配成对」，由 com-「一起」与 parare「使齐备」构成。词源链清楚，这个英语名词自十四世纪有记录。"},"items":[{"era":"PARARE","en":"Parare meant to make ready, and it also stands behind prepare, repair and apparatus.","cn":"parare 意为使齐备，prepare、repair 与 apparatus 也源于它。"},{"era":"COMPARARE","en":"With the together prefix, the verb meant to bring two things level and measure one against the other.","cn":"加上表示一起的前缀，这个动词指把两物摆平，再拿一个量另一个。"},{"era":"COMPARATIO","en":"The Latin noun named both the act and its outcome, a word used in argument and in grammar.","cn":"拉丁名词既指动作也指结果，用于论辩，也用于语法。"},{"era":"ENGLISH ENTRY","en":"English borrowed the noun through Old French in the fourteenth century, first in religious prose.","cn":"英语在十四世纪经由古法语借入这个名词，最早见于宗教文本。"},{"era":"GRAMMAR AND RHETORIC","en":"The schools gave it two technical homes, the degrees of adjectives and the figure of speech.","cn":"学校给了它两个技术归宿：形容词的级别，以及修辞格。"},{"era":"STATISTICS","en":"Modern research added a third home, the controlled contrast of groups that carries the word into every laboratory report.","cn":"现代研究加了第三个归宿：组间的受控对照，把这个词带进每份实验报告。"}]},"similar":{"note":{"en":"The first group shares the pairing root or looks close; the second group holds the neighbouring acts that are not quite comparison.","cn":"第一组或共享「配对」词根，或字形相近；第二组是并不完全等同于比较的邻近行为。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"compare","ipa":"/kəmˈpeə/","tag":"same root","definition":"The verb behind the noun.","definitionCN":"名词背后的动词。"},{"word":"comparative","ipa":"/kəmˈpærətɪv/","tag":"same root","definition":"The adjective for work based on comparison, and the grammar term.","definitionCN":"指以比较为基础的工作的形容词，也是语法术语。"},{"word":"comparable","ipa":"/ˈkɒmpərəbl/","tag":"same root","definition":"Fit to be compared, a judgement about the pair rather than the act.","definitionCN":"值得相比，是对这一对的判断而非动作。"},{"word":"comparably","ipa":"/ˈkɒmpərəbli/","tag":"same root","definition":"In a similar measure, the adverb.","definitionCN":"以类似的程度，副词形式。"},{"word":"compassion","ipa":"/kəmˈpæʃn/","tag":"different root","definition":"Sympathy for suffering; it looks similar but comes from a verb meaning to suffer with.","definitionCN":"对苦难的同情；字形相近，却出自意为「共同承受」的动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"contrast","ipa":"/ˈkɒntrɑːst/","tag":"near meaning","definition":"A setting of differences rather than similarities, often the sharper half of a comparison.","definitionCN":"摆出差异而非相似，常是比较中更锋利的一半。"},{"word":"analogy","ipa":"/əˈnælədʒi/","tag":"near meaning","definition":"A likeness used to explain, which does not require measurement.","definitionCN":"用来解释的相似，不必经过测量。"},{"word":"evaluation","ipa":"/ˌiːvæljuˈeɪʃn/","tag":"near meaning","definition":"Judging worth or quality, which may or may not involve a second thing.","definitionCN":"评判价值或质量，未必牵涉第二个对象。"},{"word":"benchmarking","ipa":"/ˈbentʃmɑːkɪŋ/","tag":"near meaning","definition":"Measuring against an external standard, a management form of comparison.","definitionCN":"对照外部标准测量，是比较在管理上的形态。"},{"word":"simile","ipa":"/ˈsɪməli/","tag":"near meaning","definition":"An explicit likening using like or as, the rhetorical form of comparison.","definitionCN":"用「像」或「如」明说的比拟，是比较的修辞形态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real pairing root, the real family and real fixed phrases.","cn":"正常联想使用真实的「配对」词根、真实同族词与真实固定搭配。"},"normal":[{"en":"Parare means to make ready, so a comparison is two things got ready and set level on one table.","cn":"词根意为使齐备，比较就是把两样东西备好、摆平在同一张桌上。"},{"en":"The family runs compare, comparison, comparative, comparable and incomparable.","cn":"同族词有 compare、comparison、comparative、comparable 与 incomparable。"},{"en":"Fixed phrases mark the uses: in comparison with, by comparison, direct comparison, comparison shopping.","cn":"固定说法标出用法：与……相比、相比之下、直接对比、货比三家。"},{"en":"The noun has three homes: everyday judgement, grammar degrees, and statistics.","cn":"这个名词有三个归宿：日常判断、语法级别与统计学。"},{"en":"Comparison in rhetoric is the simile, where two unlike things are held up together.","cn":"修辞里的比较就是明喻，把两样不同之物并排举起。"}],"abstract":[{"en":"Comparison is how a mind finds edges without touching anything.","cn":"比较是心智不碰任何东西就摸出边界的方式。"},{"en":"Every comparison chooses a reference point, and the reference point quietly chooses the answer.","cn":"每次比较都选定一个参照点，而参照点又悄悄选定了答案。"},{"en":"A comparison is a question asked with two objects instead of words.","cn":"比较是用两件东西而非词语提出的一个问题。"}]},"examples":[{"en":"A comparison of the two editions reveals a missing chapter.","cn":"把两个版本一比较，就发现少了一章。"},{"en":"By comparison with last year, sales are flat.","cn":"与去年相比，销售持平。"},{"en":"The report invites comparison with the earlier survey.","cn":"这份报告免不了要拿来与早先的调查作比较。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康帕瑞森」——两只杯子摆在同一桌上量水位：比较、对照","word":"comparison"},"root":"拉丁语 comparatio ← comparare「配成对、比量」← com-「一起」＋ parare「使齐备」；同族有 compare、comparative、comparable、incomparable。十四世纪经古法语进入英语，先在宗教文本，后在语法、修辞与统计学中定型。","sensesIntro":{"en":"Eight senses follow one pairing: the act, the side-by-side contrast, the fixed phrases, the grammar degrees, price checking, the verdict, the rhetorical figure, and the statistical contrast.","cn":"八个义项沿着同一次配对：比较的动作、并排的对照、固定说法、语法级别、货比三家、得出的判断、修辞的比喻，以及统计上的组间对比。"},"semanticMap":{"core":{"en":"CORE IMAGE: two glasses on one table, one full and one shallow, measured by the same eye twice.","cn":"核心意象：同一张桌上两只杯子，一只满一只浅，被同一道目光量了两遍。"},"chain":["MAKE READY","PAIR TOGETHER","HOLD UP BESIDE","NOTE THE DIFFERENCE","REACH A VERDICT","PUT IT IN WORDS"],"branches":[{"senses":"01 · 02","en":"THE ACT AND THE CONTRAST: examining two things, and the difference that stands out once they are level.","cn":"动作与对照：检查两物，以及摆平之后显出的差异。"},{"senses":"03 · 06","en":"THE REFERENCE AND THE VERDICT: fixed phrases that name a standard, and the judgement that follows from it.","cn":"参照与裁决：点明标准的固定说法，以及由此得出的判断。"},{"senses":"04","en":"THE GRAMMAR: a formal system of degrees, taught as a chapter with its own exceptions.","cn":"语法系统：一套正式的级别，作为一章来教，自有其例外。"},{"senses":"05 · 08","en":"THE PRACTICAL AND THE CONTROLLED: shopping that checks prices, and experiments that check groups.","cn":"日常与受控：查价比价的购物，以及对照各组别的实验。"},{"senses":"07","en":"THE FIGURE OF SPEECH: two unlike things held up together in a simile.","cn":"修辞格：明喻中把两样不同之物并排举起。"}]},"affixes":{"intro":{"en":"Comparison is a Latin noun of pairing, and its family supplies the verb, the adjective and the adverb used across academic writing.","cn":"comparison 是一个表示配对的拉丁名词，其词族提供学术写作中通用的动词、形容词与副词。"},"latinIntro":{"en":"Comparatio from comparare is the source; parare and com- are the two pieces inside it.","cn":"来源是出自 comparare 的 comparatio，其内部两个构件为 parare 与 com-。"},"items":[{"word":"comparison","structure":"Latin comparatio","meaning":"a pairing; a contrast","meaningCN":"配对；对照","example":"The noun names both the act and the verdict.","exampleCN":"这个名词既指动作也指裁决。"},{"word":"com-","structure":"Latin prefix","meaning":"together","meaningCN":"一起","example":"It puts two things on the same table.","exampleCN":"它把两样东西放到同一张桌上。"},{"word":"parare","structure":"Latin verb","meaning":"to make ready","meaningCN":"使齐备","example":"It also builds prepare and repair.","exampleCN":"它还构成 prepare 与 repair。"},{"word":"comparare","structure":"com- plus parare","meaning":"to compare, to pair","meaningCN":"比较；配对","example":"The verb is the engine of the whole family.","exampleCN":"这个动词是整个词族的引擎。"},{"word":"-ison","structure":"Latin -atio through French","meaning":"act or result","meaningCN":"行为；结果","example":"It appears in comparison and in simony's old pattern.","exampleCN":"它出现在 comparison 中，也见于类似的旧构词模式。"},{"word":"comparative","structure":"compare plus -ive","meaning":"serving for comparison","meaningCN":"用于比较的","example":"The adjective also names a grammar degree.","exampleCN":"这个形容词也指一个语法级别。"},{"word":"comparable","structure":"compare plus -able","meaning":"fit to be compared","meaningCN":"值得相比的","example":"The adjective judges the pair, not the act.","exampleCN":"这个形容词判断的是这一对，而非动作。"},{"word":"comparably","structure":"comparable plus -ly","meaning":"in a similar measure","meaningCN":"以类似程度","example":"It marks two results as close in size.","exampleCN":"它标出两个结果在量上接近。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不；非","example":"It builds incomparable, beyond any pairing.","exampleCN":"它构成 incomparable，意为无法配对。"}],"latinEntries":[{"word":"comparare","structure":"com- (together) + parare (make ready)","meaning":"to pair together; to compare","meaningCN":"配对；比较","example":"The verb is the source of both compare and comparison.","exampleCN":"这个动词是 compare 与 comparison 的共同来源。"},{"word":"comparatio","structure":"comparare + -tio (noun of action)","meaning":"a comparing; a contrast","meaningCN":"比较；对照","example":"Latin comparatio means a comparing, a contrast.","exampleCN":"拉丁语 comparatio 意为比较、对照。"},{"word":"parare","structure":"Latin verb parare (par-, paratum; to make ready)","meaning":"to make ready","meaningCN":"使齐备","example":"It supplies the pairing and preparing inside the verb.","exampleCN":"它提供动词中「配对、备齐」的成分。"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较；对照"},{"word":"comparative","pos":"adj.","zh":"比较的；比较级的"},{"word":"comparable","pos":"adj.","zh":"可比的"},{"word":"comparably","pos":"adv.","zh":"类似地"},{"word":"comparator","pos":"n.","zh":"比较器"},{"word":"incomparable","pos":"adj.","zh":"无可比拟的"}]}},{"word":"comparative analysis","ipa_uk":"/kəmˈpærətɪv əˈnæləsɪs/","ipa_us":"/kəmˈpærətɪv əˈnæləsɪs/","definition_zh":"比较分析；对比研究；跨案例的比较方法；（法律、政策、文学等领域的）比较分析","definition_en":"a method of study that sets two or more cases side by side and explains their similarities and differences","core_image":"两张摊开的表格并排放在桌上，同一栏的数据被红笔一对一对连起来","scene":"研究团队把六个城市的垃圾分类政策列成同一张表，逐项对照回收率与罚款额度。Their comparative analysis of six cities showed that deposit schemes worked better than fines.","sceneCN":"这里指把多个案例并置、逐项对照的研究方法（第 1 个义项：跨案例的比较分析）；句意为他们对六座城市的比较分析显示押金制比罚款更有效。场景图取象：两张表格并排，同一栏的数据被红线两两相连。","pos":[{"tag":"n.","zh":"比较分析；对比研究（方法）"},{"tag":"n.","zh":"（法律）比较法上的分析"},{"tag":"n.","zh":"（政策、文学、历史等领域的）跨案例比较分析"}],"collocations":[{"phrase":"conduct a comparative analysis","zh":"进行比较分析"},{"phrase":"comparative analysis of cases","zh":"案例比较分析"},{"phrase":"cross-national comparative analysis","zh":"跨国比较分析"},{"phrase":"comparative legal analysis","zh":"比较法律分析"},{"phrase":"comparative historical analysis","zh":"比较历史分析"},{"phrase":"a comparative analysis reveals","zh":"比较分析显示"},{"phrase":"quantitative comparative analysis","zh":"定量比较分析"}],"forms":[{"label":"单数","form":"comparative analysis"},{"label":"复数","form":"comparative analyses"},{"label":"作定语（形式不变）","form":"comparative analysis method"},{"label":"相关动词","form":"compare"},{"label":"相关名词","form":"comparison"},{"label":"相关形容词","form":"comparative"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较（由「一起」＋「使齐备」的拉丁构件合成，指把两物摆到一处量）"},{"word":"comparison","pos":"n.","zh":"比较；对照（比较动词的名词形式，指动作或结论）"},{"word":"comparative","pos":"adj.","zh":"比较的；比较研究的（加表示「倾向于、用于」的形容词后缀）"},{"word":"analyse","pos":"v.","zh":"分析（由希腊语「向上、彻底」的前缀加「松开」的动词构成，字面即把整体拆开看）"},{"word":"analysis","pos":"n.","zh":"分析；解析（上述动词的名词形式，指拆解后看清结构）"},{"word":"analyst","pos":"n.","zh":"分析者；分析师（加表示「人」的名词后缀）"}],"senses":[{"no":"01","title":"A cross-case method","titleCN":"跨案例的研究方法","definition":"a research method that examines several cases together in order to explain why they differ","definitionCN":"把若干案例放在一起考察、以解释其差异的研究方法","example":"A comparative analysis of six cities showed that deposit schemes worked better than fines.","exampleCN":"对六座城市的比较分析显示押金制比罚款更有效。","why":"One case can only describe; a second case gives the first something to be measured against.","whyCN":"单一案例只能描述，第二个案例才给第一个提供可比的参照。"},{"no":"02","title":"Policy comparison","titleCN":"政策比较","definition":"the systematic contrast of policies or institutions across jurisdictions","definitionCN":"跨辖区对政策或制度所作的系统对照","example":"Their comparative analysis of welfare systems covered nine countries.","exampleCN":"他们对福利制度的比较分析覆盖九个国家。","why":"Governments borrow from each other, and a structured comparison is how they decide what can travel.","whyCN":"政府彼此借鉴，而结构化的比较正是判断哪些做法可以移植的办法。"},{"no":"03","title":"Comparative legal analysis","titleCN":"比较法律分析","definition":"the study of how different legal systems treat the same question","definitionCN":"研究不同法律体系如何处理同一问题的学问","example":"The article offers a comparative analysis of liability rules in three codes.","exampleCN":"这篇文章对三部法典中的责任规则作了比较分析。","why":"Lawyers compare codes to see whether a rule is universal or merely local.","whyCN":"法律人比较法典，是要看一条规则是普遍的，还是只是本地的。"},{"no":"04","title":"Comparative literature","titleCN":"文学上的比较分析","definition":"the study of works from different languages or traditions in relation to each other","definitionCN":"把不同语言或传统的作品放在一起考察的研究","example":"Her comparative analysis of two epics changed the reading of both.","exampleCN":"她对两部史诗的比较分析改变了对两者的解读。","why":"A work seen beside a foreign cousin reveals conventions that a single tradition hides.","whyCN":"作品旁边站着一个异国亲戚，才会露出单一传统所遮蔽的成规。"},{"no":"05","title":"Statistical group comparison","titleCN":"统计上的组间比较","definition":"the formal contrast of two or more groups or conditions using quantitative data","definitionCN":"用定量数据对两个或多个组别或条件所作的正式对照","example":"A comparative analysis of the two cohorts found no difference in survival.","exampleCN":"对两个队列的比较分析未发现存活率差异。","why":"Numbers make comparison precise, and precision is what turns an impression into a finding.","whyCN":"数字让比较变得精确，而精确正是把印象变成发现的关口。"},{"no":"06","title":"Comparative historical analysis","titleCN":"比较历史分析","definition":"the comparison of historical cases or periods to identify causes and patterns","definitionCN":"比较历史案例或时期，以找出原因与模式","example":"Comparative historical analysis explained why two revolutions ended so differently.","exampleCN":"比较历史分析解释了两场革命为何结局迥异。","why":"History never repeats a case exactly, so the method compares near-cases to isolate what mattered.","whyCN":"历史不会原样重演，方法便比较相近的案例，以分离出真正起作用的因素。"},{"no":"07","title":"A business cost comparison","titleCN":"商业上的成本比较","definition":"a structured comparison of costs, benefits or options before a decision","definitionCN":"决策前对成本、收益或备选方案所作的结构化比较","example":"The board asked for a comparative analysis of building versus leasing.","exampleCN":"董事会要求对自建与租赁作一份比较分析。","why":"Firms compare options on one sheet so that a choice can be defended later.","whyCN":"企业把备选方案放在一张表上比较，好让日后的选择有据可依。"},{"no":"08","title":"A research design","titleCN":"一种研究设计","definition":"a formal design in which case selection and comparison are planned in advance","definitionCN":"事先规划好案例选择与对照方式的一种正式研究设计","example":"The course teaches comparative analysis as a design, not just a technique.","exampleCN":"这门课把比较分析当作一种研究设计来教，而不只是一种技巧。","why":"Choosing which cases to compare decides the answer before the data arrive, so it belongs to design.","whyCN":"选哪些案例来比，在数据到手前就决定了答案，所以它属于设计。"}],"etymology":{"intro":{"en":"Comparative analysis joins a Latin pair of words meaning 'to pair together' and a Greek one meaning 'to loosen up'. Both halves are well documented; the compound itself is a modern research label.","cn":"comparative analysis 把一个意为「配成对」的拉丁词与一个意为「拆开松开」的希腊词合在一起。两半的来源都有充分记录，这个复合词本身则是现代研究标签。"},"items":[{"era":"COMPARARE","en":"Latin comparare meant to bring two things level and measure one against the other, from com- 'together' and parare 'to make ready'.","cn":"拉丁语 comparare 意为把两物摆平、互相比量，由 com-「一起」与 parare「使齐备」构成。"},{"era":"COMPARATIVUS","en":"The Latin adjective comparativus marked whatever serves for comparison, and English took it as comparative.","cn":"拉丁形容词 comparativus 标出用于比较之物，英语取为 comparative。"},{"era":"GREEK ANALYSIS","en":"Greek analyein meant to loosen or break up a whole into its parts, from ana- 'up, throughout' and lyein 'to loosen'.","cn":"希腊语 analyein 意为把整体松开、拆成部分，由 ana-「向上、彻底」与 lyein「松开」构成。"},{"era":"THE PAIRING","en":"The two words were joined in nineteenth-century research writing, when comparison became an organised method.","cn":"这两个词在十九世纪的研究写作中结合，当时比较已成为有组织的方法。"},{"era":"THE COMPARATIVE METHOD","en":"Anatomy, law and religion all developed a comparative method, and each needed a name for its core operation.","cn":"解剖学、法学与宗教学都发展出比较方法，各自都需要一个名称来指其核心操作。"},{"era":"MODERN LABEL","en":"In the twentieth century the phrase settled as a term for cross-case research in social science and policy.","cn":"二十世纪，这一短语定型为社会科学与政策研究中跨案例研究的术语。"}]},"similar":{"note":{"en":"The first group shares one of the two roots or looks close; the second group holds methods that are often put beside comparative analysis.","cn":"第一组或共享两个词根之一，或字形相近；第二组是常与比较分析并列的其他方法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"comparative","ipa":"/kəmˈpærətɪv/","tag":"same root","definition":"The adjective alone, naming work based on comparison.","definitionCN":"单用的形容词，指以比较为基础的工作。"},{"word":"comparison","ipa":"/kəmˈpærɪsn/","tag":"same root","definition":"The noun for the act or the contrast, without the method's formality.","definitionCN":"指比较动作或对照的名词，不含方法上的正式性。"},{"word":"analysis","ipa":"/əˈnæləsɪs/","tag":"same root","definition":"The breaking up of a whole into parts, the second half of the phrase.","definitionCN":"把整体拆成部分，是这个词组的后一半。"},{"word":"analytical","ipa":"/ˌænəˈlɪtɪkl/","tag":"same root","definition":"The adjective from analysis, describing a method that separates parts.","definitionCN":"出自 analysis 的形容词，描述拆解部分的方法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"case study","ipa":"/ˈkeɪs stʌdi/","tag":"near meaning","definition":"A deep study of one case, which comparative analysis deliberately contrasts with others.","definitionCN":"对单一案例的深入研究所，比较分析有意拿它与别的案例对照。"},{"word":"cross-sectional study","ipa":"/ˌkrɒs sekˈʃənl ˈstʌdi/","tag":"near meaning","definition":"A study of many cases at one moment, usually statistical rather than historical.","definitionCN":"在同一时点考察许多案例，通常偏统计而非历史。"},{"word":"benchmarking","ipa":"/ˈbentʃmɑːkɪŋ/","tag":"near meaning","definition":"Comparing one's own performance with an external standard, common in management.","definitionCN":"把自身表现与外部标准相比，常见于管理领域。"},{"word":"meta-analysis","ipa":"/ˌmetə əˈnæləsɪs/","tag":"near meaning","definition":"Combining the results of many studies into one statistical summary.","definitionCN":"把许多研究的结果合成一个统计汇总。"},{"word":"content analysis","ipa":"/ˈkɒntent əˈnæləsɪs/","tag":"near meaning","definition":"Systematically coding texts, which may then be compared across sources.","definitionCN":"对文本系统编码，随后可跨来源比较。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real two roots, the real fixed phrases and the real research family.","cn":"正常联想使用真实的两个词根、真实固定说法与真实研究词族。"},"normal":[{"en":"The first half says pair together, the second half says break apart, so the phrase means pair cases and take them apart.","cn":"前一半说配成对，后一半说拆开来，整个词组就是先把案例配对再拆开看。"},{"en":"The family runs compare, comparison, comparative, analyse and analysis.","cn":"同族词有 compare、comparison、comparative、analyse 与 analysis。"},{"en":"Fixed phrases mark the uses: conduct a comparative analysis, cross-national comparative analysis, comparative legal analysis.","cn":"固定说法标出用法：进行比较分析、跨国比较分析、比较法律分析。"},{"en":"The plural is comparative analyses, because the head noun is analysis.","cn":"复数形式是 comparative analyses，因为中心词是 analysis。"},{"en":"A comparative analysis always names its cases, since the second case is half the method.","cn":"比较分析总要说明拿哪些案例来比，因为第二个案例就是方法的一半。"}],"abstract":[{"en":"Comparison without analysis lists differences; analysis without comparison explains only one world.","cn":"只比较不分析，只是列出差别；只分析不比较，只解释一个世界。"},{"en":"The method's honesty lies in saying which cases were left out.","cn":"这一方法的诚实，在于说出哪些案例被漏掉了。"},{"en":"Analysis without a second case is a portrait; comparison without analysis is a list.","cn":"没有第二个案例的分析只是一幅肖像；没有分析比较只是一张清单。"}]},"examples":[{"en":"Their comparative analysis of the two health systems took four years.","cn":"他们对两套医疗体系的比较分析花了四年。"},{"en":"A comparative analysis of rainfall records explained the crop failure.","cn":"对降雨记录的比较分析解释了这次歉收。"},{"en":"The paper's comparative analysis is careful about what the cases share.","cn":"这篇论文的比较分析对案例之间的共同点很谨慎。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"记作「先配对、再拆开」——把几个案例并排摆好，逐项对看：比较分析","word":"comparative analysis"},"root":"comparative（拉丁语 comparativus ← comparare「配成对」← com-「一起」＋ parare「使齐备」）＋ analysis（希腊语 analyein「松开、拆解」← ana-「彻底」＋ lyein「松开」）。复合术语于十九世纪研究写作中成形，二十世纪定型为跨案例研究之名。","sensesIntro":{"en":"Eight senses follow one method: a cross-case design, policy comparison, legal comparison, literary comparison, statistical groups, historical cases, business options, and the design itself.","cn":"八个义项沿着同一种方法展开：跨案例设计、政策比较、法律比较、文学比较、统计分组、历史案例、商业备选方案，以及研究设计本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: two open tables side by side, with entries in the same column joined by red lines.","cn":"核心意象：两张摊开的表格并排，同一栏的条目被红线两两连起。"},"chain":["PAIR TOGETHER","LOOSEN APART","SET CASES SIDE BY SIDE","EXPLAIN THE DIFFERENCE","A METHOD","A RESEARCH DESIGN"],"branches":[{"senses":"01 · 08","en":"THE METHOD AND THE DESIGN: cases chosen and compared on purpose, not merely noticed.","cn":"方法与设计：案例是被有意挑选、有意对照的，不只是顺手看见。"},{"senses":"02 · 07","en":"THE PRACTICAL CHOICE: policies and business options weighed on one sheet before a decision.","cn":"实务上的取舍：政策与商业备选方案在决策前放到一张表上称量。"},{"senses":"03 · 06","en":"THE INSTITUTION AND THE PERIOD: legal codes compared, and historical cases set beside each other.","cn":"制度与时期：法典被对照，历史案例被并置。"},{"senses":"04","en":"THE LITERARY COMPARISON: two traditions read against each other so that conventions show.","cn":"文学比较：两个传统互相映照，使成规显形。"},{"senses":"05","en":"THE NUMBERS: groups and cohorts compared with data rather than with impression.","cn":"数字：用数据而非印象比较组别与队列。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin comparative adjective and a Greek noun of breaking up, both still productive in English.","cn":"这个短语把拉丁的比较形容词与希腊的拆解名词合在一起，两者在英语中仍有构词力。"},"latinIntro":{"en":"Comparare supplies the first half; analyein supplies the second, through Latin and French forms.","cn":"前半出自 comparare，后半出自 analyein，经由拉丁与法语形态进入英语。"},"items":[{"word":"comparative analysis","structure":"comparative plus analysis","meaning":"a study by comparison of cases","meaningCN":"通过比较案例所作的研究","example":"The phrase is a fixed research term.","exampleCN":"这个短语是固定的研究术语。"},{"word":"com-","structure":"Latin prefix","meaning":"together","meaningCN":"一起","example":"It gives the first half its pairing sense.","exampleCN":"它给前半部分配对之意。"},{"word":"parare","structure":"Latin verb","meaning":"to make ready","meaningCN":"使齐备","example":"It also builds prepare and repair.","exampleCN":"它还构成 prepare 与 repair。"},{"word":"-ive","structure":"Latin -ivus","meaning":"serving for","meaningCN":"用于……的","example":"It turns comparare into an adjective.","exampleCN":"它把 comparare 变成形容词。"},{"word":"ana-","structure":"Greek prefix","meaning":"up, throughout","meaningCN":"向上；彻底","example":"It gives analysis the sense of taking apart thoroughly.","exampleCN":"它给 analysis 彻底拆解之意。"},{"word":"lyein","structure":"Greek verb","meaning":"to loosen","meaningCN":"松开","example":"The root supplies the image of loosening a knot.","exampleCN":"这个词根提供解开绳结的意象。"},{"word":"-sis","structure":"Greek noun ending","meaning":"process, action","meaningCN":"过程；动作","example":"It builds analysis, synthesis and diagnosis.","exampleCN":"它构成分析、综合与诊断等词。"},{"word":"-al","structure":"Latin -alis","meaning":"relating to","meaningCN":"与……有关的","example":"It builds analytical from analysis.","exampleCN":"它从 analysis 造出 analytical。"},{"word":"-ist","structure":"Greek -istes through Latin","meaning":"one who practises","meaningCN":"从事者","example":"It builds analyst, the person who does the work.","exampleCN":"它构成 analyst，指做这项工作的人。"}],"latinEntries":[{"word":"comparare","structure":"com- (together) + parare (make ready)","meaning":"to pair together; to compare","meaningCN":"配对；比较","example":"The verb supplies the comparing half of the term.","exampleCN":"这个动词提供该术语中「比较」那一半。"},{"word":"analysis","structure":"Greek analysis, from ana- (up) + lysis (loosening)","meaning":"a loosening; a resolving into parts","meaningCN":"松开；拆解为部分","example":"Greek analysis means a loosening up, a resolving into parts.","exampleCN":"希腊语 analysis 意为松开，即拆解为部分。"},{"word":"lyein","structure":"Greek verb lyein (to loosen)","meaning":"to loosen","meaningCN":"松开","example":"Greek lyein means to loosen, and gives -lysis in English.","exampleCN":"希腊语 lyein 意为松开，并给出英语的 -lysis。"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较"},{"word":"comparison","pos":"n.","zh":"比较；对照"},{"word":"comparative","pos":"adj.","zh":"比较的"},{"word":"analyse","pos":"v.","zh":"分析"},{"word":"analysis","pos":"n.","zh":"分析"},{"word":"analyst","pos":"n.","zh":"分析者"}]}},{"word":"theoretical model","ipa_uk":"/θɪəˈretɪkl ˈmɒdl/","ipa_us":"/θɪəˈretɪkl ˈmɑːdl/","definition_zh":"理论模型；理论模式；概念框架；（物理、经济等领域的）数学化理论构造","definition_en":"a simplified formal representation of a system, built from theory, that is used to explain or predict its behaviour","core_image":"一块透明板上画着几条相互连接的圆圈，真实世界的杂乱被简化成清晰的路径","scene":"工程师还没下钻，先在纸上画出含水层的层数与流向，用来估算压力会怎样变化。The team built a theoretical model of the aquifer before drilling the first well.","sceneCN":"这里指用理论构造出的简化表示（第 1 个义项：理论模型、概念框架）；句意为团队在钻第一口井之前先建了一个含水层的理论模型。场景图取象：透明板上几条相互连接的圆圈，把杂乱简化成清晰路径。","pos":[{"tag":"n.","zh":"理论模型；理论模式"},{"tag":"n.","zh":"（物理、化学的）数学模型化构造"},{"tag":"n.","zh":"（经济学的）理论分析框架"},{"tag":"n.","zh":"概念框架；用以指导研究的简化图式"}],"collocations":[{"phrase":"build a theoretical model","zh":"建立理论模型"},{"phrase":"theoretical model of the atom","zh":"原子的理论模型"},{"phrase":"economic theoretical model","zh":"经济学理论模型"},{"phrase":"test a theoretical model","zh":"检验理论模型"},{"phrase":"theoretical model predicts","zh":"理论模型预测"},{"phrase":"simplified theoretical model","zh":"简化的理论模型"},{"phrase":"the limits of a theoretical model","zh":"理论模型的限度"}],"forms":[{"label":"单数","form":"theoretical model"},{"label":"复数","form":"theoretical models"},{"label":"作定语（形式不变）","form":"theoretical model prediction"},{"label":"相关形容词","form":"theoretical"},{"label":"相关名词","form":"theory"},{"label":"相关动词","form":"model"}],"derivatives":[{"word":"theory","pos":"n.","zh":"理论；学说（出自希腊语「观看、旁观」，从「看的方式」转为「解释体系」）"},{"word":"theoretical","pos":"adj.","zh":"理论的；理论上的（加表示「与……有关」的形容词后缀）"},{"word":"theorist","pos":"n.","zh":"理论家（加表示「从事者」的名词后缀）"},{"word":"model","pos":"n./v.","zh":"模型；模式；模仿（出自拉丁语「小尺度」，从量具转为缩小的代表物）"},{"word":"modelling","pos":"n.","zh":"建模；模型制作（加表示「行为、过程」的词尾，指构造模型的工作）"},{"word":"theorize","pos":"v.","zh":"作理论推演；建立理论（加表示「使成为」的动词词尾）"}],"senses":[{"no":"01","title":"A simplified representation","titleCN":"简化的表示","definition":"a deliberately simplified representation of a system, built to make its behaviour easier to reason about","definitionCN":"对一个系统有意作出的简化表示，使其行为更容易推理","example":"The team built a theoretical model of the aquifer before drilling the first well.","exampleCN":"团队在钻第一口井之前先建了一个含水层的理论模型。","why":"A model is a small measure of a large thing, and theory supplies the shape that the measurement takes.","whyCN":"模型是对大事物的小尺度代表，而理论提供这次量取所采取的形状。"},{"no":"02","title":"A mathematical construction","titleCN":"数学化的构造","definition":"a set of equations or formal assumptions that generates predictions about a system","definitionCN":"一组方程或形式化假设，能对某系统生成预测","example":"The theoretical model reduces the climate to three variables.","exampleCN":"这个理论模型把气候简化成三个变量。","why":"Equations make a model precise enough to be wrong, which is what a theory needs.","whyCN":"方程让模型精确到足以出错，而这正是理论所需要的。"},{"no":"03","title":"A physicist's working picture","titleCN":"物理学家的作业图景","definition":"a standard construct in physics that organizes known behaviour and guides new experiments","definitionCN":"物理学中组织已知行为、指导新实验的标准构造","example":"The standard theoretical model of the atom treats electrons as waves.","exampleCN":"原子的标准理论模型把电子当作波。","why":"Physics often cannot see its objects directly, so a model stands in and is tested by its predictions.","whyCN":"物理学常常看不到对象本身，于是让模型代为站立，用预测来检验它。"},{"no":"04","title":"An economic framework","titleCN":"经济学的分析框架","definition":"a formal framework of assumptions in economics used to analyse choices, markets or growth","definitionCN":"经济学中一套形式化假设，用于分析选择、市场或增长","example":"The theoretical model assumes that buyers know all prices.","exampleCN":"这个理论模型假设买方知道所有价格。","why":"Economics builds from stated assumptions, and the model is the place where they are made visible.","whyCN":"经济学从明说的假设出发，模型正是这些假设显形的地方。"},{"no":"05","title":"Untested theory, not yet data","titleCN":"尚未受数据检验的理论","definition":"a model that has been constructed but not yet checked against observation","definitionCN":"已经建好、但尚未对照观测检验的模型","example":"The paper's contribution is still a theoretical model, not a result.","exampleCN":"这篇论文的贡献仍是一个理论模型，而不是一个结果。","why":"The adjective marks the gap between a construction and a finding, a distinction reviewers guard.","whyCN":"这个形容词标出构造与发现之间的空隙，审稿人对此看得很紧。"},{"no":"06","title":"A simulation's basis","titleCN":"模拟所依据的模型","definition":"the theoretical core on which a computer simulation or forecast is built","definitionCN":"计算机模拟或预报所依托的理论内核","example":"The forecast runs on a theoretical model of ocean currents.","exampleCN":"这份预报运行在一个洋流的理论模型之上。","why":"Simulation adds computation to theory; the model is what the machine is told to obey.","whyCN":"模拟是在理论上加计算，模型就是机器被要求服从的那套东西。"},{"no":"07","title":"A guide for experiment","titleCN":"指导实验的框架","definition":"a model used to decide which measurements matter and what result would count as support","definitionCN":"用来决定哪些测量要紧、什么结果算支持模型的框架","example":"The theoretical model told them which two temperatures to test.","exampleCN":"这个理论模型告诉他们该测哪两个温度。","why":"A model that predicts nothing specific cannot guide a bench, so usefulness is its own test.","whyCN":"什么具体结果都预测不出的模型指导不了实验台，因此有用本身就是一种检验。"},{"no":"08","title":"A model known to be wrong","titleCN":"明知不完美却仍有用的模型","definition":"a simplified model accepted despite known inaccuracies, because it explains enough","definitionCN":"明知不准确却仍被接受的简化模型，因为它解释得够用","example":"Every theoretical model is wrong somewhere, but some are useful.","exampleCN":"每个理论模型都在某处是错的，但有些仍然有用。","why":"The purpose is explanation, not mimicry; a map the size of the country would be useless.","whyCN":"目的是解释而非复制；一张与国土等大的地图反而没有用。"}],"etymology":{"intro":{"en":"Theoretical model joins Greek theoria, 'a looking or viewing', with Latin modulus, 'a small measure'. Both halves are well documented; the compound is a modern scientific phrase.","cn":"theoretical model 把希腊语 theoria「观看」与拉丁语 modulus「小尺度」合在一起。两半来源都有充分记录，这个复合词是现代科学用语。"},"items":[{"era":"GREEK THEORIA","en":"Theoria meant a viewing or a spectacle, and it named the act of looking at something for understanding rather than for use.","cn":"theoria 意为观看、景象，指为理解而非为实用去看一件事。"},{"era":"THEOROS","en":"The related word for a spectator or envoy shows the root idea of someone sent to watch, which gives theory its air of distance.","cn":"相关的「观看者、使者」一词显出「被派去看」的词根意象，理论由此带上距离感。"},{"era":"LATIN MODULUS","en":"Modulus meant a small measure, from modus, a measure or manner, and it survives in module and model.","cn":"modulus 意为小尺度，出自 modus「尺度、方式」，在 module 与 model 中留存。"},{"era":"ENGLISH THEORY","en":"English took theory in the sixteenth century, first for a scheme of ideas and later for an explanation of observed facts.","cn":"英语在十六世纪借入 theory，先指一套观念，后指对观测事实的解释。"},{"era":"MODEL AS A COPY","en":"By the eighteenth century model meant a small copy of a thing, and by the nineteenth a formal representation of a system.","cn":"到十八世纪，model 指事物的小型复制品；到十九世纪，指系统的形式化表示。"},{"era":"THE COMPOUND","en":"The phrase theoretical model became standard in twentieth-century physics and economics, where construction precedes measurement.","cn":"二十世纪，这一短语在物理与经济学中成为标准说法，那里构造先于测量。"}]},"similar":{"note":{"en":"The first group shares one of the two roots or looks close; the second group holds the neighbouring constructs that are often called models by mistake.","cn":"第一组或共享两个词根之一，或字形相近；第二组是常被误称为模型的邻近构造。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"theory","ipa":"/ˈθɪəri/","tag":"same root","definition":"A system of explanation, the first half of the phrase.","definitionCN":"一套解释体系，是词组的前一半。"},{"word":"theoretical","ipa":"/θɪəˈretɪkl/","tag":"same root","definition":"Concerning theory rather than practice or measurement.","definitionCN":"关涉理论而非实践或测量。"},{"word":"model","ipa":"/ˈmɒdl/","tag":"same root","definition":"A simplified representation or a small copy.","definitionCN":"简化的表示或小型复制品。"},{"word":"modelling","ipa":"/ˈmɒdəlɪŋ/","tag":"same root","definition":"The activity of building models, now mostly computational.","definitionCN":"构建模型的活动，如今多指计算建模。"},{"word":"therapeutic","ipa":"/ˌθerəˈpjuːtɪk/","tag":"different root","definition":"Healing; it shares a Greek shape but comes from a verb meaning to attend or serve.","definitionCN":"有疗愈作用的；希腊词形相近，词根却意为照料、服务。"}]},{"heading":"NEAR MEANING","entries":[{"word":"conceptual framework","ipa":"/kənˈseptʃuəl ˈfreɪmwɜːk/","tag":"near meaning","definition":"An organised set of ideas that guides research, often less formal than a model.","definitionCN":"指导研究的一套有组织的观念，通常不如模型形式化。"},{"word":"simulation","ipa":"/ˌsɪmjuˈleɪʃn/","tag":"near meaning","definition":"A running computation of a model over time, the model put to work.","definitionCN":"让模型随时间运行的计算，是模型被投入使用。"},{"word":"hypothesis","ipa":"/haɪˈpɒθəsɪs/","tag":"near meaning","definition":"A single testable proposal, smaller than a model and easier to kill.","definitionCN":"单个可检验的提议，比模型小，也更容易被推翻。"},{"word":"framework","ipa":"/ˈfreɪmwɜːk/","tag":"near meaning","definition":"A supporting structure of ideas, which may not generate predictions.","definitionCN":"支撑性的观念结构，未必能生成预测。"},{"word":"paradigm","ipa":"/ˈpærədaɪgm/","tag":"near meaning","definition":"A whole way of working within a field, larger than any single model.","definitionCN":"一个领域内整套工作方式，比任何单个模型都大。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Greek viewing root, the real Latin measure word and real fixed phrases.","cn":"正常联想使用真实的希腊「观看」词根、真实的拉丁「尺度」词与真实固定搭配。"},"normal":[{"en":"Theoria is a viewing, modulus is a small measure, so a theoretical model is a small measured picture of something too large to see.","cn":"前者是观看，后者是小尺度，合起来就是用缩小尺寸画出的图，去看太大的东西。"},{"en":"The family runs theory, theoretical, theorist, model, modelling and module.","cn":"同族词有 theory、theoretical、theorist、model、modelling 与 module。"},{"en":"Fixed phrases mark the uses: build a theoretical model, test a theoretical model, the limits of a model.","cn":"固定说法标出用法：建立理论模型、检验理论模型、模型的限度。"},{"en":"The plural is theoretical models, because the head noun is model.","cn":"复数是 theoretical models，因为中心词是 model。"},{"en":"A model that predicts nothing specific cannot guide an experiment.","cn":"预测不出具体结果的模型，指导不了实验。"}],"abstract":[{"en":"A theoretical model is a promise that the mess can be written down in fewer lines.","cn":"理论模型是一个承诺：这团杂乱能用更少的几行写下来。"},{"en":"Its usefulness and its falseness are often the same property seen from two sides.","cn":"它的有用与它的错误，常常是同一性质的两面。"},{"en":"Every model is a small lie told in order to tell a large truth.","cn":"每个模型都是一个为了说出大真相而撒的小谎。"}]},"examples":[{"en":"The theoretical model predicted a rise that the data later confirmed.","cn":"理论模型预言了一次上升，数据后来证实了它。"},{"en":"Without a theoretical model, the measurements were just numbers.","cn":"没有理论模型，那些测量只是一堆数字。"},{"en":"The theoretical model deliberately ignores friction to keep the equations simple.","cn":"这个理论模型有意忽略摩擦，以保持方程简单。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"记作「看的方式＋小尺度」——把大东西缩小画成图，再用理论去看：理论模型","word":"theoretical model"},"root":"theoretical（希腊语 theoria「观看」＋形容词词尾）＋ model（拉丁语 modulus「小尺度」← modus「尺度、方式」）。两词在二十世纪的物理与经济学中合成固定短语，指先构造、后测量的形式化表示。","sensesIntro":{"en":"Eight senses follow one construction: a simplified picture, equations, a physicist's working image, an economic framework, untested theory, a simulation's core, a guide for experiment, and a model known to be wrong.","cn":"八个义项沿着同一种构造：简化的图景、方程、物理学家的作业图像、经济学框架、未经检验的理论、模拟的内核、实验的指南，以及明知有错的模型。"},"semanticMap":{"core":{"en":"CORE IMAGE: a transparent sheet with linked circles on it, standing in for a tangle it cannot copy.","cn":"核心意象：一块透明板上画着相连的圆圈，代替它复制不了的乱麻。"},"chain":["VIEW","A SMALL MEASURE","A SIMPLIFIED PICTURE","EQUATIONS","PREDICTION","TEST AGAINST DATA"],"branches":[{"senses":"01 · 03","en":"THE PICTURE THAT STANDS IN: a simplified image of a system, including a physicist's working drawing of the atom.","cn":"代为站立的图：系统的简化图像，包括物理学家关于原子的作业图。"},{"senses":"02 · 06","en":"THE EQUATIONS AND THE RUN: formal assumptions that generate numbers, and the simulation built on them.","cn":"方程与运行：生成数字的形式假设，以及建在其上的模拟。"},{"senses":"04","en":"THE ECONOMIC FRAMEWORK: assumptions about buyers and prices made visible on one page.","cn":"经济学框架：关于买方与价格的假设，在一页纸上显形。"},{"senses":"05 · 08","en":"THE GAP FROM FACT: a construction not yet tested, and a model accepted although known to be wrong.","cn":"与事实的间距：尚未受检的构造，以及明知有错仍被接受的模型。"},{"senses":"07","en":"THE GUIDE: a model that decides which measurement matters.","cn":"指南：决定哪一项测量要紧的模型。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek noun of viewing and a Latin noun of measuring, both of which have large English families.","cn":"这个短语把希腊的「观看」名词与拉丁的「量度」名词合在一起，两者在英语中都有大词族。"},"latinIntro":{"en":"Theoria and modulus are the two sources; the endings -ical and -el came through Latin and French forms.","cn":"theoria 与 modulus 是两个来源，-ical 与 -el 词尾经由拉丁与法语形态而来。"},"items":[{"word":"theoretical model","structure":"Greek theoria plus Latin modulus","meaning":"a formal simplified representation","meaningCN":"形式化的简化表示","example":"The phrase names a construction, not a measurement.","exampleCN":"这个短语指一种构造，而非一次测量。"},{"word":"theoria","structure":"Greek noun","meaning":"a viewing, a contemplation","meaningCN":"观看；沉思","example":"It gives theory its air of looking rather than doing.","exampleCN":"它给理论带上观看而非动手的意味。"},{"word":"theoros","structure":"Greek noun","meaning":"a spectator, an envoy sent to watch","meaningCN":"观看者；被派去看的使者","example":"The root image is someone watching from a distance.","exampleCN":"词根意象是从远处观看的人。"},{"word":"-ical","structure":"Greek -ikos through Latin","meaning":"relating to","meaningCN":"与……有关的","example":"It builds theoretical, practical and medical.","exampleCN":"它构成理论的、实践的和医学的等词。"},{"word":"modus","structure":"Latin noun","meaning":"measure, manner","meaningCN":"尺度；方式","example":"It also gives mode and moderate.","exampleCN":"它还给出 mode 与 moderate。"},{"word":"modulus","structure":"Latin diminutive","meaning":"a small measure","meaningCN":"小尺度","example":"The diminutive makes the model a small version of a large thing.","exampleCN":"指小形式让模型成为大事物的小版本。"},{"word":"-el","structure":"Latin -ellus through Italian","meaning":"small","meaningCN":"小的","example":"It survives in model, a small copy.","exampleCN":"它留存在 model 中，指小型复制品。"},{"word":"-ing","structure":"English suffix","meaning":"activity or process","meaningCN":"活动；过程","example":"It builds modelling, the work of making models.","exampleCN":"它构成 modelling，即建模工作。"},{"word":"-ist","structure":"Greek -istes","meaning":"one who practises","meaningCN":"从事者","example":"It builds theorist, a maker of theory.","exampleCN":"它构成 theorist，即理论制造者。"}],"latinEntries":[{"word":"theoria","structure":"Greek theoria (a viewing), borrowed into Latin","meaning":"a viewing; contemplation","meaningCN":"观看；沉思","example":"Greek theoria means a viewing or contemplation.","exampleCN":"希腊语 theoria 意为观看、沉思。"},{"word":"modulus","structure":"modus (measure) + -ulus (diminutive)","meaning":"a small measure","meaningCN":"小尺度","example":"Latin modulus means a small measure.","exampleCN":"拉丁语 modulus 意为小尺度。"},{"word":"modus","structure":"Latin noun modus (measure, manner)","meaning":"measure, manner","meaningCN":"尺度；方式","example":"Latin modus means measure or manner, and gives English mode.","exampleCN":"拉丁语 modus 意为尺度、方式，并给出英语 mode。"}],"derivatives":[{"word":"theory","pos":"n.","zh":"理论；学说"},{"word":"theoretical","pos":"adj.","zh":"理论的；理论上的"},{"word":"theorist","pos":"n.","zh":"理论家"},{"word":"model","pos":"n./v.","zh":"模型；模式"},{"word":"modelling","pos":"n.","zh":"建模"},{"word":"theorize","pos":"v.","zh":"作理论推演"}]}},{"word":"scientific advancement","ipa_uk":"/ˌsaɪənˈtɪfɪk əˈvɑːnsmənt/","ipa_us":"/ˌsaɪənˈtɪfɪk əˈvænsmənt/","definition_zh":"科学进步；科学进展；科学上的突破；（整体的）科学知识推进","definition_en":"progress in scientific knowledge, or a specific step forward such as a discovery or a better method","core_image":"一支温度计的刻度被往前推了一格，旁边旧的那一格还留着淡痕","scene":"显微镜改良之后，医生第一次看清了细胞里那些细小的结构。The microscope was a scientific advancement that changed medicine within a generation.","sceneCN":"这里指科学上的具体进步或突破（第 2 个义项：一项科学突破）；句意为显微镜是一项在一代人之内改变了医学的科学进步。场景图取象：温度计的刻度被往前推了一格，旧痕仍在。","pos":[{"tag":"n.","zh":"科学进步；科学进展（不可数）"},{"tag":"n.","zh":"一项科学突破；一项具体进展（可数）"},{"tag":"n.","zh":"（整体的）科学知识推进"}],"collocations":[{"phrase":"a major scientific advancement","zh":"一项重大科学进步"},{"phrase":"scientific advancement in medicine","zh":"医学上的科学进步"},{"phrase":"the pace of scientific advancement","zh":"科学进步的速度"},{"phrase":"scientific and technological advancement","zh":"科学与技术进步"},{"phrase":"hinder scientific advancement","zh":"阻碍科学进步"},{"phrase":"advancement of knowledge","zh":"知识的推进"},{"phrase":"a century of scientific advancement","zh":"一个世纪的科学进步"}],"forms":[{"label":"单数","form":"scientific advancement"},{"label":"复数","form":"scientific advancements"},{"label":"作定语（形式不变）","form":"scientific advancement policy"},{"label":"相关形容词","form":"scientific"},{"label":"相关名词","form":"science"},{"label":"相关动词","form":"advance"}],"derivatives":[{"word":"science","pos":"n.","zh":"科学（出自拉丁语「知识」一词，从「知道」转为系统化的知识）"},{"word":"scientific","pos":"adj.","zh":"科学的（加表示「与……有关」的形容词后缀）"},{"word":"scientist","pos":"n.","zh":"科学家（加表示「从事者」的名词后缀）"},{"word":"advance","pos":"v./n.","zh":"推进；前进；进展（出自法语「向前」一词，由拉丁语「从前面」而来）"},{"word":"advancement","pos":"n.","zh":"推进；进步；晋升（加表示「行为、结果」的名词后缀）"},{"word":"advanced","pos":"adj.","zh":"先进的；高级的（过去分词转形容词，指已经走在前头）"}],"senses":[{"no":"01","title":"Progress of knowledge","titleCN":"知识的推进","definition":"the gradual growth of scientific understanding over time","definitionCN":"科学理解随时间逐步增长","example":"Scientific advancement depends on instruments as much as on ideas.","exampleCN":"科学进步既靠想法，也靠仪器。","why":"The word for going forward is applied to knowledge itself, which is imagined as moving ahead.","whyCN":"表示向前的词被用到了知识上，知识于是被想象成在往前走。"},{"no":"02","title":"A specific breakthrough","titleCN":"一项具体突破","definition":"one identifiable step forward, such as a discovery, a method or a device","definitionCN":"可指认的一步前进，如一项发现、一种方法或一件器械","example":"The microscope was a scientific advancement that changed medicine within a generation.","exampleCN":"显微镜是一项在一代人之内改变了医学的科学进步。","why":"Big progress is counted in units, and each unit needs a name it can be pointed at.","whyCN":"大的进步按件来数，每一件都需要一个能指认的名字。"},{"no":"03","title":"Cumulative growth","titleCN":"累积式的增长","definition":"the accumulation of reliable findings that later work can build on","definitionCN":"可靠发现不断积累，后来的工作可以接着往上建","example":"Scientific advancement is cumulative, even when it looks sudden.","exampleCN":"科学进步是累积的，即使看起来像是突然发生。","why":"New work stands on published work, so progress is a pile rather than a leap.","whyCN":"新工作站在已发表的工作上，因此进步是一堆而不是一跳。"},{"no":"04","title":"Advance that becomes technology","titleCN":"转化为技术的进步","definition":"scientific progress that is taken up in tools, medicine or industry","definitionCN":"被工具、医学或工业吸收的科学进展","example":"The sequencing method was a scientific advancement that soon became a clinic test.","exampleCN":"这种测序方法是一项科学进步，很快就成了临床检测。","why":"The public usually meets science through its devices, so the phrase often means applied progress.","whyCN":"公众通常经由器械遇见科学，所以这一说法常指应用上的进展。"},{"no":"05","title":"A better method","titleCN":"更好的方法","definition":"an improvement in how science is done, such as a new control or a new statistic","definitionCN":"做科学的方式得到改进，如新的对照设计或新的统计方法","example":"Randomised trials were a quiet scientific advancement with vast effects.","exampleCN":"随机对照试验是一项安静的科学进步，影响却极大。","why":"Methods are invisible in the result but decide whether the result can be trusted.","whyCN":"方法在结果里看不见，却决定结果是否可信。"},{"no":"06","title":"Institutional progress","titleCN":"制度层面的推进","definition":"growth in the institutions, funding or training that support research","definitionCN":"支撑研究的机构、经费或人才培养的增长","example":"The new laboratory was called an advancement for the whole region.","exampleCN":"这座新实验室被称为整个地区的一大进步。","why":"Institutions speak of advancement when they mean capacity, not a single discovery.","whyCN":"机构说进步时，往往指能力，而不是某一项发现。"},{"no":"07","title":"A claim to be judged","titleCN":"有待评判的宣称","definition":"a public claim that something new is progress, which still has to be assessed","definitionCN":"公开宣称某项新事物是进步，但仍需评估","example":"Not every scientific advancement announced in a press release survives review.","exampleCN":"并非每个在新闻稿里宣告的科学进步都能挺过评审。","why":"The phrase is also used in publicity, and calling something an advancement does not make it one.","whyCN":"这一说法也用于宣传，把一件事称为进步并不等于它真是进步。"},{"no":"08","title":"Progress with a cost","titleCN":"带有代价的进步","definition":"scientific progress considered together with its risks, costs or unequal benefits","definitionCN":"连同风险、代价或分配不均一并考虑的科学进展","example":"Every scientific advancement brings a question about who will control it.","exampleCN":"每一项科学进步都会带来一个问题：由谁掌控。","why":"The word advance assumes a direction, and critics ask forward for whom.","whyCN":"「前进」一词预设了方向，批评者便问：这是替谁往前。"}],"etymology":{"intro":{"en":"The phrase joins Latin scientia 'knowledge' with French avancement, from Latin abante 'from before'. Both halves are clear; the compound is a modern label for progress.","cn":"这个短语把拉丁语 scientia「知识」与法语 avancement 合在一起，后者出自拉丁语 abante「从前面」。两半来源清楚，这个复合词是现代的进步标签。"},"items":[{"era":"SCIRE","en":"Scire meant to know, and its present participle scientia named knowledge or a body of knowing.","cn":"scire 意为知道，其现在分词 scientia 指知识或一整套所知。"},{"era":"SCIENTIA","en":"Latin scientia covered knowledge in general before English narrowed it to organised, testable knowledge.","cn":"拉丁语 scientia 泛指知识，英语后来把它收窄为有组织、可检验的知识。"},{"era":"ABANTE","en":"Latin abante meant from before or in front, and French built avancer, to move forward, on it.","cn":"拉丁语 abante 意为从前面、在前方，法语据此造出 avancer「向前移动」。"},{"era":"ADVANCEMENT","en":"English took advancement in the fifteenth century for promotion and for forward movement in general.","cn":"英语在十五世纪借入 advancement，指晋升，也泛指向前推进。"},{"era":"SCIENTIFIC","en":"The adjective scientific appeared in the seventeenth century, when the word science acquired its modern, method-bound sense.","cn":"形容词 scientific 出现在十七世纪，当时 science 获得现代那种受方法约束的含义。"},{"era":"THE COMPOUND","en":"The phrase scientific advancement became common in the nineteenth and twentieth centuries, as progress became a public expectation.","cn":"十九与二十世纪，这一短语变得常见，因为进步成了一种公共期待。"}]},"similar":{"note":{"en":"The first group shares one of the two roots or looks close; the second group holds the words used for progress that are not quite the same claim.","cn":"第一组或共享两个词根之一，或字形相近；第二组是表示进展但并不等同的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"science","ipa":"/ˈsaɪəns/","tag":"same root","definition":"The organised body of knowledge itself, not a step within it.","definitionCN":"有组织的知识本身，而非其中的一步。"},{"word":"scientific","ipa":"/ˌsaɪənˈtɪfɪk/","tag":"same root","definition":"The adjective for method, attitude or knowledge of that kind.","definitionCN":"指这类方法、态度或知识的形容词。"},{"word":"advance","ipa":"/əˈvɑːns/","tag":"same root","definition":"To move forward, or a forward step, the verb and noun inside the phrase.","definitionCN":"向前移动或向前一步，是词组里的动词与名词。"},{"word":"advanced","ipa":"/əˈvɑːnst/","tag":"same root","definition":"Far along in development, describing a state rather than an act.","definitionCN":"发展程度靠前，描述状态而非动作。"},{"word":"advantage","ipa":"/əˈvɑːntɪdʒ/","tag":"different root","definition":"A benefit; it looks like advance but comes from a phrase meaning before the front.","definitionCN":"好处；字形近似，却出自意为「在前方」的词组变异。"}]},{"heading":"NEAR MEANING","entries":[{"word":"breakthrough","ipa":"/ˈbreɪkθruː/","tag":"near meaning","definition":"A sudden decisive advance, sharper and more dramatic than progress.","definitionCN":"突然而决定性的推进，比一般进步更锋利、更戏剧化。"},{"word":"discovery","ipa":"/dɪsˈkʌvəri/","tag":"near meaning","definition":"Finding something that already existed, which may or may not be progress.","definitionCN":"发现本已存在之物，未必构成进步。"},{"word":"innovation","ipa":"/ˌɪnəˈveɪʃn/","tag":"near meaning","definition":"A new product or practice put to use, closer to application than to knowledge.","definitionCN":"投入应用的新产品、新做法，更近应用而非知识。"},{"word":"progress","ipa":"/ˈprəʊɡres/","tag":"near meaning","definition":"General forward movement, which need not be scientific or cumulative.","definitionCN":"泛指向前推进，未必是科学的或累积的。"},{"word":"technological advance","ipa":"/ˌteknəˈlɒdʒɪkl əˈvɑːns/","tag":"near meaning","definition":"Progress in tools and technique, the usual partner or rival of the scientific kind.","definitionCN":"工具与技艺上的进展，常与科学进步并列或相争。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real knowing and forward roots, the real family and real fixed phrases.","cn":"正常联想使用真实的「知道」与「向前」词根、真实词族与真实固定搭配。"},"normal":[{"en":"Scire is to know and abante is in front, so scientific advancement is knowledge moving forward.","cn":"前者是知道，后者是在前，合起来就是知识向前走。"},{"en":"The family runs science, scientific, scientist, advance, advancement and advanced.","cn":"同族词有 science、scientific、scientist、advance、advancement 与 advanced。"},{"en":"Fixed phrases mark the uses: a major scientific advancement, the pace of scientific advancement, scientific and technological advancement.","cn":"固定说法标出用法：一项重大科学进步、科学进步的速度、科学与技术进步。"},{"en":"The plural counts individual steps; the singular names the whole movement.","cn":"复数数的是具体步伐，单数指整个进程。"},{"en":"Advancement is not the same as advantage, which is only a benefit.","cn":"进步不同于优势，后者只是好处。"}],"abstract":[{"en":"Scientific advancement enlarges what can be done before it settles what should be done.","cn":"科学进步先扩大能做的事，然后才轮到该做的事。"},{"en":"The word assumes a direction; the argument is always about who is being carried forward.","cn":"这个词预设了方向，争论总在于谁被带着向前。"},{"en":"An advancement is measured backwards, by what later work can no longer imagine doing without.","cn":"进步是倒着量的，量的是后来的工作再也无法想象缺少什么。"}]},"examples":[{"en":"Clean water was a scientific advancement that saved more lives than any drug.","cn":"洁净水是一项科学进步，救的命比任何药物都多。"},{"en":"Scientific advancement slowed when the funding was cut.","cn":"经费被削减后，科学进步慢了下来。"},{"en":"The committee asked whether the device was a real scientific advancement.","cn":"委员会追问这件装置是否真是科学上的进步。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"记作「知识向前走一格」——刻度又推进了一格：科学进步","word":"scientific advancement"},"root":"scientific（拉丁语 scientia「知识」← scire「知道」＋形容词词尾）＋ advancement（法语 avancement ← 拉丁语 abante「从前、在前」）。science 在十七世纪收窄为受方法约束的知识体系，这一复合短语在十九、二十世纪成为公共用语。","sensesIntro":{"en":"Eight senses follow one forward movement: the growth of understanding, a specific breakthrough, cumulative findings, applied technology, better method, institutional capacity, a claim still to be judged, and progress weighed with its costs.","cn":"八个义项沿着同一次向前：理解的生长、一项具体突破、累积的发现、转入应用的技术、更好的方法、机构能力、仍待评判的宣称，以及连同代价一并称量的进步。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gauge whose mark has been pushed one notch forward, the old notch still faintly visible.","cn":"核心意象：刻度被往前推了一格，旧的一格还留着淡痕。"},"chain":["KNOW","KNOWLEDGE","MOVE FORWARD","A STEP","APPLICATION","PUBLIC EXPECTATION"],"branches":[{"senses":"01 · 03","en":"THE LONG MOVEMENT: understanding grows, and each reliable finding lets the next stand on it.","cn":"漫长的移动：理解在生长，每个可靠发现都让下一个站上去。"},{"senses":"02 · 05","en":"THE SINGLE STEP: a device or a better method that can be pointed at and dated.","cn":"单独的一步：能指认、能定年的一件器械或一种更好的方法。"},{"senses":"04 · 06","en":"THE APPLIED AND THE INSTITUTIONAL: progress taken up by clinics and industry, or by laboratories and funding.","cn":"应用与制度：被诊所与工业吸收的进展，或被实验室与经费吸收的进展。"},{"senses":"07","en":"THE CLAIM: a press release's word for progress, which review has not yet settled.","cn":"宣称：新闻稿里对进步的称呼，评审尚未定论。"},{"senses":"08","en":"THE COST: the same step seen with its risks and its unequal benefits.","cn":"代价：同一步伐连同风险与分配不均一起看。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin word of knowing with a French word of moving forward, and both halves support large families.","cn":"这个短语把拉丁的「知道」与法语的「向前」合在一起，两半都支撑着大词族。"},"latinIntro":{"en":"Scientia and abante are the sources behind scientific and advancement.","cn":"scientia 与 abante 是 scientific 与 advancement 背后的来源。"},"items":[{"word":"scientific advancement","structure":"scientific plus advancement","meaning":"progress in knowledge or method","meaningCN":"知识或方法上的进步","example":"The phrase can mean one step or the whole movement.","exampleCN":"这个短语可指一步，也可指整个进程。"},{"word":"scire","structure":"Latin verb","meaning":"to know","meaningCN":"知道","example":"It supplies the present participle behind scientia.","exampleCN":"它提供 scientia 背后的现在分词。"},{"word":"scientia","structure":"Latin noun","meaning":"knowledge","meaningCN":"知识","example":"English narrowed it to organised, testable knowledge.","exampleCN":"英语把它收窄为有组织、可检验的知识。"},{"word":"-ific","structure":"Latin -ificus","meaning":"making, causing","meaningCN":"造成……的","example":"It appears in scientific and specific.","exampleCN":"它出现在 scientific 与 specific 中。"},{"word":"-ist","structure":"Greek and Latin -ista","meaning":"one who practises","meaningCN":"从事者","example":"It builds scientist, the person who knows by method.","exampleCN":"它构成 scientist，指以方法求知的人。"},{"word":"abante","structure":"Latin phrase","meaning":"from before, in front","meaningCN":"从前；在前","example":"French built avancer on it.","exampleCN":"法语据此造出 avancer。"},{"word":"avancer","structure":"Old French verb","meaning":"to move forward","meaningCN":"向前移动","example":"The verb supplies the movement in advancement.","exampleCN":"这个动词提供 advancement 中的移动。"},{"word":"-ment","structure":"Latin -mentum through French","meaning":"result or act","meaningCN":"结果；行为","example":"It builds advancement, agreement and measurement.","exampleCN":"它构成进步、一致与测量等词。"},{"word":"ad-","structure":"Latin prefix","meaning":"to, toward","meaningCN":"向；朝","example":"It appears in advanced and in advance.","exampleCN":"它出现在 advanced 与 advance 中。"}],"latinEntries":[{"word":"scientia","structure":"sciens (knowing) + -ia (noun suffix)","meaning":"knowledge","meaningCN":"知识","example":"The noun gives the first half of the phrase.","exampleCN":"这个名词提供该短语的前半部分。"},{"word":"scire","structure":"Latin verb scire (sci-, scitum; to know)","meaning":"to know","meaningCN":"知道","example":"The verb is the oldest element behind the phrase.","exampleCN":"这个动词是该短语背后最古老的成分。"},{"word":"abante","structure":"ab (from) + ante (before)","meaning":"from before, in front","meaningCN":"从前；在前","example":"Late Latin abante means from before, in front.","exampleCN":"晚期拉丁语 abante 意为从前、在前。"}],"derivatives":[{"word":"science","pos":"n.","zh":"科学"},{"word":"scientific","pos":"adj.","zh":"科学的"},{"word":"scientist","pos":"n.","zh":"科学家"},{"word":"advance","pos":"v./n.","zh":"推进；进展"},{"word":"advancement","pos":"n.","zh":"推进；进步"},{"word":"advanced","pos":"adj.","zh":"先进的"}]}},{"word":"autonomous","ipa_uk":"/ɔːˈtɒnəməs/","ipa_us":"/ɔːˈtɑːnəməs/","definition_zh":"自治的；自主的；有自主权的；自行运转的；（车辆、机器）无人驾驶的、自主运行的","definition_en":"governing itself or acting on its own, without control from outside, including machines that operate without a driver","core_image":"一辆没有驾驶座的车在田垄间自己转弯，方向盘转得比人手还稳","scene":"拖拉机沿着垄沟自己走，遇到地头的石堆就减速绕开，驾驶室里空着。An autonomous tractor steers itself across the field and slows for the stones at the edge.","sceneCN":"这里指机器无人驾驶、自行作业（第 4 个义项：无人驾驶的、自主运行的）；句意为这台无人驾驶的拖拉机自己穿过田地，遇到地边的石堆就减速。场景图取象：一辆没有驾驶座的车在田垄间自己转弯。","pos":[{"tag":"adj.","zh":"自治的；自主的（地区、机构）"},{"tag":"adj.","zh":"自主行动的；不受外部支配的（人、决定）"},{"tag":"adj.","zh":"（车辆、机器）无人驾驶的；自主运行的"},{"tag":"adj.","zh":"（哲学、伦理）自律的；自我立法的"}],"collocations":[{"phrase":"autonomous region","zh":"自治区"},{"phrase":"autonomous vehicle","zh":"无人驾驶车辆"},{"phrase":"autonomous system","zh":"自主系统"},{"phrase":"autonomous learning","zh":"自主学习"},{"phrase":"autonomous decision-making","zh":"自主决策"},{"phrase":"autonomous weapons","zh":"自主武器"},{"phrase":"remain autonomous","zh":"保持自治"},{"phrase":"autonomous agent","zh":"自主代理程序"}],"forms":[{"label":"原形","form":"autonomous"},{"label":"名词","form":"autonomy"},{"label":"副词","form":"autonomously"},{"label":"形容词（相关）","form":"autonomic"},{"label":"名词（自治论）","form":"autonomism"},{"label":"动词（使自治）","form":"autonomize"}],"derivatives":[{"word":"autonomy","pos":"n.","zh":"自治；自主权（把希腊语「自己的」与「法、规矩」合在一起，字面即「自己的法」）"},{"word":"autonomously","pos":"adv.","zh":"自主地；自行地（加副词词尾，指不受外部操控地运行）"},{"word":"autonomic","pos":"adj.","zh":"自主神经的；自动调节的（同源形容词，现代医学多用来指不受意识支配的神经系统）"},{"word":"autonomism","pos":"n.","zh":"自治主义（加表示「学说、倾向」的后缀）"},{"word":"autonomize","pos":"v.","zh":"使自治；使自主（加表示「使成为」的动词词尾）"},{"word":"autonomist","pos":"n.","zh":"自治主义者；主张自主者（加表示「从事者、主张者」的名词后缀）"}],"senses":[{"no":"01","title":"Self-governing in law","titleCN":"法律上的自治","definition":"of a region, institution or community, having the right to govern its own affairs","definitionCN":"指地区、机构或群体有权管理自身事务","example":"The autonomous region sets its own school curriculum.","exampleCN":"这个自治区自行制定学校课程。","why":"The Greek word literally means living under one's own law, so self-rule is its oldest sense.","whyCN":"这个希腊词字面就是按自己的法生活，因此自治是最古老的义项。"},{"no":"02","title":"Acting independently","titleCN":"独立自主地行动","definition":"able to act or decide without direction from another person or body","definitionCN":"无需他人或他机构指示即可行动或决定","example":"The research unit is autonomous in how it spends its grant.","exampleCN":"这个研究单位在如何使用经费上自主。","why":"From self-rule in law the word moved to self-direction in ordinary institutions.","whyCN":"这个词从法律上的自治，转到一般机构里的自行其是。"},{"no":"03","title":"Self-directed as a person","titleCN":"个人的自主","definition":"of a person, able to think and choose for oneself rather than being led","definitionCN":"指人能独立思考和选择，而非被人牵着走","example":"An autonomous learner asks the next question without being told.","exampleCN":"自主的学习者不用别人吩咐就会问下一个问题。","why":"Education and ethics both prize the person who can set a rule for himself.","whyCN":"教育与伦理都看重那个能替自己立规矩的人。"},{"no":"04","title":"Driverless in the physical world","titleCN":"无人驾驶","definition":"of a vehicle or machine, able to move and operate without a human driver","definitionCN":"指车辆或机器无需人驾驶即可移动与作业","example":"An autonomous tractor steers itself across the field and slows for the stones at the edge.","exampleCN":"这台无人驾驶的拖拉机自己穿过田地，遇到地边的石堆就减速。","why":"A machine that needs no hand on the wheel is self-governing in the most literal way.","whyCN":"不需要手扶方向盘的机器，是最字面意义上的自治者。"},{"no":"05","title":"A self-running system","titleCN":"自行运转的系统","definition":"of software or a system, able to monitor its own state and act without a human in the loop","definitionCN":"指软件或系统能监测自身状态并在无人介入时行动","example":"The autonomous system rerouted traffic when the sensor failed.","exampleCN":"传感器失效时，这套自主系统重新规划了车流。","why":"Computing took the word for loops that close on themselves, a small republic of code.","whyCN":"计算机领域用这个词指自我闭合的循环，是一小块代码的自治体。"},{"no":"06","title":"Moral self-legislation","titleCN":"道德上的自我立法","definition":"in philosophy, the capacity of a rational being to give itself its own moral law","definitionCN":"在哲学中，指理性存在者替自己立下道德法则的能力","example":"Kant placed autonomy at the centre of moral worth.","exampleCN":"康德把自律置于道德价值的中心。","why":"The Greek image of giving oneself a law became, in ethics, the ground of dignity.","whyCN":"为自己立法的希腊意象，在伦理学里成了尊严的根据。"},{"no":"07","title":"A self-governing agent","titleCN":"自主的智能体","definition":"in artificial intelligence, an agent that pursues goals without continuous instruction","definitionCN":"在人工智能中，指无需持续指令即可追求目标的智能体","example":"The autonomous agent books the tickets and confirms them itself.","exampleCN":"这个自主代理自己订票并自己确认。","why":"Software agents were named after political self-rule, a joke that became a technical term.","whyCN":"软件代理借用了政治上的自治，这个玩笑后来成了技术术语。"},{"no":"08","title":"Weapons that choose","titleCN":"会自行选择的武器","definition":"of a weapon system, able to select and engage targets without human decision","definitionCN":"指武器系统能不经人决定就选择并攻击目标","example":"Talks on autonomous weapons stalled over the question of accountability.","exampleCN":"关于自主武器的谈判卡在责任归属问题上。","why":"When the machine picks the target, the word stops being neutral and becomes a warning.","whyCN":"当机器自己挑目标，这个词就不再中性，而成了警告。"},{"no":"09","title":"Not the same as automatic","titleCN":"与「自动」不同","definition":"governed by its own rules rather than merely following a fixed mechanical sequence","definitionCN":"按自身规则行事，而不只是执行固定的机械序列","example":"A thermostat is automatic; a system that rewrites its own rules is autonomous.","exampleCN":"恒温器是自动的；能改写自身规则的系统才是自主的。","why":"Automatic comes from a Greek word for acting of itself, but only autonomy implies law of one's own.","whyCN":"「自动」出自希腊语「自行动作」，但只有「自主」才含有自己的法之意。"}],"etymology":{"intro":{"en":"Autonomous comes from Greek autonomos, 'living under one's own laws', from autos 'self' and nomos 'law or custom'. The formation is clear; the exact date of its English entry is uncertain.","cn":"autonomous 出自希腊语 autonomos「按自己的法生活」，由 autos「自己」与 nomos「法、习俗」构成。构词清楚，进入英语的确切年代不确定。"},"items":[{"era":"GREEK AUTOS","en":"Autos meant self or the same, and it is the source of auto- in automatic, autobiography and automobile.","cn":"autos 意为自身、同一，是 automatic、autobiography 与 automobile 中 auto- 的来源。"},{"era":"GREEK NOMOS","en":"Nomos meant law, custom or usage, and it also stands behind economy, astronomy and taxonomy.","cn":"nomos 意为法、习俗、惯例，economy、astronomy 与 taxonomy 也由它而来。"},{"era":"AUTONOMOS","en":"The compound described a city or people living under its own laws rather than under an outside ruler.","cn":"这个复合词描述按自己的法而非按外来统治者之法治生活的城邦或民族。"},{"era":"CITY-STATES","en":"Greek politics made autonomy a claim of cities, and the word entered political argument before philosophy used it.","cn":"希腊政治使自治成为城邦的主张，这个词先进入政治论辩，后被哲学使用。"},{"era":"KANT","en":"Kant gave autonomy a moral sense, the rational will legislating for itself, which is still the philosophical anchor.","cn":"康德赋予自律道德含义，即理性意志替自己立法，这仍是哲学上的锚点。"},{"era":"MACHINES","en":"In the twentieth century the word was applied to vehicles and software, extending self-rule from cities to machines.","cn":"二十世纪，这个词被用于车辆与软件，把自治从城邦扩展到机器。"}]},"similar":{"note":{"en":"The first group shares the self or law root or looks close; the second group holds the related words that are routinely confused with autonomous.","cn":"第一组或共享「自己」或「法」的词根，或字形相近；第二组是常与 autonomous 混淆的相关词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"autonomy","ipa":"/ɔːˈtɒnəmi/","tag":"same root","definition":"The noun: the right or condition of self-government.","definitionCN":"名词：自治的权利或状态。"},{"word":"autonomously","ipa":"/ɔːˈtɒnəməsli/","tag":"same root","definition":"The adverb for acting without outside control.","definitionCN":"副词：不受外部控制地行动。"},{"word":"autonomic","ipa":"/ˌɔːtəˈnɒmɪk/","tag":"same root","definition":"Of the nervous system that regulates the body without conscious control.","definitionCN":"指不受意识支配、自行调节身体的神经系统。"},{"word":"automatic","ipa":"/ˌɔːtəˈmætɪk/","tag":"different root","definition":"Working by itself mechanically; it shares autos but its second half means acting of itself, not law.","definitionCN":"机械地自行工作；共享「自己」，后半却意为自行动作而非法。"},{"word":"anonymous","ipa":"/əˈnɒnɪməs/","tag":"different root","definition":"Nameless; it looks close but comes from a word meaning name.","definitionCN":"无名的；字形相近，却出自意为「名字」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"independent","ipa":"/ˌɪndɪˈpendənt/","tag":"near meaning","definition":"Not controlled by another, the everyday word for the same idea.","definitionCN":"不受他人控制，是同一意思的日常说法。"},{"word":"self-governing","ipa":"/ˌself ˈɡʌvənɪŋ/","tag":"near meaning","definition":"Ruling itself, the plain English equivalent of the political sense.","definitionCN":"自我治理，是政治义项最朴素的英语对应。"},{"word":"driverless","ipa":"/ˈdraɪvələs/","tag":"near meaning","definition":"Without a human driver, the narrow transport sense.","definitionCN":"无人类驾驶，是交通领域的窄义。"},{"word":"sovereign","ipa":"/səˈvərɪn/","tag":"near meaning","definition":"Holding supreme authority, stronger and more legal than autonomous.","definitionCN":"握有最高权力，比 autonomous 更强、更法律化。"},{"word":"self-directed","ipa":"/ˌself dəˈrektɪd/","tag":"near meaning","definition":"Setting one's own course, the personal sense without the legal weight.","definitionCN":"自己定方向，是个人层面的意思，没有法律分量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real self and law roots, the real family and real fixed phrases.","cn":"正常联想使用真实的「自己」与「法」词根、真实词族与真实固定搭配。"},"normal":[{"en":"Autos is self and nomos is law, so autonomous means living under one's own law.","cn":"前者是自己，后者是法，合起来就是按自己的法生活。"},{"en":"The family runs autonomy, autonomous, autonomously, autonomic and autonomism.","cn":"同族词有 autonomy、autonomous、autonomously、autonomic 与 autonomism。"},{"en":"Fixed phrases mark the uses: autonomous region, autonomous vehicle, autonomous system, autonomous learning.","cn":"固定说法标出用法：自治区、无人驾驶车辆、自主系统、自主学习。"},{"en":"The word has three lines: a region governs itself, a person directs himself, a machine drives itself.","cn":"这个词有三条线：地区自治、个人自主、机器自驾。"},{"en":"Keep it apart from automatic, which only means working by itself.","cn":"要与「自动」分开，后者只是自行工作。"}],"abstract":[{"en":"Autonomy is not the absence of rules but the presence of one's own.","cn":"自主不是没有规则，而是有一套自己的规则。"},{"en":"A machine that governs itself raises the oldest political question in a new body.","cn":"自行治理的机器，把最古老的政治问题装进了一具新的身体。"},{"en":"Self-rule is a burden before it is a freedom.","cn":"自治先是负担，然后才是自由。"}]},"examples":[{"en":"The province became autonomous after the treaty.","cn":"条约签订后，这个省取得自治。"},{"en":"Autonomous vehicles still struggle with unmapped roads.","cn":"无人驾驶车辆在未测绘的道路上仍吃力。"},{"en":"She encouraged autonomous work rather than close supervision.","cn":"她鼓励自主工作，而不是紧盯着管。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「奥托诺默斯」——自己给自己定规矩，自己走自己的路：自治的、自主的","word":"autonomous"},"root":"希腊语 autonomos「按自己的法生活」← autos「自己」＋ nomos「法、习俗」；nomos 另见于 economy、astronomy、taxonomy。政治义先出，康德赋予道德自律义，二十世纪扩展到无人驾驶车辆与自主软件系统。进入英语确切年代不确定。","sensesIntro":{"en":"Nine senses follow one self-made law: a self-governing region, an independent institution, a self-directed person, a driverless machine, a self-running system, moral self-legislation, a software agent, a weapon that chooses, and the contrast with merely automatic.","cn":"九个义项沿着同一部自订的法：自治地区、独立机构、自主的个人、无人驾驶的机器、自行运转的系统、道德的自我立法、软件智能体、自行选择的武器，以及与「自动」的区别。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tractor with an empty cab turning a corner by itself, steadier than a human hand.","cn":"核心意象：空着驾驶室的拖拉机自己转过弯来，比人手还稳。"},"chain":["SELF","LAW","OWN LAW","SELF-GOVERNMENT","SELF-DIRECTION","SELF-DRIVING"],"branches":[{"senses":"01 · 02","en":"THE GOVERNING BODY: a region or institution that sets its own rules and spends its own budget.","cn":"治理的主体：自订规则、自支预算的地区或机构。"},{"senses":"03 · 06","en":"THE SELF-LEGISLATING PERSON: a learner who asks the next question, and a will that gives itself a moral law.","cn":"自我立法的个人：自己问出下一个问题的学习者，以及替自己立道德法的意志。"},{"senses":"04 · 05","en":"THE MACHINE THAT RUNS ITSELF: a driverless tractor, and software that acts with no hand in the loop.","cn":"自行运转的机器：无人驾驶的拖拉机，以及无人介入即行动的软件。"},{"senses":"07 · 08","en":"THE AGENT AND THE WEAPON: a program pursuing a goal, and a system that picks its own target.","cn":"智能体与武器：追求目标的程序，以及自己挑选目标的系统。"},{"senses":"09","en":"THE DISTINCTION: automatic follows a fixed sequence; autonomous follows a law of its own.","cn":"那条区别：自动执行固定序列，自主遵循自己的法。"}]},"affixes":{"intro":{"en":"Autonomous is a Greek compound of self and law, with a family that runs from politics through philosophy into robotics.","cn":"autonomous 是「自己」与「法」的希腊复合词，其词族从政治经哲学一直延伸到机器人技术。"},"latinIntro":{"en":"The source is Greek rather than Latin: autos and nomos, with the adjective ending -os becoming -ous in English.","cn":"来源是希腊语而非拉丁语：autos 与 nomos，形容词词尾 -os 在英语中变成 -ous。"},"items":[{"word":"autonomous","structure":"Greek autonomos","meaning":"living under one's own law","meaningCN":"按自己的法生活","example":"The adjective covers regions, persons and machines.","exampleCN":"这个形容词覆盖地区、个人与机器。"},{"word":"autos","structure":"Greek pronoun","meaning":"self, the same","meaningCN":"自己；同一","example":"It supplies the auto- in many English words.","exampleCN":"它提供许多英语词里的 auto-。"},{"word":"nomos","structure":"Greek noun","meaning":"law, custom","meaningCN":"法；习俗","example":"It also stands behind economy and astronomy.","exampleCN":"economy 与 astronomy 也由它而来。"},{"word":"autonomy","structure":"Greek autonomia","meaning":"self-government","meaningCN":"自治","example":"The noun names the condition rather than the holder.","exampleCN":"这个名词指状态而非持有者。"},{"word":"-ous","structure":"Latin -osus, matching Greek -os","meaning":"full of, having the quality","meaningCN":"具有……性质的","example":"It builds autonomous, famous and dangerous.","exampleCN":"它构成自治的、著名的与危险的等词。"},{"word":"-ly","structure":"English suffix","meaning":"in the manner of","meaningCN":"以……方式","example":"It builds autonomously, meaning without outside control.","exampleCN":"它构成 autonomously，意为不受外部控制。"},{"word":"-ic","structure":"Greek -ikos","meaning":"relating to","meaningCN":"与……有关的","example":"It builds autonomic, the medical adjective.","exampleCN":"它构成 autonomic，即医学形容词。"},{"word":"-ism","structure":"Greek -ismos","meaning":"doctrine or tendency","meaningCN":"学说；倾向","example":"It builds autonomism, a political stance.","exampleCN":"它构成 autonomism，一种政治立场。"},{"word":"-ize","structure":"Greek -izein","meaning":"to make","meaningCN":"使成为","example":"It builds autonomize, to make self-governing.","exampleCN":"它构成 autonomize，意为使自治。"}],"latinEntries":[{"word":"autonomos","structure":"autos (self) + nomos (law); Greek autonomos","meaning":"living under one's own law","meaningCN":"按自己的法生活","example":"Greek autonomos means living under one's own law.","exampleCN":"希腊语 autonomos 意为按自己的法生活。"},{"word":"autos","structure":"Greek pronoun autos (self)","meaning":"self","meaningCN":"自己","example":"Greek autos means self, and gives the auto- of English.","exampleCN":"希腊语 autos 意为自己，并给出英语的 auto-。"},{"word":"nomos","structure":"Greek noun nomos (law, custom)","meaning":"law, custom","meaningCN":"法；习俗","example":"Greek nomos means law or custom, and gives -nomy in English.","exampleCN":"希腊语 nomos 意为法、习俗，并给出英语的 -nomy。"}],"derivatives":[{"word":"autonomy","pos":"n.","zh":"自治；自主权"},{"word":"autonomously","pos":"adv.","zh":"自主地；自行地"},{"word":"autonomic","pos":"adj.","zh":"自主神经的"},{"word":"autonomism","pos":"n.","zh":"自治主义"},{"word":"autonomize","pos":"v.","zh":"使自治；使自主"}]}}]);
